1	//! Batch payload encode/decode per Rollup-1 spec §8.1.
2	//!
3	//! ```text
4	//!   payload := tagByte ‖ rlp([
5	//!     blockTxCounts,    # legacy tags: list of uint16, length ==
6	//!                       # toBlock - fromBlock + 1
7	//!                       # entry i = number of retained txs in block
8	//!                       # 0 means empty block
9	//!     transactions,     # list of bytes, block-major order
10	//!                       # the first blockTxCounts[0] entries belong to block fromBlock,
11	//!                       # the next blockTxCounts[1] entries to block fromBlock+1, etc.
12	//!                       # each entry is a standard RLP-encoded EVM tx
13	//!     l2_entries,       # list of bytes — ABI-encoded L2-shape
14	//!                       # ExecutionEntry the L2 system tx
15	//!                       # (executeIncomingCrossChainCall) consumes.
16	//!                       # Empty for arbitrary-call batches; populated
17	//!                       # for value-bearing (deposit/withdrawal) ones.
18	//!     outboundGroupSizes, # tag 0x01 only: number of source entries
19	//!                         # consumed by each outbound user transaction
20	//!   ])
21	//!
22	//!   tagByte:
23	//!     0x00  legacy three-field body
24	//!     0x01  grouped four-field body
25	//!     0x02  self-contained blocks: full canonical block RLP values replace
26	//!           the separate block counts and transactions fields; decoded counts
27	//!           and transactions are derived from those exact block bodies
28	//! ```
29	//!
30	//! `fromBlock` and `toBlock` are **not** in this encoding. Callers supply the
31	//! absolute block range from their surrounding protocol context; this codec
32	//! only preserves the number of covered blocks and each block's transaction
33	//! count.
34	//!
35	//! Decode invariants enforced (§8.3):
36	//!  - `sum(blockTxCounts) == len(transactions)`
37	//!  - `blockTxCounts[i]` fits in `u16`
38	//!
39	//! The codec does **not** validate per-tx fields (§8.4 — that's STF-level).
40	
41	#![cfg_attr(not(test), warn(unused_crate_dependencies))]
42	
43	use alloy_rlp::{Decodable, Encodable};
44	
45	mod block_size;
46	pub use block_size::BlockDaSizer;
47	
48	/// A raw EIP-2718 signed transaction. Opaque to this crate.
49	pub type RawTx = Vec<u8>;
50	
51	/// Tag byte for the legacy three-field calldata format.
52	pub const TAG_CALLDATA: u8 = 0x00;
53	/// Calldata format carrying explicit outbound-root counts per signed user tx.
54	pub const TAG_GROUPED_CALLDATA: u8 = 0x01;
55	/// Self-contained format carrying each complete L2 block as consensus RLP.
56	pub const TAG_SELF_CONTAINED_BLOCKS: u8 = 0x02;
57	
58	/// Convenience [`Result`] alias.
59	pub type CodecResult<T> = Result<T, CodecError>;
60	
61	/// Error returned by encode / decode.
62	#[derive(Debug, thiserror::Error)]
63	pub enum CodecError {
64	    #[error("encoded payload length exceeds addressable memory")]
65	    LengthOverflow,
66	    /// Payload was empty or missing the tag byte.
67	    #[error("payload too short ({0} bytes)")]
68	    TooShort(usize),
69	    /// Tag byte didn't match the current format.
70	    #[error(
71	        "unsupported tag byte 0x{0:02x}; expected 0x{TAG_CALLDATA:02x}, \
72	         0x{TAG_GROUPED_CALLDATA:02x}, or 0x{TAG_SELF_CONTAINED_BLOCKS:02x}"
73	    )]
74	    UnsupportedTag(u8),
75	    /// A self-contained block is not exact canonical Ethereum block RLP.
76	    #[error("invalid self-contained block {index}: {reason}")]
77	    InvalidBlock { index: usize, reason: String },
78	    /// Adjacent self-contained blocks do not form one hash-linked sequence.
79	    #[error("self-contained block {index} is not contiguous with its predecessor")]
80	    NonContiguousBlock { index: usize },
81	    /// RLP decoding failed.
82	    #[error("rlp decode failed: {0}")]
83	    Rlp(#[from] alloy_rlp::Error),
84	    /// Bytes remained after the single tagged RLP body.
85	    #[error("payload has {0} trailing bytes")]
86	    TrailingBytes(usize),
87	    /// A `blockTxCounts[i]` didn't fit in `u16`.
88	    #[error("block tx count {0} at index {1} exceeds u16::MAX")]
89	    BlockTxCountOverflow(u64, usize),
90	    /// `sum(blockTxCounts) != transactions.len()`.
91	    #[error("tx-count mismatch: sum(blockTxCounts) = {expected}, transactions.len() = {got}")]
92	    TxCountMismatch { expected: u64, got: u64 },
93	}
94	
95	/// A decoded batch payload.
96	#[derive(Debug, Clone, PartialEq, Eq)]
97	pub struct DecodedBatch {
98	    /// Per-block transaction counts. Length = number of L2 blocks covered.
99	    ///
100	    /// For legacy tags these are the retained payload transactions. For the
101	    /// self-contained tag they count every transaction in the exact block body,
102	    /// including system transactions.
103	    pub block_tx_counts: Vec<u16>,
104	    /// Flat list of raw EIP-2718 signed transactions in block-major order.
105	    pub transactions: Vec<RawTx>,
106	    /// L2-shape `ExecutionEntry` bytes (ABI-encoded). Empty for
107	    /// arbitrary-call batches; populated for value-bearing ones
108	    /// (deposits/withdrawals), where the L1 settlement entry does not
109	    /// contain the exact L2 execution-table shape followers must rebuild.
110	    pub l2_entries: Vec<Vec<u8>>,
111	    /// Number of outbound source roots consumed by each terminal-block user
112	    /// transaction. Empty for legacy tag-0 payloads.
113	    pub outbound_group_sizes: Vec<u16>,
114	    /// Canonical full-block RLP, one value per block. Empty for legacy tags.
115	    ///
116	    /// This commits every original header field, transaction, ommer and
117	    /// withdrawal needed to reproduce and hash the exact block. Receipts and
118	    /// execution requests are deterministic STF outputs and are not duplicated.
119	    pub block_rlps: Vec<Vec<u8>>,
120	}
121	
122	impl DecodedBatch {
123	    /// Number of L2 blocks covered.
124	    #[must_use]
125	    pub fn block_count(&self) -> usize {
126	        self.block_tx_counts.len()
127	    }
128	}
129	
130	/// Encode the calldata payload: per-block tx vectors plus L2-shape
131	/// entries.
132	///
133	/// `blocks[i]` is the list of raw signed transactions for the i-th L2
134	/// block in the range. `l2_entries[i]` is one ABI-encoded
135	/// `ExecutionEntrySol`; pass `&[]` for arbitrary-call batches that
136	/// don't need follower-side L2 system-tx reconstruction.
137	///
138	/// # Errors
139	///
140	/// - [`CodecError::BlockTxCountOverflow`] if any block has > `u16::MAX` txs.
141	pub fn encode(blocks: &[Vec<RawTx>], l2_entries: &[Vec<u8>]) -> CodecResult<Vec<u8>> {
142	    let mut block_tx_counts: Vec<u16> = Vec::with_capacity(blocks.len());
143	    for (i, b) in blocks.iter().enumerate() {
144	        let n = u64::try_from(b.len()).unwrap_or(u64::MAX);
145	        let cnt = u16::try_from(b.len()).map_err(|_| CodecError::BlockTxCountOverflow(n, i))?;
146	        block_tx_counts.push(cnt);
147	    }
148	    let transactions: Vec<RawTx> = blocks.iter().flatten().cloned().collect();
149	    let body = Body {
150	        block_tx_counts,
151	        transactions,
152	        l2_entries: l2_entries.to_vec(),
153	    };
154	    let mut buf = Vec::with_capacity(1 + body.length());
155	    buf.push(TAG_CALLDATA);
156	    body.encode(&mut buf);
157	    Ok(buf)
158	}
159	
160	/// Encode the grouped calldata format used when one signed outbound user
161	/// transaction consumes one or more source roots.
162	pub fn encode_grouped(
163	    blocks: &[Vec<RawTx>],
164	    l2_entries: &[Vec<u8>],
165	    outbound_group_sizes: &[u16],
166	) -> CodecResult<Vec<u8>> {
167	    let mut block_tx_counts: Vec<u16> = Vec::with_capacity(blocks.len());
168	    for (i, b) in blocks.iter().enumerate() {
169	        let n = u64::try_from(b.len()).unwrap_or(u64::MAX);
170	        block_tx_counts
171	            .push(u16::try_from(b.len()).map_err(|_| CodecError::BlockTxCountOverflow(n, i))?);
172	    }
173	    let body = GroupedBody {
174	        block_tx_counts,
175	        transactions: blocks.iter().flatten().cloned().collect(),
176	        l2_entries: l2_entries.to_vec(),
177	        outbound_group_sizes: outbound_group_sizes.to_vec(),
178	    };
179	    let mut buf = Vec::with_capacity(1 + body.length());
180	    buf.push(TAG_GROUPED_CALLDATA);
181	    body.encode(&mut buf);
182	    Ok(buf)
183	}
184	
185	/// Encode the self-contained chain-operations profile.
186	///
187	/// Every element is one complete canonical Ethereum block RLP. Blocks must be
188	/// number- and parent-hash-contiguous. Transactions are recovered from those
189	/// block bodies during decoding rather than duplicated in a parallel field.
190	pub fn encode_self_contained(
191	    block_rlps: &[Vec<u8>],
192	    l2_entries: &[Vec<u8>],
193	    outbound_group_sizes: &[u16],
194	) -> CodecResult<Vec<u8>> {
195	    decode_self_contained_blocks(block_rlps)?;
196	    let body = SelfContainedBody {
197	        blocks: block_rlps.to_vec(),
198	        l2_entries: l2_entries.to_vec(),
199	        outbound_group_sizes: outbound_group_sizes.to_vec(),
200	    };
201	    let mut buf = Vec::with_capacity(1 + body.length());
202	    buf.push(TAG_SELF_CONTAINED_BLOCKS);
203	    body.encode(&mut buf);
204	    Ok(buf)
205	}
206	
207	/// Size of the existing self-contained encoding from incrementally measured
208	/// RLP item lengths. Each input is the SUM of the individual elements'
209	/// `Encodable::length()` values, without its enclosing list header. In
210	/// particular, use the existing `Vec<u8>` representation for block RLPs;
211	/// changing it to byte strings would change the wire format.
212	pub fn self_contained_payload_len(
213	    block_items: usize,
214	    entry_items: usize,
215	    group_items: usize,
216	) -> CodecResult<usize> {
217	    fn list_len(payload_length: usize) -> CodecResult<usize> {
218	        payload_length
219	            .checked_add(
220	                alloy_rlp::Header {
221	                    list: true,
222	                    payload_length,
223	                }
224	                .length(),
225	            )
226	            .ok_or(CodecError::LengthOverflow)
227	    }
228	    let body = list_len(block_items)?
229	        .checked_add(list_len(entry_items)?)
230	        .and_then(|length| length.checked_add(list_len(group_items).ok()?))
231	        .ok_or(CodecError::LengthOverflow)?;
232	    list_len(body)?
233	        .checked_add(1)
234	        .ok_or(CodecError::LengthOverflow)
235	}
236	
237	/// Decode a calldata payload.
238	///
239	/// # Errors
240	///
241	/// - [`CodecError::TooShort`] if `payload` is empty.
242	/// - [`CodecError::UnsupportedTag`] if the leading byte is not a supported tag.
243	/// - [`CodecError::Rlp`] if the RLP body is malformed.
244	/// - [`CodecError::TrailingBytes`] if bytes remain after the RLP body.
245	/// - [`CodecError::TxCountMismatch`] if `sum(blockTxCounts) != transactions.len()`.
246	pub fn decode(payload: &[u8]) -> CodecResult<DecodedBatch> {
247	    let Some((&tag, rest)) = payload.split_first() else {
248	        return Err(CodecError::TooShort(0));
249	    };
250	    let mut encoded_body = rest;
251	    let (block_tx_counts, transactions, l2_entries, outbound_group_sizes, block_rlps) = match tag {
252	        TAG_CALLDATA => {
253	            let body = Body::decode(&mut encoded_body)?;
254	            (
255	                body.block_tx_counts,
256	                body.transactions,
257	                body.l2_entries,
258	                Vec::new(),
259	                Vec::new(),
260	            )
261	        }
262	        TAG_GROUPED_CALLDATA => {
263	            let body = GroupedBody::decode(&mut encoded_body)?;
264	            (
265	                body.block_tx_counts,
266	                body.transactions,
267	                body.l2_entries,
268	                body.outbound_group_sizes,
269	                Vec::new(),
270	            )
271	        }
272	        TAG_SELF_CONTAINED_BLOCKS => {
273	            let body = SelfContainedBody::decode(&mut encoded_body)?;
274	            let (block_tx_counts, transactions) = decode_self_contained_blocks(&body.blocks)?;
275	            (
276	                block_tx_counts,
277	                transactions,
278	                body.l2_entries,
279	                body.outbound_group_sizes,
280	                body.blocks,
281	            )
282	        }
283	        _ => return Err(CodecError::UnsupportedTag(tag)),
284	    };
285	    if !encoded_body.is_empty() {
286	        return Err(CodecError::TrailingBytes(encoded_body.len()));
287	    }
288	    let expected: u64 = block_tx_counts.iter().map(|n| u64::from(*n)).sum();
289	    let got = transactions.len() as u64;
290	    if expected != got {
291	        return Err(CodecError::TxCountMismatch { expected, got });
292	    }
293	    Ok(DecodedBatch {
294	        block_tx_counts,
295	        transactions,
296	        l2_entries,
297	        outbound_group_sizes,
298	        block_rlps,
299	    })
300	}
301	
302	#[derive(Debug, alloy_rlp::RlpEncodable, alloy_rlp::RlpDecodable)]
303	struct Body {
304	    block_tx_counts: Vec<u16>,
305	    transactions: Vec<RawTx>,
306	    l2_entries: Vec<Vec<u8>>,
307	}
308	
309	#[derive(Debug, alloy_rlp::RlpEncodable, alloy_rlp::RlpDecodable)]
310	struct GroupedBody {
311	    block_tx_counts: Vec<u16>,
312	    transactions: Vec<RawTx>,
313	    l2_entries: Vec<Vec<u8>>,
314	    outbound_group_sizes: Vec<u16>,
315	}
316	
317	#[derive(Debug, alloy_rlp::RlpEncodable, alloy_rlp::RlpDecodable)]
318	struct SelfContainedBody {
319	    blocks: Vec<Vec<u8>>,
320	    l2_entries: Vec<Vec<u8>>,
321	    outbound_group_sizes: Vec<u16>,
322	}
323	
324	fn decode_self_contained_blocks(block_rlps: &[Vec<u8>]) -> CodecResult<(Vec<u16>, Vec<RawTx>)> {
325	    let mut block_tx_counts = Vec::with_capacity(block_rlps.len());
326	    let mut transactions = Vec::new();
327	    let mut previous: Option<(u64, alloy_primitives::B256)> = None;
328	    for (index, encoded) in block_rlps.iter().enumerate() {
329	        let block = alloy_rlp::decode_exact::<reth_ethereum_primitives::Block>(encoded).map_err(
330	            |error| CodecError::InvalidBlock {
331	                index,
332	                reason: error.to_string(),
333	            },
334	        )?;
335	        if alloy_rlp::encode(&block) != *encoded {
336	            return Err(CodecError::InvalidBlock {
337	                index,
338	                reason: "non-canonical RLP".to_owned(),
339	            });
340	        }
341	        if let Some((previous_number, previous_hash)) = previous
342	            && (block.header.number != previous_number.saturating_add(1)
343	                || block.header.parent_hash != previous_hash)
344	        {
345	            return Err(CodecError::NonContiguousBlock { index });
346	        }
347	        let count = u16::try_from(block.body.transactions.len()).map_err(|_| {
348	            CodecError::BlockTxCountOverflow(block.body.transactions.len() as u64, index)
349	        })?;
350	        block_tx_counts.push(count);
351	        transactions.extend(
352	            block
353	                .body
354	                .transactions
355	                .iter()
356	                .map(alloy_eips::Encodable2718::encoded_2718),
357	        );
358	        previous = Some((block.header.number, block.header.hash_slow()));
359	    }
360	    Ok((block_tx_counts, transactions))
361	}
