363	#[cfg(test)]
364	mod tests {
365	    use super::*;
366	
367	    fn tx(byte: u8, n: usize) -> RawTx {
368	        vec![byte; n]
369	    }
370	
371	    #[test]
372	    fn roundtrip_single_block_with_two_txs() {
373	        let blocks = vec![vec![tx(0xa1, 64), tx(0xa2, 32)]];
374	        let bytes = encode(&blocks, &[]).unwrap();
375	        let decoded = decode(&bytes).unwrap();
376	        assert_eq!(decoded.block_tx_counts, vec![2u16]);
377	        assert_eq!(decoded.transactions.len(), 2);
378	        assert!(decoded.l2_entries.is_empty());
379	    }
380	
381	    #[test]
382	    fn roundtrip_multi_block_with_empties() {
383	        let blocks = vec![
384	            vec![tx(0x01, 8)],
385	            vec![],
386	            vec![tx(0x02, 16), tx(0x03, 16), tx(0x04, 16)],
387	            vec![],
388	            vec![tx(0x05, 24)],
389	        ];
390	        let bytes = encode(&blocks, &[]).unwrap();
391	        let decoded = decode(&bytes).unwrap();
392	        assert_eq!(decoded.block_tx_counts, vec![1, 0, 3, 0, 1]);
393	        assert_eq!(decoded.transactions.len(), 5);
394	        assert_eq!(decoded.block_count(), 5);
395	    }
396	
397	    #[test]
398	    fn tag_byte_is_first_byte() {
399	        let bytes = encode(&[vec![]], &[]).unwrap();
400	        assert_eq!(bytes[0], TAG_CALLDATA);
401	    }
402	
403	    #[test]
404	    fn block_overflow_rejected_on_encode() {
405	        let blocks = vec![vec![tx(0, 1); usize::from(u16::MAX) + 1]];
406	        let err = encode(&blocks, &[]).unwrap_err();
407	        assert!(matches!(err, CodecError::BlockTxCountOverflow(_, 0)));
408	    }
409	
410	    #[test]
411	    fn too_short_rejected_on_decode() {
412	        assert!(matches!(decode(&[]).unwrap_err(), CodecError::TooShort(_)));
413	    }
414	
415	    #[test]
416	    fn unsupported_tag_rejected_on_decode() {
417	        assert!(matches!(
418	            decode(&[0xff]).unwrap_err(),
419	            CodecError::UnsupportedTag(0xff)
420	        ));
421	    }
422	
423	    #[test]
424	    fn corrupt_rlp_rejected_on_decode() {
425	        assert!(matches!(
426	            decode(&[TAG_CALLDATA, 0x99, 0x99]).unwrap_err(),
427	            CodecError::Rlp(_)
428	        ));
429	    }
430	
431	    #[test]
432	    fn trailing_bytes_rejected_on_decode() {
433	        for mut bytes in [
434	            encode(&[vec![]], &[]).unwrap(),
435	            encode_grouped(&[vec![]], &[], &[]).unwrap(),
436	        ] {
437	            bytes.extend_from_slice(&[0xde, 0xad]);
438	            assert!(matches!(
439	                decode(&bytes).unwrap_err(),
440	                CodecError::TrailingBytes(2)
441	            ));
442	        }
443	    }
444	
445	    #[test]
446	    fn roundtrip_with_l2_entries() {
447	        // Value-bearing batch: L2 entries survive the round-trip
448	        // alongside per-block tx data.
449	        let blocks = vec![vec![], vec![tx(0xa1, 32)], vec![]];
450	        let l2_entries: Vec<Vec<u8>> = vec![
451	            vec![0xde, 0xad, 0xbe, 0xef],
452	            vec![0xca, 0xfe, 0xba, 0xbe, 0x00, 0x11, 0x22, 0x33],
453	        ];
454	        let bytes = encode(&blocks, &l2_entries).unwrap();
455	        assert_eq!(bytes[0], TAG_CALLDATA);
456	        let decoded = decode(&bytes).unwrap();
457	        assert_eq!(decoded.block_tx_counts, vec![0u16, 1u16, 0u16]);
458	        assert_eq!(decoded.transactions.len(), 1);
459	        assert_eq!(decoded.l2_entries, l2_entries);
460	    }
461	
462	    #[test]
463	    fn grouped_roundtrip_preserves_outbound_root_counts() {
464	        let blocks = vec![vec![tx(0xa1, 32), tx(0xa2, 32)]];
465	        let bytes =
466	            encode_grouped(&blocks, &[vec![0x01], vec![0x02], vec![0x03]], &[2, 1]).unwrap();
467	        assert_eq!(bytes[0], TAG_GROUPED_CALLDATA);
468	        let decoded = decode(&bytes).unwrap();
469	        assert_eq!(decoded.outbound_group_sizes, [2, 1]);
470	        assert_eq!(decoded.l2_entries.len(), 3);
471	    }
472	
473	    fn self_contained_blocks() -> Vec<Vec<u8>> {
474	        use alloy_consensus::{BlockBody, Header};
475	
476	        let first = reth_ethereum_primitives::Block {
477	            header: Header {
478	                number: 10,
479	                timestamp: 123,
480	                beneficiary: alloy_primitives::Address::repeat_byte(0x11),
481	                extra_data: alloy_primitives::Bytes::from_static(b"eez-test"),
482	                ..Default::default()
483	            },
484	            body: BlockBody::default(),
485	        };
486	        let second = reth_ethereum_primitives::Block {
487	            header: Header {
488	                parent_hash: first.header.hash_slow(),
489	                number: 11,
490	                timestamp: 125,
491	                beneficiary: alloy_primitives::Address::repeat_byte(0x22),
492	                ..Default::default()
493	            },
494	            body: BlockBody::default(),
495	        };
496	        vec![alloy_rlp::encode(first), alloy_rlp::encode(second)]
497	    }
498	
499	    #[test]
500	    fn incremental_size_matches_existing_encoding_including_metadata() {
501	        let blocks = self_contained_blocks();
502	        for size in [0, 1, 55, 56, 127, 128, 255, 256, 1024] {
503	            let entries = vec![vec![0; size], vec![255; size]];
504	            let groups = vec![1u16, 127, 128, 256];
505	            let actual = encode_self_contained(&blocks, &entries, &groups).unwrap();
506	            let estimated = self_contained_payload_len(
507	                blocks.iter().map(Encodable::length).sum(),
508	                entries.iter().map(Encodable::length).sum(),
509	                groups.iter().map(Encodable::length).sum(),
510	            )
511	            .unwrap();
512	            assert_eq!(estimated, actual.len());
513	        }
514	        let actual = encode_self_contained(&blocks, &[], &[]).unwrap();
515	        assert_eq!(
516	            self_contained_payload_len(blocks.iter().map(Encodable::length).sum(), 0, 0).unwrap(),
517	            actual.len()
518	        );
519	        assert!(self_contained_payload_len(usize::MAX, 0, 0).is_err());
520	    }
521	
522	    #[test]
523	    fn self_contained_roundtrip_preserves_exact_blocks_and_metadata() {
524	        let blocks = self_contained_blocks();
525	        let entries = vec![vec![0xde, 0xad]];
526	        let encoded = encode_self_contained(&blocks, &entries, &[2]).unwrap();
527	        assert_eq!(encoded[0], TAG_SELF_CONTAINED_BLOCKS);
528	        let decoded = decode(&encoded).unwrap();
529	        assert_eq!(decoded.block_rlps, blocks);
530	        assert_eq!(decoded.block_tx_counts, [0, 0]);
531	        assert!(decoded.transactions.is_empty());
532	        assert_eq!(decoded.l2_entries, entries);
533	        assert_eq!(decoded.outbound_group_sizes, [2]);
534	    }
535	
536	    #[test]
537	    fn self_contained_blocks_must_be_hash_linked() {
538	        let mut blocks = self_contained_blocks();
539	        let mut second =
540	            alloy_rlp::decode_exact::<reth_ethereum_primitives::Block>(&blocks[1]).unwrap();
541	        second.header.parent_hash = alloy_primitives::B256::repeat_byte(0xff);
542	        blocks[1] = alloy_rlp::encode(second);
543	        assert!(matches!(
544	            encode_self_contained(&blocks, &[], &[]),
545	            Err(CodecError::NonContiguousBlock { index: 1 })
546	        ));
547	    }
548	}
