1	//! Conservative size of one block in the existing `Vec<Vec<u8>>` payload.
2	//! Unknown execution header fields are bounded; transaction encodings are exact.
3	
4	use alloy_consensus::Header;
5	use alloy_primitives::{Address, B64, B256, Bloom, Bytes, U256};
6	use alloy_rlp::Encodable;
7	
8	use crate::{CodecError, CodecResult};
9	
10	#[derive(Clone, Copy, Debug)]
11	pub struct BlockDaSizer {
12	    header_bytes: usize,
13	    transaction_bytes: usize,
14	    transaction_items: usize,
15	}
16	
17	fn prefix(bytes: usize) -> usize {
18	    alloy_rlp::Header {
19	        list: true,
20	        payload_length: bytes,
21	    }
22	    .length()
23	}
24	
25	impl BlockDaSizer {
26	    /// Bound every supported header field, including optional fields that may
27	    /// activate before the next boundary. EEZ supplies its fixed extra data and
28	    /// never produces ommers or nonempty withdrawals through ordinary sequencing.
29	    pub fn new(extra_data: &[u8]) -> Self {
30	        let header = Header {
31	            parent_hash: B256::repeat_byte(255),
32	            ommers_hash: B256::repeat_byte(255),
33	            beneficiary: Address::repeat_byte(255),
34	            state_root: B256::repeat_byte(255),
35	            transactions_root: B256::repeat_byte(255),
36	            receipts_root: B256::repeat_byte(255),
37	            logs_bloom: Bloom::repeat_byte(255),
38	            difficulty: U256::MAX,
39	            number: u64::MAX,
40	            gas_limit: u64::MAX,
41	            gas_used: u64::MAX,
42	            timestamp: u64::MAX,
43	            extra_data: Bytes::copy_from_slice(extra_data),
44	            mix_hash: B256::repeat_byte(255),
45	            nonce: B64::repeat_byte(255),
46	            base_fee_per_gas: Some(u64::MAX),
47	            withdrawals_root: Some(B256::repeat_byte(255)),
48	            blob_gas_used: Some(u64::MAX),
49	            excess_blob_gas: Some(u64::MAX),
50	            parent_beacon_block_root: Some(B256::repeat_byte(255)),
51	            requests_hash: Some(B256::repeat_byte(255)),
52	            block_access_list_hash: Some(B256::repeat_byte(255)),
53	            slot_number: Some(u64::MAX),
54	        };
55	        Self {
56	            header_bytes: header.length(),
57	            transaction_bytes: 0,
58	            transaction_items: 0,
59	        }
60	    }
61	
62	    /// The transaction's canonical **block-body RLP**, including a typed
63	    /// transaction's RLP string wrapper, rather than just its EIP-2718 envelope.
64	    pub fn with_transaction(&self, transaction_rlp: &[u8]) -> CodecResult<Self> {
65	        let items = transaction_rlp.iter().try_fold(0usize, |sum, byte| {
66	            sum.checked_add(byte.length())
67	                .ok_or(CodecError::LengthOverflow)
68	        })?;
69	        Ok(Self {
70	            header_bytes: self.header_bytes,
71	            transaction_bytes: self
72	                .transaction_bytes
73	                .checked_add(transaction_rlp.len())
74	                .ok_or(CodecError::LengthOverflow)?,
75	            transaction_items: self
76	                .transaction_items
77	                .checked_add(items)
78	                .ok_or(CodecError::LengthOverflow)?,
79	        })
80	    }
81	
82	    /// Upper bound including the enclosing byte-vector RLP list. Header and
83	    /// variable list-prefix bytes may each expand to two bytes in that format.
