18	pub(crate) enum DaPayloadError {
19	    #[error("batch callData does not decode: {reason}")]
20	    Decode { reason: String },
21	    #[error("batch callData has {trailing} trailing bytes")]
22	    TrailingBytes { trailing: usize },
