78	
79	const CALL_DATA_TAG: u8 = 0;
80	const GROUPED_CALL_DATA_TAG: u8 = 1;
81	const SELF_CONTAINED_BLOCKS_TAG: u8 = 2;
82	
83	/// Borrowed RLP-list bodies that advance as their items are verified.
84	///
85	/// Keeping slices into the original calldata avoids copying transactions and
86	/// effect sidecars supplied by an untrusted composer.
87	struct DaPayloadCursor<'a> {
88	    block_tx_counts: &'a [u8],
89	    transactions: &'a [u8],
90	    l2_entries: &'a [u8],
91	    outbound_group_sizes: Option<&'a [u8]>,
92	}
93	
94	impl<'a> DaPayloadCursor<'a> {
95	    fn decode(encoded_payload: &'a [u8]) -> Result<Self, DaPayloadError> {
96	        let Some((&tag, encoded_body)) = encoded_payload.split_first() else {
97	            return Err(invalid_da_payload("payload is empty"));
98	        };
99	        if tag != CALL_DATA_TAG && tag != GROUPED_CALL_DATA_TAG {
100	            return Err(invalid_da_payload(format!(
101	                "unsupported tag byte 0x{tag:02x}; expected 0x{CALL_DATA_TAG:02x} or 0x{GROUPED_CALL_DATA_TAG:02x}"
102	            )));
103	        }
104	
105	        let mut remainder = encoded_body;
106	        let mut body = decode_list(&mut remainder)?;
107	        if !remainder.is_empty() {
108	            return Err(DaPayloadError::TrailingBytes {
109	                trailing: remainder.len(),
110	            });
111	        }
112	
113	        let block_tx_counts = decode_list(&mut body)?;
114	        let transactions = decode_list(&mut body)?;
115	        let l2_entries = decode_list(&mut body)?;
116	        let outbound_group_sizes = if tag == GROUPED_CALL_DATA_TAG {
117	            Some(decode_list(&mut body)?)
118	        } else {
119	            None
120	        };
121	        if !body.is_empty() {
122	            return Err(invalid_da_payload("payload body has unexpected fields"));
123	        }
124	        Ok(Self {
125	            block_tx_counts,
126	            transactions,
127	            l2_entries,
128	            outbound_group_sizes,
129	        })
130	    }
131	}
132	
133	fn decode_list<'a>(input: &mut &'a [u8]) -> Result<&'a [u8], DaPayloadError> {
134	    Header::decode_bytes(input, true).map_err(|error| invalid_da_payload(error.to_string()))
135	}
136	
137	fn invalid_da_payload(reason: impl Into<String>) -> DaPayloadError {
138	    DaPayloadError::Decode {
139	        reason: reason.into(),
140	    }
141	}
142	
143	/// Bind the decoded batch's submitted DA payload to the validated window and
144	/// authorized effects.
145	///
146	/// The preceding blocks carry every transaction verbatim. In the terminal
147	/// settling block, system loads and inbound deliveries are omitted while
148	/// outbound user transactions remain. Each effect has one exact, ordered
149	/// derivation sidecar, and the resulting mixed Sync sequence is reconstructed
150	/// byte for byte.
151	pub(crate) fn verify_da_payload(
152	    encoded_payload: &[u8],
153	    validated_window: &ValidatedWindow,
154	    outbound_effects: &AuthorizedOutboundEffects,
155	    inbound_effects: &AuthorizedInboundEffects<'_>,
156	    system_transaction_reconstructor: &SystemTransactionReconstructor,
157	) -> Result<(), DaPayloadError> {
158	    let settling = validated_window.settling_block().block();
159	    verify_encoded_da_payload(
160	        encoded_payload,
161	        validated_window
162	            .preceding_blocks()
163	            .iter()
164	            .map(|block| (block.number(), block.rlp())),
165	        (settling.number(), settling.rlp()),
166	        outbound_effects,
167	        inbound_effects,
168	        system_transaction_reconstructor,
169	    )
170	}
171	
172	/// Raw-input adapter for focused DA unit tests.
173	#[cfg(test)]
174	pub(crate) fn verify_da_payload_for_test<'a, I>(
175	    encoded_payload: &[u8],
176	    intermediate_blocks: I,
177	    settling_block: (u64, &'a [u8]),
178	    outbound_effects: &AuthorizedOutboundEffects,
179	    inbound_effects: &AuthorizedInboundEffects<'_>,
180	    system_transaction_reconstructor: &SystemTransactionReconstructor,
181	) -> Result<(), DaPayloadError>
182	where
183	    I: ExactSizeIterator<Item = (u64, &'a [u8])>,
184	{
185	    verify_encoded_da_payload(
186	        encoded_payload,
187	        intermediate_blocks,
188	        settling_block,
189	        outbound_effects,
190	        inbound_effects,
191	        system_transaction_reconstructor,
192	    )
193	}
194	
195	fn verify_encoded_da_payload<'a, I>(
196	    encoded_payload: &[u8],
197	    intermediate_blocks: I,
198	    settling_block: (u64, &'a [u8]),
199	    outbound_effects: &AuthorizedOutboundEffects,
200	    inbound_effects: &AuthorizedInboundEffects<'_>,
201	    system_transaction_reconstructor: &SystemTransactionReconstructor,
202	) -> Result<(), DaPayloadError>
203	where
204	    I: ExactSizeIterator<Item = (u64, &'a [u8])>,
205	{
206	    if encoded_payload.first() == Some(&SELF_CONTAINED_BLOCKS_TAG) {
207	        return verify_self_contained_da_payload(
208	            encoded_payload,
209	            intermediate_blocks,
210	            settling_block,
211	            outbound_effects,
212	            inbound_effects,
213	            system_transaction_reconstructor,
214	        );
215	    }
216	    let mut payload_cursor = DaPayloadCursor::decode(encoded_payload)?;
217	    let expected_blocks = intermediate_blocks.len() + 1;
218	    let omitted_terminal_count = outbound_effects
219	        .groups()
220	        .try_fold(0usize, |count, group| {
221	            let callbacks = group
222	                .iter()
223	                .map(|effect| effect.callback_transaction_indices().len())
224	                .sum::<usize>();
225	            count.checked_add(1 + callbacks)
226	        })
227	        .and_then(|count| count.checked_add(inbound_effects.len()))
228	        .ok_or(DaPayloadError::InvalidEffectTransactionLayout)?;
229	    let preceding_transaction_count = verify_preceding_block_transactions(
230	        &mut payload_cursor,
231	        intermediate_blocks,
232	        expected_blocks,
233	    )?;
234	    let settling = verify_settling_block_transactions(
235	        &mut payload_cursor,
236	        settling_block,
237	        expected_blocks,
238	        outbound_effects,
239	        inbound_effects,
240	        omitted_terminal_count,
241	    )?;
242	    // Cannot overflow: every counted transaction occupies at least one byte of
243	    // memory-resident block RLP; the sum only feeds an error diagnostic.
244	    let retained_transactions =
245	        preceding_transaction_count.saturating_add(settling.retained_transaction_count);
246	
247	    if !payload_cursor.block_tx_counts.is_empty() {
248	        return Err(DaPayloadError::UnexpectedItems {
249	            field: "blockTxCounts",
250	            expected: expected_blocks,
251	        });
252	    }
253	    if !payload_cursor.transactions.is_empty() {
254	        return Err(DaPayloadError::UnexpectedItems {
255	            field: "transactions",
256	            expected: retained_transactions,
257	        });
258	    }
259	
260	    verify_outbound_group_sizes(&mut payload_cursor, outbound_effects)?;
261	    verify_effect_sidecars(&mut payload_cursor, outbound_effects, inbound_effects)?;
262	    if settling.requires_sync_reconstruction {
263	        verify_reconstructed_sync_block(
264	            &settling.block,
265	            &settling.encoded_transactions,
266	            outbound_effects,
267	            inbound_effects,
268	            system_transaction_reconstructor,
269	        )?;
270	    }
271	    Ok(())
272	}
