274	/// Verify the self-contained profile byte-for-byte against the exact blocks
275	/// accepted by Stateless. Unlike the legacy projection, complete terminal
276	/// system transactions are present, so no transaction omission is inferred.
277	fn verify_self_contained_da_payload<'a, I>(
278	    encoded_payload: &[u8],
279	    intermediate_blocks: I,
280	    settling_block: (u64, &'a [u8]),
281	    outbound_effects: &AuthorizedOutboundEffects,
282	    inbound_effects: &AuthorizedInboundEffects<'_>,
283	    system_transaction_reconstructor: &SystemTransactionReconstructor,
284	) -> Result<(), DaPayloadError>
285	where
286	    I: ExactSizeIterator<Item = (u64, &'a [u8])>,
287	{
288	    let decoded = eez_payload_codec::decode(encoded_payload)
289	        .map_err(|error| invalid_da_payload(error.to_string()))?;
290	    let expected_blocks = intermediate_blocks.len() + 1;
291	    if decoded.block_rlps.len() != expected_blocks {
292	        return Err(DaPayloadError::BlockCount {
293	            expected: expected_blocks,
294	            actual: decoded.block_rlps.len(),
295	        });
296	    }
297	    let expected_rlps = intermediate_blocks.chain(std::iter::once(settling_block));
298	    for ((block_number, validated_rlp), submitted_rlp) in expected_rlps.zip(&decoded.block_rlps) {
299	        if submitted_rlp.as_slice() != validated_rlp {
300	            return Err(DaPayloadError::BlockRlpMismatch { block_number });
301	        }
302	    }
303	
304	    let expected_group_sizes = outbound_effects
305	        .groups()
306	        .map(|group| u16::try_from(group.len()).map_err(|_| DaPayloadError::OutboundGroupSizes))
307	        .collect::<Result<Vec<_>, _>>()?;
308	    if decoded.outbound_group_sizes != expected_group_sizes {
309	        return Err(DaPayloadError::OutboundGroupSizes);
310	    }
311	
312	    let expected_sidecars = outbound_effects
313	        .iter()
314	        .flat_map(|outbound| {
315	            let source_encoding = match outbound.derived_source_entry() {
316	                eez_protocol::system_tx::OutboundSourceEntry::Mutable(entry) => entry.abi_encode(),
317	                eez_protocol::system_tx::OutboundSourceEntry::Static(entry) => entry.abi_encode(),
318	            };
319	            std::iter::once((outbound.transaction_index(), source_encoding)).chain(
320	                outbound
321	                    .callback_transaction_indices()
322	                    .iter()
323	                    .copied()
324	                    .zip(outbound.derived_callback_entries())
325	                    .map(|(transaction_index, entry)| (transaction_index, entry.abi_encode())),
326	            )
327	        })
328	        .chain(inbound_effects.iter().map(|inbound| {
329	            (
330	                inbound.transaction_index(),
331	                inbound.observation().derived_da_entry.encoded(),
332	            )
333	        }))
334	        .collect::<Vec<_>>();
335	    for (entry_index, (transaction_index, expected)) in expected_sidecars.iter().enumerate() {
336	        let Some(actual) = decoded.l2_entries.get(entry_index) else {
337	            return Err(DaPayloadError::MissingL2Entry {
338	                entry_index,
339	                transaction_index: *transaction_index,
340	            });
341	        };
342	        if actual != expected {
343	            return Err(DaPayloadError::L2EntryMismatch {
344	                entry_index,
345	                transaction_index: *transaction_index,
346	            });
347	        }
348	    }
349	    if decoded.l2_entries.len() != expected_sidecars.len() {
350	        return Err(DaPayloadError::UnexpectedItems {
351	            field: "l2Entries",
352	            expected: expected_sidecars.len(),
353	        });
354	    }
355	
356	    if outbound_effects.iter().next().is_some() || inbound_effects.len() != 0 {
357	        let (settling_number, settling_rlp) = settling_block;
358	        let block = decode_validated_block(settling_number, settling_rlp)?;
359	        let encoded_transactions = block
360	            .body
361	            .encoded_2718_transactions_iter()
362	            .map(Bytes::from)
363	            .collect::<Vec<_>>();
364	        verify_reconstructed_sync_block(
365	            &block,
366	            &encoded_transactions,
367	            outbound_effects,
368	            inbound_effects,
369	            system_transaction_reconstructor,
370	        )?;
371	    }
372	    Ok(())
373	}
374	
375	/// Verify that every preceding block is reproduced transaction-for-transaction.
376	fn verify_preceding_block_transactions<'a, I>(
377	    payload_cursor: &mut DaPayloadCursor<'_>,
378	    preceding_blocks: I,
379	    expected_blocks: usize,
380	) -> Result<usize, DaPayloadError>
381	where
382	    I: Iterator<Item = (u64, &'a [u8])>,
383	{
384	    let mut retained_transaction_count = 0usize;
385	    for (block_index, (block_number, block_rlp)) in preceding_blocks.enumerate() {
386	        let block = decode_validated_block(block_number, block_rlp)?;
387	        let submitted_count = next_block_count(payload_cursor, expected_blocks, block_index)?;
388	        let validated_count = block.body.transactions.len();
389	        if submitted_count != validated_count {
390	            return Err(DaPayloadError::ProjectedTransactionCount {
391	                block_number,
392	                submitted: submitted_count,
393	                expected: validated_count,
394	            });
395	        }
396	        retained_transaction_count = retained_transaction_count.saturating_add(validated_count);
397	        for (transaction_index, transaction) in
398	            block.body.encoded_2718_transactions_iter().enumerate()
399	        {
400	            expect_transaction(
401	                &mut payload_cursor.transactions,
402	                block_number,
403	                transaction_index,
404	                &transaction,
405	            )?;
406	        }
407	    }
408	    Ok(retained_transaction_count)
409	}
410	
411	struct SettlingBlockDaVerification {
412	    block: EthereumBlock,
413	    encoded_transactions: Vec<Bytes>,
414	    retained_transaction_count: usize,
415	    requires_sync_reconstruction: bool,
416	}
417	
418	/// Verify the settling-block transaction projection and retain exact bytes only
419	/// when the canonical Sync sequence must be reconstructed.
420	fn verify_settling_block_transactions(
421	    payload_cursor: &mut DaPayloadCursor<'_>,
422	    (block_number, block_rlp): (u64, &[u8]),
423	    expected_blocks: usize,
424	    outbound_effects: &AuthorizedOutboundEffects,
425	    inbound_effects: &AuthorizedInboundEffects<'_>,
426	    omitted_transaction_count: usize,
427	) -> Result<SettlingBlockDaVerification, DaPayloadError> {
428	    let block = decode_validated_block(block_number, block_rlp)?;
429	    let submitted_count = next_block_count(payload_cursor, expected_blocks, expected_blocks - 1)?;
430	    let validated_count = block.body.transactions.len();
431	    let retained_transaction_count = validated_count
432	        .checked_sub(omitted_transaction_count)
433	        .ok_or(DaPayloadError::InvalidEffectTransactionLayout)?;
434	    if submitted_count != retained_transaction_count {
435	        return Err(DaPayloadError::ProjectedTransactionCount {
436	            block_number,
437	            submitted: submitted_count,
438	            expected: retained_transaction_count,
439	        });
440	    }
441	
442	    // With no authorized effects the settling block is ordinary: nothing was
443	    // omitted and there is no canonical Sync layout to reconstruct.
444	    let requires_sync_reconstruction = omitted_transaction_count != 0;
445	    let mut encoded_transactions = if requires_sync_reconstruction {
446	        Vec::with_capacity(validated_count)
447	    } else {
448	        Vec::new()
449	    };
450	    // Outbound-before-inbound ordering was established by authorization, so
451	    // chaining the two position lists preserves block order.
452	    let mut omitted_positions = outbound_effects
453	        .groups()
454	        .flat_map(|group| {
455	            std::iter::once(group[0].load_transaction_index()).chain(
456	                group
457	                    .iter()
458	                    .flat_map(|effect| effect.callback_transaction_indices().iter().copied()),
459	            )
460	        })
461	        .chain(
462	            inbound_effects
463	                .iter()
464	                .map(AuthorizedInboundEffect::transaction_index),
465	        )
466	        .peekable();
467	    for (transaction_index, transaction) in block
468	        .body
469	        .encoded_2718_transactions_iter()
470	        .map(Bytes::from)
471	        .enumerate()
472	    {
473	        if requires_sync_reconstruction {
474	            encoded_transactions.push(transaction.clone());
475	        }
476	        if omitted_positions
477	            .peek()
478	            .is_some_and(|&position| position == transaction_index)
479	        {
480	            omitted_positions.next();
481	            continue;
482	        }
483	        expect_transaction(
484	            &mut payload_cursor.transactions,
485	            block_number,
486	            transaction_index,
487	            transaction.as_ref(),
488	        )?;
489	    }
490	    if omitted_positions.next().is_some() {
491	        return Err(DaPayloadError::InvalidEffectTransactionLayout);
492	    }
493	
494	    Ok(SettlingBlockDaVerification {
495	        block,
496	        encoded_transactions,
497	        retained_transaction_count,
498	        requires_sync_reconstruction,
499	    })
500	}
501	
502	/// Verify one ordered canonical sidecar for every authorized effect.
503	fn verify_effect_sidecars(
504	    payload_cursor: &mut DaPayloadCursor<'_>,
505	    outbound_effects: &AuthorizedOutboundEffects,
506	    inbound_effects: &AuthorizedInboundEffects<'_>,
507	) -> Result<(), DaPayloadError> {
508	    let expected_sidecar_count = outbound_effects
509	        .iter()
510	        .map(|effect| 1 + effect.callback_transaction_indices().len())
511	        .sum::<usize>()
512	        + inbound_effects.len();
513	    let expected_sidecars = outbound_effects
514	        .iter()
515	        .flat_map(|outbound| {
516	            let source_encoding = match outbound.derived_source_entry() {
517	                eez_protocol::system_tx::OutboundSourceEntry::Mutable(entry) => entry.abi_encode(),
518	                eez_protocol::system_tx::OutboundSourceEntry::Static(entry) => entry.abi_encode(),
519	            };
520	            std::iter::once((outbound.transaction_index(), source_encoding)).chain(
521	                outbound
522	                    .callback_transaction_indices()
523	                    .iter()
524	                    .copied()
525	                    .zip(outbound.derived_callback_entries())
526	                    .map(|(transaction_index, entry)| (transaction_index, entry.abi_encode())),
527	            )
528	        })
529	        .chain(inbound_effects.iter().map(|inbound| {
530	            (
531	                inbound.transaction_index(),
532	                inbound.observation().derived_da_entry.encoded(),
533	            )
534	        }));
535	    for (entry_index, (transaction_index, expected_encoding)) in expected_sidecars.enumerate() {
536	        verify_l2_entry(
537	            &mut payload_cursor.l2_entries,
538	            entry_index,
539	            transaction_index,
540	            &expected_encoding,
541	        )?;
542	    }
543	    if !payload_cursor.l2_entries.is_empty() {
544	        return Err(DaPayloadError::UnexpectedItems {
545	            field: "l2Entries",
546	            expected: expected_sidecar_count,
547	        });
548	    }
549	    Ok(())
550	}
551	
552	fn verify_outbound_group_sizes(
553	    payload_cursor: &mut DaPayloadCursor<'_>,
554	    outbound_effects: &AuthorizedOutboundEffects,
555	) -> Result<(), DaPayloadError> {
556	    let expected = outbound_effects
557	        .groups()
558	        .map(<[AuthorizedOutboundEffect]>::len)
559	        .collect::<Vec<_>>();
560	    let Some(mut encoded) = payload_cursor.outbound_group_sizes.take() else {
561	        return if expected.iter().all(|&size| size == 1) {
562	            Ok(())
563	        } else {
564	            Err(DaPayloadError::OutboundGroupSizes)
565	        };
566	    };
567	    for expected_size in expected {
568	        if encoded.is_empty() {
569	            return Err(DaPayloadError::OutboundGroupSizes);
570	        }
571	        let actual =
572	            u16::decode(&mut encoded).map_err(|error| invalid_da_payload(error.to_string()))?;
573	        if usize::from(actual) != expected_size {
574	            return Err(DaPayloadError::OutboundGroupSizes);
575	        }
576	    }
577	    if !encoded.is_empty() {
578	        return Err(DaPayloadError::OutboundGroupSizes);
579	    }
580	    Ok(())
581	}
582	
583	fn decode_validated_block(
584	    block_number: u64,
585	    block_rlp: &[u8],
586	) -> Result<EthereumBlock, DaPayloadError> {
587	    alloy_rlp::decode_exact(block_rlp).map_err(|error| DaPayloadError::InvalidBlockRlp {
588	        block_number,
589	        reason: error.to_string(),
590	    })
591	}
592	
593	fn next_block_count(
594	    payload_cursor: &mut DaPayloadCursor<'_>,
595	    expected_blocks: usize,
596	    block_index: usize,
597	) -> Result<usize, DaPayloadError> {
598	    if payload_cursor.block_tx_counts.is_empty() {
599	        return Err(DaPayloadError::BlockCount {
600	            expected: expected_blocks,
601	            actual: block_index,
602	        });
603	    }
604	    u16::decode(&mut payload_cursor.block_tx_counts)
605	        .map(usize::from)
606	        .map_err(|error| invalid_da_payload(error.to_string()))
607	}
608	
609	fn expect_transaction(
610	    transactions: &mut &[u8],
611	    block_number: u64,
612	    transaction_index: usize,
613	    expected: &[u8],
614	) -> Result<(), DaPayloadError> {
615	    if transactions.is_empty() {
616	        return Err(DaPayloadError::TransactionMismatch {
617	            block_number,
618	            transaction_index,
619	        });
620	    }
621	    let encoded_transaction = decode_list(transactions)?;
622	    if !encoded_bytes_match(encoded_transaction, expected)? {
623	        return Err(DaPayloadError::TransactionMismatch {
624	            block_number,
625	            transaction_index,
626	        });
627	    }
628	    Ok(())
629	}
630	
631	fn verify_l2_entry(
632	    encoded_entries: &mut &[u8],
633	    entry_index: usize,
634	    transaction_index: usize,
635	    expected: &[u8],
636	) -> Result<(), DaPayloadError> {
637	    if encoded_entries.is_empty() {
638	        return Err(DaPayloadError::MissingL2Entry {
639	            entry_index,
640	            transaction_index,
641	        });
642	    }
643	    let encoded_entry = decode_list(encoded_entries)?;
644	    if !encoded_bytes_match(encoded_entry, expected)? {
645	        return Err(DaPayloadError::L2EntryMismatch {
646	            entry_index,
647	            transaction_index,
648	        });
649	    }
650	    Ok(())
651	}
652	
653	fn verify_reconstructed_sync_block(
654	    block: &EthereumBlock,
655	    validated_transactions: &[Bytes],
656	    outbound_effects: &AuthorizedOutboundEffects,
657	    inbound_effects: &AuthorizedInboundEffects<'_>,
658	    reconstructor: &SystemTransactionReconstructor,
659	) -> Result<(), DaPayloadError> {
660	    let first_system_position = outbound_effects
661	        .iter()
662	        .next()
663	        .map(AuthorizedOutboundEffect::load_transaction_index)
664	        .or_else(|| {
665	            inbound_effects
666	                .iter()
667	                .next()
668	                .map(AuthorizedInboundEffect::transaction_index)
669	        })
670	        .ok_or(DaPayloadError::InvalidEffectTransactionLayout)?;
671	    let starting_nonce = block
672	        .body
673	        .transactions
674	        .get(first_system_position)
675	        .ok_or(DaPayloadError::InvalidEffectTransactionLayout)?
676	        .nonce();
677	    let outbound_reconstruction_inputs = outbound_effects
678	        .groups()
679	        .map(|bindings| {
680	            let first = &bindings[0];
681	            let user_transaction = validated_transactions
682	                .get(first.transaction_index())
683	                .ok_or(DaPayloadError::InvalidEffectTransactionLayout)?;
684	            Ok(eez_protocol::system_tx::OutboundSyncGroup {
685	                effects: bindings
686	                    .iter()
687	                    .map(|binding| eez_protocol::system_tx::OutboundSyncEffect {
688	                        source_entry: binding.derived_source_entry().clone(),
689	                        callback_entries: binding.derived_callback_entries().to_vec(),
690	                    })
691	                    .collect(),
692	                user_tx: user_transaction.clone(),
693	            })
694	        })
695	        .collect::<Result<Vec<_>, DaPayloadError>>()?;
696	    let inbound_reconstruction_entries = inbound_effects
697	        .iter()
698	        .map(|binding| binding.observation().derived_da_entry.as_entry().clone())
699	        .collect::<Vec<_>>();
700	    let pairs = reconstructor
701	        .reconstruct_sync_pairs(
702	            &outbound_reconstruction_inputs,
703	            &inbound_reconstruction_entries,
704	            starting_nonce,
705	        )
706	        .map_err(|reason| DaPayloadError::SystemTransactionReconstruction { reason })?;
707	    let reconstructed = eez_protocol::system_tx::interleave_sync_block_txs(&pairs);
708	
709	    // The canonical Sync layout contains exactly `2 * outbound + inbound`
710	    // transactions. Reject a different terminal-block length before comparing
711	    // transaction bytes.
712	    if reconstructed.len() != validated_transactions.len() {
713	        return Err(DaPayloadError::SyncBlockTransactionCount {
714	            expected: reconstructed.len(),
715	            actual: validated_transactions.len(),
716	        });
717	    }
718	    for (transaction_index, (validated_transaction, reconstructed_transaction)) in
719	        validated_transactions.iter().zip(reconstructed).enumerate()
720	    {
721	        if validated_transaction.as_ref() != reconstructed_transaction.as_ref() {
722	            return Err(DaPayloadError::SyncBlockTransactionMismatch { transaction_index });
723	        }
724	    }
725	    Ok(())
726	}
727	
728	pub(super) fn encoded_bytes_match(
729	    mut encoded: &[u8],
730	    expected: &[u8],
731	) -> Result<bool, DaPayloadError> {
732	    // `Vec<u8>` is represented here as an RLP list of byte items. Decode it
733	    // incrementally so a malformed or non-canonical byte fails closed.
734	    for expected_byte in expected {
735	        if encoded.is_empty() {
736	            return Ok(false);
737	        }
738	        let actual =
739	            u8::decode(&mut encoded).map_err(|error| invalid_da_payload(error.to_string()))?;
740	        if actual != *expected_byte {
741	            return Ok(false);
742	        }
743	    }
744	    Ok(encoded.is_empty())
745	}
746	
747	#[cfg(test)]
748	pub(crate) fn encode_da_payload(blocks: &[Vec<Vec<u8>>], l2_entries: &[Vec<u8>]) -> Vec<u8> {
749	    use alloy_rlp::Encodable as _;
750	
751	    #[derive(alloy_rlp::RlpEncodable)]
752	    struct Body {
753	        block_tx_counts: Vec<u16>,
754	        transactions: Vec<Vec<u8>>,
755	        l2_entries: Vec<Vec<u8>>,
756	    }
757	
758	    let body = Body {
759	        block_tx_counts: blocks
760	            .iter()
761	            .map(|block| u16::try_from(block.len()).expect("test block exceeds u16::MAX txs"))
762	            .collect(),
763	        transactions: blocks.iter().flatten().cloned().collect(),
764	        l2_entries: l2_entries.to_vec(),
765	    };
766	    let mut encoded = Vec::with_capacity(1 + body.length());
767	    encoded.push(CALL_DATA_TAG);
768	    body.encode(&mut encoded);
769	    encoded
770	}
771	
772	#[cfg(test)]
773	pub(crate) fn encode_grouped_da_payload(
774	    blocks: &[Vec<Vec<u8>>],
775	    l2_entries: &[Vec<u8>],
776	    outbound_group_sizes: &[u16],
777	) -> Vec<u8> {
778	    use alloy_rlp::Encodable as _;
779	
780	    #[derive(alloy_rlp::RlpEncodable)]
781	    struct Body {
782	        block_tx_counts: Vec<u16>,
783	        transactions: Vec<Vec<u8>>,
784	        l2_entries: Vec<Vec<u8>>,
785	        outbound_group_sizes: Vec<u16>,
786	    }
787	
788	    let body = Body {
789	        block_tx_counts: blocks
790	            .iter()
791	            .map(|block| u16::try_from(block.len()).expect("test block exceeds u16::MAX txs"))
792	            .collect(),
793	        transactions: blocks.iter().flatten().cloned().collect(),
794	        l2_entries: l2_entries.to_vec(),
