    settling_block: (u64, &'a [u8]),
    outbound_effects: &AuthorizedOutboundEffects,
    inbound_effects: &AuthorizedInboundEffects<'_>,
    system_transaction_reconstructor: &SystemTransactionReconstructor,
) -> Result<(), DaPayloadError>
where
