73	        let transaction_count = block.body().transactions.len();
74	        let mut system_sender_flags = Vec::with_capacity(transaction_count);
75	        let mut sync_system_transaction_flags = Vec::with_capacity(transaction_count);
76	        for transaction in block.transactions_recovered() {
77	            let is_system_sender = transaction.signer() == expected_l2_system_address;
78	            system_sender_flags.push(is_system_sender);
79	            sync_system_transaction_flags.push(is_system_tx(
80	                transaction.signer(),
81	                transaction.to(),
82	                expected_l2_system_address,
83	                EEZL2_ADDRESS,
84	            ));
85	        }
86	        let plan = Self {
87	            transaction_indices: pair_end_positions(&sync_system_transaction_flags),
88	        };
89	        (plan, system_sender_flags)
90	    }
91	
92	    /// Check that a checkpoint-capable backend honored the selection exactly.
93	    fn verify_returned(
94	        &self,
95	        checkpoints: &[ReplayStateCheckpoint],
96	    ) -> Result<(), ValidationError> {
97	        let selection_matches = checkpoints.len() == self.transaction_indices.len()
98	            && checkpoints
99	                .iter()
100	                .zip(&self.transaction_indices)
101	                .all(|(checkpoint, requested)| checkpoint.transaction_index == *requested);
102	        if !selection_matches {
103	            let returned = checkpoints
104	                .iter()
105	                .map(|checkpoint| checkpoint.transaction_index)
106	                .collect::<Vec<_>>();
107	            return Err(ValidationError::InvalidBackendOutput(format!(
108	                "stateless checkpoint response targeted transaction indices {returned:?}; \
109	                 requested {:?}",
110	                self.transaction_indices,
111	            )));
112	        }
113	        Ok(())
114	    }
115	}
