208	    /// Replay every admitted block and return associated per-block output. The
209	    /// caller still consumes and checks that output before exposing settlement evidence.
210	    pub(super) fn validate_blocks(
211	        &self,
212	        blocks: &mut [AdmittedBlock],
213	        cancellation: &CancellationToken,
214	    ) -> Result<BackendWindowOutput, ValidationError> {
215	        let validation_started = Instant::now();
216	        let total_blocks = blocks.len();
217	        let mut block_outputs = Vec::<BackendBlockOutput>::with_capacity(total_blocks);
218	        let mut window_pre_state_root = None;
219	
220	        // Derive the final block's complete checkpoint plan before any witness
221	        // is consumed or earlier block is replayed.
222	        check_cancellation(cancellation, 0, total_blocks)?;
223	        let mut prepared_settling_block = blocks
224	            .last()
225	            .map(|admitted| {
226	                let recovered_block = decode_match_and_recover_signers(admitted, &self.chain_spec)?;
227	                let (checkpoint_plan, system_sender_flags) = CheckpointPlan::from_recovered_block(
228	                    &recovered_block,
229	                    self.expected_l2_system_address,
230	                );
231	                Ok(PreparedSettlingBlock {
232	                    block: recovered_block,
233	                    checkpoint_plan,
234	                    system_sender_flags,
235	                })
236	            })
237	            .transpose()?;
238	
239	        for (index, admitted) in blocks.iter_mut().enumerate() {
240	            check_cancellation(cancellation, index, total_blocks)?;
241	            let block_started = Instant::now();
242	            let block_ordinal = index + 1;
243	            let (recovered_block, checkpoint_plan, system_sender_flags) = if block_ordinal
244	                == total_blocks
245	            {
246	                let prepared = prepared_settling_block.take().ok_or_else(|| {
247	                    ValidationError::InternalInvariant(
248	                        "prepared settling block unexpectedly missing".to_owned(),
249	                    )
250	                })?;
251	                (
252	                    prepared.block,
253	                    Some(prepared.checkpoint_plan),
254	                    prepared.system_sender_flags,
255	                )
256	            } else {
257	                let recovered_block = decode_match_and_recover_signers(admitted, &self.chain_spec)?;
258	                let system_sender_flags =
259	                    system_sender_flags(&recovered_block, self.expected_l2_system_address);
260	                (recovered_block, None, system_sender_flags)
261	            };
262	            let block_number = recovered_block.header().number;
263	            let decoded_parent_hash = recovered_block.header().parent_hash;
264	            let timestamp = recovered_block.header().timestamp;
265	            let transaction_count = recovered_block.body().transactions.len();
266	            let settling_block_template = checkpoint_plan.as_ref().map(|_| recovered_block.clone());
267	            trace!(
268	                block_ordinal,
269	                block_number,
270	                claimed_block_hash = %admitted.claimed_hash,
271	                timestamp,
272	                transactions = transaction_count,
273	                "validating stateless block",
274	            );
275	
276	            // Before this call the decoded block and witness remain untrusted.
277	            // Successful Stateless output means consensus, witness pre-state,
278	            // execution receipts, and the recomputed post-state commitment all
279	            // passed. Only a non-empty final selection uses the checkpoint path.
280	            let witness = std::mem::take(&mut admitted.witness);
281	            let (stateless_output, replay_state_checkpoints) = match checkpoint_plan {
282	                Some(plan) if !plan.transaction_indices.is_empty() => {
283	                    let output = stateless_validation_recovered_with_state_checkpoints(
284	                        recovered_block,
285	                        witness,
286	                        Arc::clone(&self.chain_spec),
287	                        self.evm_config.clone(),
288	                        &plan.transaction_indices,
289	                    )
290	                    .map_err(|error| map_stateless_error(block_number, error))?;
291	                    let checkpoints = output
292	                        .checkpoints
293	                        .transaction_state_checkpoints
294	                        .into_iter()
295	                        .map(|checkpoint| ReplayStateCheckpoint {
296	                            transaction_index: checkpoint.transaction_index,
297	                            state_root: checkpoint.state_root,
298	                        })
299	                        .collect::<Vec<_>>();
300	                    plan.verify_returned(&checkpoints)?;
301	                    (output.validation, checkpoints)
302	                }
303	                _ => {
304	                    let output = stateless_validation_recovered(
305	                        recovered_block,
306	                        witness,
307	                        Arc::clone(&self.chain_spec),
308	                        self.evm_config.clone(),
309	                    )
310	                    .map_err(|error| map_stateless_error(block_number, error))?;
311	                    (output, Vec::new())
312	                }
313	            };
314	
315	            let StatelessValidationOutput {
316	                block_hash: computed_hash,
317	                pre_state_root,
318	                post_state_root,
319	                execution_output,
320	                block_access_list: _validated_block_access_list,
321	            } = stateless_output;
322	            if let Some(previous_post_state_root) =
323	                block_outputs.last().map(|output| output.post_state_root)
324	                && pre_state_root != previous_post_state_root
325	            {
326	                return Err(ValidationError::Rejected(format!(
327	                    "stateless state roots do not telescope at block {block_number}: expected \
328	                     pre-state root {previous_post_state_root}, got {pre_state_root}",
329	                )));
330	            }
331	            window_pre_state_root.get_or_insert(pre_state_root);
332	
333	            // These receipts come from successful replay. Observed outbound
334	            // events are retained here but authorized against batch entries only
335	            // later by settlement.
336	            let has_execution_requests = !execution_output.result.requests.is_empty();
337	            let validated_receipts = execution_output.result.receipts;
338	            let transaction_state_checkpoints = match settling_block_template {
339	                Some(block) => derive_prefix_block_hashes(
340	                    &block,
341	                    &validated_receipts,
342	                    &replay_state_checkpoints,
343	                    has_execution_requests,
344	                )?,
345	                None => Vec::new(),
346	            };
347	            let receipt_successes = validated_receipts
348	                .iter()
349	                .map(|receipt| receipt.success)
350	                .collect::<Vec<_>>();
351	            let observed_outbound_events = observe_outbound_events(&validated_receipts);
352	
353	            if tracing::enabled!(tracing::Level::TRACE) {
354	                let failed_transactions = receipt_successes
355	                    .iter()
356	                    .filter(|&&success| !success)
357	                    .count();
358	                let malformed_outbound_events = observed_outbound_events
359	                    .iter()
360	                    .filter(|observation| observation.decoded_event.is_none())
361	                    .count();
362	                trace!(
363	                    block_ordinal,
364	                    total_blocks,
365	                    block_number,
366	                    computed_block_hash = %computed_hash,
367	                    validated_pre_state_root = %pre_state_root,
368	                    validated_post_state_root = %post_state_root,
369	                    transactions = transaction_count,
370	                    failed_transactions,
371	                    outbound_events = observed_outbound_events.len(),
372	                    malformed_outbound_events,
373	                    block_elapsed_ms = elapsed_millis(block_started),
374	                    "stateless block validated",
375	                );
376	            }
377	            block_outputs.push(BackendBlockOutput {
378	                decoded_number: block_number,
379	                decoded_parent_hash,
380	                computed_hash,
381	                decoded_transaction_count: transaction_count,
382	                receipt_successes,
383	                transaction_state_checkpoints,
384	                post_state_root,
385	                settlement_evidence: SettlementBlockEvidence {
386	                    system_sender_flags,
387	                    observed_outbound_events,
388	                },
389	            });
390	
391	            if block_ordinal.is_multiple_of(DEBUG_PROGRESS_INTERVAL) {
392	                debug!(
393	                    validated_blocks = block_ordinal,
394	                    total_blocks,
395	                    block_number,
396	                    validated_post_state_root = %post_state_root,
397	                    elapsed_ms = elapsed_millis(validation_started),
398	                    "stateless validation progress",
399	                );
400	            }
401	        }
402	
403	        let pre_state_root = window_pre_state_root.ok_or_else(|| {
404	            ValidationError::Rejected("refusing to validate an empty window".to_owned())
405	        })?;
406	        Ok(BackendWindowOutput {
407	            pre_state_root,
408	            blocks: block_outputs,
409	        })
410	    }
