412	    /// Re-execute every non-applying lookup/static root from the exact witness
413	    /// already accepted for the terminal block.
414	    pub(super) fn verify_observations(
415	        &self,
416	        window: &ValidatedWindow,
417	        claims: &[FifoObservationClaim],
418	    ) -> Result<(), ObservationValidationError> {
419	        let outcomes = self.replay_observations(window, claims)?;
420	        for (index, (claim, outcome)) in claims.iter().zip(outcomes).enumerate() {
421	            if claim.expected_success != outcome.success || claim.expected_output != outcome.output
422	            {
423	                return Err(ObservationValidationError::OutcomeMismatch { index });
424	            }
425	        }
426	        Ok(())
427	    }
428	
429	    fn replay_observations(
430	        &self,
431	        window: &ValidatedWindow,
432	        claims: &[FifoObservationClaim],
433	    ) -> Result<Vec<ObservedOutcome>, ObservationValidationError> {
434	        let settling = window.settling_block();
435	        let replay = settling.replay_input();
436	        let block = alloy_rlp::decode_exact::<Block>(settling.block().rlp())
437	            .map_err(|error| ObservationValidationError::Replay(error.to_string()))?;
438	        let block = recover_block(block, &self.chain_spec)
439	            .map_err(|error| ObservationValidationError::Replay(error.to_string()))?;
440	        let transaction_count = block.body().transactions.len();
441	
442	        let mut observations = Vec::with_capacity(claims.len());
443	        for (index, claim) in claims.iter().cloned().enumerate() {
444	            let after_transactions = if claim.pinned_block_hash == window.settling_pre_block_hash()
445	            {
446	                0
447	            } else if let Some(checkpoint) = settling
448	                .transaction_state_checkpoints()
449	                .iter()
450	                .find(|checkpoint| checkpoint.block_hash == claim.pinned_block_hash)
451	            {
452	                checkpoint.transaction_index + 1
453	            } else if claim.pinned_block_hash == window.window_post_block_hash() {
454	                transaction_count
455	            } else {
456	                return Err(ObservationValidationError::UnknownPinnedRoot {
457	                    index,
458	                    block_hash: claim.pinned_block_hash,
459	                });
460	            };
461	            observations.push(BlockObservation {
462	                after_transactions,
463	                manager_address: crate::EEZL2_ADDRESS,
464	                claim,
465	            });
466	        }
467	        if observations
468	            .windows(2)
469	            .any(|pair| pair[0].after_transactions > pair[1].after_transactions)
470	        {
471	            return Err(ObservationValidationError::Replay(
472	                "observation pins are not in FIFO prefix order".to_owned(),
473	            ));
474	        }
475	
476	        // The ordinary validation pass consumed an identical clone and
477	        // accepted its ancestor chain and pre-state commitment. Rebuilding the
478	        // sparse trie here authenticates every supplemental observation read;
479	        // missing account/code/storage nodes fail closed.
480	        let (trie, bytecode) =
481	            StatelessSparseTrie::new(replay.witness.clone(), replay.pre_state_root)
482	                .map_err(|error| ObservationValidationError::Replay(format!("{error:?}")))?;
483	        // Validate the retained header chain again before exposing it through
484	        // BLOCKHASH. This is redundant with the first Stateless pass, but it
485	        // keeps the observation verifier fail-closed if the retained replay
486	        // representation is ever refactored or made mutable.
487	        let ancestor_hashes = authenticated_ancestor_hashes(&block, &replay.witness.headers)?;
488	        let db = ObservationWitnessDatabase::new(&trie, bytecode, ancestor_hashes);
489	        let has_bal = block.sealed_header().block_access_list_hash().is_some();
490	        let mut state = State::builder()
491	            .with_database(db)
492	            .with_bundle_update()
493	            .with_bal_builder_if(has_bal)
494	            .build();
495	        replay_block_with_observations(&mut state, &self.evm_config, &block, &observations)
496	            .map_err(|error| ObservationValidationError::Replay(error.to_string()))
497	    }
498	}
