500	/// Decode and authenticate the EVM `BLOCKHASH` window against the exact
501	/// terminal block header. Witness headers are ordered oldest-to-newest, so the
502	/// parent is checked first by iterating in reverse.
503	fn authenticated_ancestor_hashes(
504	    block: &RecoveredBlock<Block>,
505	    headers: &[Bytes],
506	) -> Result<BTreeMap<u64, B256>, ObservationValidationError> {
507	    if headers.len() > BLOCKHASH_ANCESTOR_LIMIT {
508	        return Err(ObservationValidationError::Replay(format!(
509	            "ancestor header count {} exceeds limit {BLOCKHASH_ANCESTOR_LIMIT}",
510	            headers.len(),
511	        )));
512	    }
513	    if headers.is_empty() {
514	        return Err(ObservationValidationError::Replay(
515	            "terminal replay witness has no parent header".to_owned(),
516	        ));
517	    }
518	
519	    let decoded = headers
520	        .iter()
521	        .map(|bytes| {
522	            alloy_rlp::decode_exact::<alloy_consensus::Header>(bytes)
523	                .map(|header| (header, keccak256(bytes)))
524	                .map_err(|error| ObservationValidationError::Replay(error.to_string()))
525	        })
526	        .collect::<Result<Vec<_>, _>>()?;
527	    let mut hashes = BTreeMap::new();
528	    let mut child_number = block.header().number;
529	    let mut expected_parent_hash = block.header().parent_hash;
530	    for (parent, actual_hash) in decoded.iter().rev() {
531	        let expected_parent_number = child_number.checked_sub(1).ok_or_else(|| {
532	            ObservationValidationError::Replay(
533	                "genesis block cannot have an ancestor-header witness".to_owned(),
534	            )
535	        })?;
536	        if parent.number != expected_parent_number {
537	            return Err(ObservationValidationError::Replay(format!(
538	                "invalid ancestor number: block {child_number} expects parent {expected_parent_number}, got {}",
539	                parent.number,
540	            )));
541	        }
542	        if *actual_hash != expected_parent_hash {
543	            return Err(ObservationValidationError::Replay(format!(
544	                "invalid ancestor hash at block {}: expected {expected_parent_hash}, got {actual_hash}",
545	                parent.number,
546	            )));
547	        }
548	        hashes.insert(parent.number, *actual_hash);
549	        child_number = parent.number;
550	        expected_parent_hash = parent.parent_hash;
551	    }
552	    Ok(hashes)
553	}
