555	/// Minimal witness-backed revm database used only for observation replay.
556	/// This mirrors Stateless's private validation adapter while deliberately
557	/// keeping account/storage reads fail-closed through `StatelessSparseTrie`.
558	#[derive(Debug)]
559	struct ObservationWitnessDatabase<'a> {
560	    trie: &'a StatelessSparseTrie,
561	    bytecode: B256IndexMap<Bytes>,
562	    block_hashes: BTreeMap<u64, B256>,
563	}
564	
565	impl<'a> ObservationWitnessDatabase<'a> {
566	    const fn new(
567	        trie: &'a StatelessSparseTrie,
568	        bytecode: B256IndexMap<Bytes>,
569	        block_hashes: BTreeMap<u64, B256>,
570	    ) -> Self {
571	        Self {
572	            trie,
573	            bytecode,
574	            block_hashes,
575	        }
576	    }
577	}
