579	impl Database for ObservationWitnessDatabase<'_> {
580	    type Error = WitnessDbError;
581	
582	    fn basic(&mut self, address: Address) -> Result<Option<AccountInfo>, Self::Error> {
583	        self.trie.account(address).map(|account| {
584	            account.map(|account| AccountInfo {
585	                balance: account.balance,
586	                nonce: account.nonce,
587	                code_hash: account.code_hash,
588	                code: None,
589	                account_id: None,
590	            })
591	        })
592	    }
593	
594	    fn storage(&mut self, address: Address, slot: U256) -> Result<U256, Self::Error> {
595	        self.trie.storage(address, slot)
596	    }
597	
598	    fn code_by_hash(&mut self, code_hash: B256) -> Result<Bytecode, Self::Error> {
599	        self.bytecode
600	            .get(&code_hash)
601	            .cloned()
602	            .map(Bytecode::new_raw)
603	            .ok_or_else(|| {
604	                WitnessDbError::TrieWitness(format!("bytecode for {code_hash} not found"))
605	            })
606	    }
