608	    fn block_hash(&mut self, block_number: u64) -> Result<B256, Self::Error> {
609	        self.block_hashes
610	            .get(&block_number)
611	            .copied()
612	            .ok_or(WitnessDbError::StateNotFound(block_number))
613	    }
