616	/// Convert replayed transaction-state checkpoints into complete canonical
617	/// block-hash commitments. Every header field not affected by truncating the
618	/// transaction list is inherited from the exact block accepted by Stateless.
619	/// Transaction/receipt roots, bloom, gas and state commitment are recomputed
620	/// for each prefix.
621	fn derive_prefix_block_hashes(
622	    block: &RecoveredBlock<Block>,
623	    receipts: &[EthereumReceipt],
624	    checkpoints: &[ReplayStateCheckpoint],
625	    has_execution_requests: bool,
626	) -> Result<Vec<TransactionStateCheckpoint>, ValidationError> {
627	    if checkpoints.is_empty() {
628	        return Ok(Vec::new());
629	    }
630	    if receipts.len() != block.body().transactions.len() {
631	        return Err(ValidationError::InvalidBackendOutput(format!(
632	            "cannot derive prefix block hashes for block {}: replay returned {} receipts for {} transactions",
633	            block.header().number,
634	            receipts.len(),
635	            block.body().transactions.len(),
636	        )));
637	    }
638	    if block
639	        .body()
640	        .withdrawals
641	        .as_ref()
642	        .is_some_and(|withdrawals| !withdrawals.is_empty())
643	    {
644	        return Err(ValidationError::Rejected(format!(
645	            "settling block {} has withdrawals; prefix block-hash commitments require no post-transaction state changes",
646	            block.header().number,
647	        )));
648	    }
649	    if !block.body().ommers.is_empty() {
650	        return Err(ValidationError::Rejected(format!(
651	            "settling block {} has ommers; prefix block-hash commitments require a post-merge block body",
652	            block.header().number,
653	        )));
654	    }
655	    if has_execution_requests {
656	        return Err(ValidationError::Rejected(format!(
657	            "settling block {} produces EIP-7685 requests; prefix block-hash commitments currently support only empty requests",
658	            block.header().number,
659	        )));
660	    }
661	
662	    let mut block_hashes = Vec::with_capacity(checkpoints.len());
663	    for checkpoint in checkpoints {
664	        let prefix_len = checkpoint.transaction_index + 1;
665	        let prefix_receipts = receipts[..prefix_len]
666	            .iter()
667	            .map(alloy_consensus::TxReceipt::with_bloom_ref)
668	            .collect::<Vec<_>>();
669	        let mut header = block.header().clone();
670	        header.state_root = checkpoint.state_root;
671	        header.transactions_root =
672	            calculate_transaction_root(&block.body().transactions[..prefix_len]);
673	        header.receipts_root = calculate_receipt_root(&prefix_receipts);
674	        header.logs_bloom = prefix_receipts
675	            .iter()
676	            .fold(Bloom::ZERO, |bloom, receipt| bloom | receipt.bloom_ref());
677	        header.gas_used = receipts[checkpoint.transaction_index].cumulative_gas_used();
678	        if header.blob_gas_used.is_some() {
679	            header.blob_gas_used = Some(
680	                block.body().transactions[..prefix_len]
681	                    .iter()
682	                    .try_fold(0u64, |total, transaction| {
683	                        total.checked_add(transaction.blob_gas_used().unwrap_or(0))
684	                    })
685	                    .ok_or_else(|| {
686	                        ValidationError::InvalidBackendOutput(format!(
687	                            "blob gas overflow while deriving a prefix hash for block {}",
688	                            block.header().number,
689	                        ))
690	                    })?,
691	            );
692	        }
693	        let block_hash = header.hash_slow();
694	        if prefix_len == block.body().transactions.len() {
695	            let full_block_hash = block.header().hash_slow();
696	            if block_hash != full_block_hash {
697	                return Err(ValidationError::InvalidBackendOutput(format!(
698	                    "final prefix hash {block_hash} for block {} does not match validated full block hash {full_block_hash}",
699	                    block.header().number,
700	                )));
701	            }
702	        }
703	        block_hashes.push(TransactionStateCheckpoint {
704	            transaction_index: checkpoint.transaction_index,
705	            block_hash,
706	        });
707	    }
708	    Ok(block_hashes)
709	}
710	
711	/// Classify a rejected local checkpoint plan as an internal invariant failure;
712	/// all other Stateless errors reject the input.
713	fn map_stateless_error(block_number: u64, error: StatelessValidationError) -> ValidationError {
714	    match error {
715	        error @ (StatelessValidationError::UnorderedTransactionCheckpoints { .. }
716	        | StatelessValidationError::TransactionCheckpointOutOfBounds { .. }) => {
717	            ValidationError::InternalInvariant(format!(
718	                "stateless rejected the locally derived checkpoint plan for block {block_number}: \
719	                 {error}",
720	            ))
721	        }
722	        error => ValidationError::Rejected(format!(
723	            "stateless validation rejected block {block_number}: {error}",
724	        )),
725	    }
726	}
727	
728	/// Classify each locally recovered signer for later settlement policy.
729	fn system_sender_flags(
730	    block: &RecoveredBlock<Block>,
731	    expected_l2_system_address: Address,
732	) -> Vec<bool> {
733	    block
734	        .transactions_recovered()
735	        .map(|transaction| transaction.signer() == expected_l2_system_address)
736	        .collect()
737	}
738	
739	/// Stop between non-interruptible block executions after request cancellation.
740	fn check_cancellation(
741	    cancellation: &CancellationToken,
742	    validated_blocks: usize,
743	    total_blocks: usize,
744	) -> Result<(), ValidationError> {
745	    if cancellation.is_cancelled() {
746	        debug!(
747	            validated_blocks,
748	            total_blocks, "stateless validation stopped after request cancellation",
749	        );
750	        Err(ValidationError::Cancelled)
751	    } else {
752	        Ok(())
753	    }
754	}
755	
756	fn elapsed_millis(since: Instant) -> u64 {
757	    u64::try_from(since.elapsed().as_millis()).unwrap_or(u64::MAX)
758	}
759	
760	/// Exact-decode Composer-supplied RLP and match its identity to stream metadata.
761	/// The returned block is still untrusted until Stateless accepts it.
762	fn decode_and_match_stream_metadata(admitted: &AdmittedBlock) -> Result<Block, ValidationError> {
763	    let block = alloy_rlp::decode_exact::<Block>(&admitted.rlp).map_err(|error| {
764	        ValidationError::Rejected(format!(
765	            "block {} carries invalid consensus RLP: {error}",
766	            admitted.declared_number,
767	        ))
768	    })?;
769	    if block.header.number != admitted.declared_number {
770	        return Err(ValidationError::Rejected(format!(
771	            "decoded block number {} does not match streamed block {}",
772	            block.header.number, admitted.declared_number,
773	        )));
774	    }
775	    if block.header.parent_hash != admitted.claimed_parent_hash {
776	        return Err(ValidationError::Rejected(format!(
777	            "decoded parent hash {} for block {} does not match streamed parent hash {}",
778	            block.header.parent_hash, admitted.declared_number, admitted.claimed_parent_hash,
779	        )));
780	    }
781	    let computed_hash = block.header.hash_slow();
782	    if computed_hash != admitted.claimed_hash {
783	        return Err(ValidationError::Rejected(format!(
784	            "computed block hash {computed_hash} for block {} does not match streamed block hash {}",
785	            admitted.declared_number, admitted.claimed_hash,
786	        )));
787	    }
788	    Ok(block)
789	}
790	
791	/// Exact-decode, match stream metadata, and recover transaction signers under
792	/// the configured fork rules. Signer recovery is not execution validation.
793	fn decode_match_and_recover_signers(
794	    admitted: &AdmittedBlock,
795	    chain_spec: &ChainSpec,
796	) -> Result<RecoveredBlock<Block>, ValidationError> {
797	    let block = decode_and_match_stream_metadata(admitted)?;
798	    let number = block.header.number;
799	    recover_block(block, chain_spec).map_err(|error| {
800	        ValidationError::Rejected(format!(
801	            "block {number} transaction recovery failed: {error}",
802	        ))
803	    })
804	}
805	
806	/// Homestead (EIP-2) forbids high-s signatures, so enforce the low-s rule
807	/// during recovery only for blocks where that fork is active.
808	fn recover_block(
809	    block: Block,
810	    chain_spec: &ChainSpec,
811	) -> Result<RecoveredBlock<Block>, reth_primitives_traits::transaction::signed::RecoveryError> {
812	    if chain_spec.is_homestead_active_at_block(block.header.number) {
813	        RecoveredBlock::try_recover(block)
814	    } else {
815	        RecoveredBlock::try_recover_unchecked(block)
816	    }
817	}
818	
819	/// Retain every EEZL2 outbound-event candidate with receipt provenance.
820	///
821	/// Matching emitter/signature logs remain observations in receipt order.
822	/// Canonical encodings expose the emitted hash and manager-entry gas;
823	/// malformed or non-canonical encodings remain undecoded observations.
824	fn observe_outbound_events(
825	    validated_receipts: &[EthereumReceipt],
826	) -> Vec<OutboundEventObservation> {
827	    let mut observations = Vec::new();
828	    for (transaction_index, receipt) in validated_receipts.iter().enumerate() {
829	        for (receipt_log_index, log) in receipt.logs.iter().enumerate() {
830	            if log.address != EEZL2_ADDRESS
831	                || log.data.topics().first() != Some(&CrossChainCallExecuted::SIGNATURE_HASH)
832	            {
833	                continue;
834	            }
835	            let decoded_event = CrossChainCallExecuted::decode_log_validate(log)
836	                .ok()
837	                .filter(|decoded| &CrossChainCallExecuted::encode_log(decoded) == log)
838	                .map(|decoded| {
839	                    DecodedOutboundEvent::new(decoded.data.crossChainCallHash, decoded.data.callGas)
840	                });
841	            observations.push(OutboundEventObservation {
842	                transaction_index,
843	                receipt_log_index,
844	                decoded_event,
845	            });
846	        }
847	    }
848	    observations
849	}
850	
851	#[cfg(test)]
852	mod tests;
853

