288	    /// Consume the header-only state after matching its rollup claim against
289	    /// operator configuration, enabling block admission and finalization.
290	    pub(crate) fn verify_rollup_identity(
291	        self,
292	        expected_rollup_id: NonZeroU64,
293	    ) -> Result<WindowAssembler<true>, RollupIdentityMismatch> {
294	        let expected = expected_rollup_id.get();
295	        if self.claimed_rollup_id != expected {
296	            return Err(RollupIdentityMismatch {
297	                claimed: self.claimed_rollup_id,
298	                expected,
299	            });
300	        }
301	
302	        Ok(WindowAssembler {
303	            limits: self.limits,
304	            accounted_payload_bytes: self.accounted_payload_bytes,
305	            accounted_witness_items: self.accounted_witness_items,
306	            claimed_rollup_id: expected,
307	            header: self.header,
308	            declared_block_count: self.declared_block_count,
309	            blocks: self.blocks,
310	        })
311	    }
312	
313	    /// Parse the header, retain its rollup claim, and validate its range.
314	    fn check_header(
315	        header: ProveHeader,
316	        limits: WindowLimits,
317	    ) -> Result<ParsedHeader, WindowError> {
318	        let ProveHeader {
319	            rollup_id: claimed_rollup_id,
320	            from_block: declared_from_block,
321	            to_block: declared_to_block,
322	            post_batch: submitted_post_batch,
323	        } = header;
324	        let submitted_post_batch = submitted_post_batch.ok_or(WindowError::MissingPostBatch)?;
325	        // List every wire field explicitly so schema additions require a
326	        // deliberate retention, validation, or discard decision here.
327	        let PostBatch {
328	            // This non-authoritative Composer claim is deliberately ignored.
329	            // Only a locally recomputed hash authorized by every pipeline gate
330	            // may be signed.
331	            public_inputs_hash: _composer_claimed_public_inputs_hash,
332	            l1_block_hash: submitted_l1_block_hash,
333	            abi_calldata: submitted_post_batch_calldata,
334	            blobs: submitted_blobs,
335	            posting_context,
336	        } = submitted_post_batch;
337	        let posting_context = posting_context.ok_or(WindowError::MissingPostingContext)?;
338	        let l1_block_hash_len = submitted_l1_block_hash.len();
339	        if l1_block_hash_len != 0 {
340	            return Err(WindowError::NonemptyL1BlockHash {
341	                actual: l1_block_hash_len,
342	            });
343	        }
344	        if declared_from_block == 0 || declared_from_block > declared_to_block {
345	            return Err(WindowError::InvalidBounds {
346	                from: declared_from_block,
347	                to: declared_to_block,
348	            });
349	        }
350	        // The checked nonzero, ordered bounds make this inclusive span overflow-safe.
351	        let span = declared_to_block - declared_from_block + 1;
352	        let max_blocks = u64::try_from(limits.blocks).unwrap_or(u64::MAX);
353	        if span > max_blocks {
354	            return Err(WindowError::BlockLimit {
355	                from: declared_from_block,
356	                to: declared_to_block,
357	                span,
358	                max: limits.blocks,
359	            });
360	        }
361	        let declared_block_count =
362	            usize::try_from(span).expect("span was bounded by the usize block limit");
363	
364	        Ok(ParsedHeader {
365	            claimed_rollup_id,
366	            admitted: AdmittedHeader {
367	                declared_from_block,
368	                declared_to_block,
369	                submitted_post_batch_calldata,
370	                submitted_blobs,
371	                posting_context,
372	            },
373	            declared_block_count,
374	        })
375	    }
376	}
377	
378	impl WindowAssembler<true> {
379	    /// Account, structurally check, and retain the next block chunk.
380	    ///
381	    /// Accounting precedes some shape checks, so every error is terminal:
382	    /// callers must discard the assembler rather than retry the chunk.
383	    pub(crate) fn push(&mut self, chunk: ProveChunk) -> Result<(), WindowError> {
384	        charge(
385	            &mut self.accounted_payload_bytes,
386	            chunk.encoded_len(),
387	            self.limits.payload_bytes,
388	            |attempted, max| WindowError::PayloadLimit { attempted, max },
389	        )?;
390	
391	        match chunk.kind {
392	            Some(prove_chunk::Kind::Header(_)) => Err(WindowError::DuplicateHeader),
393	            Some(prove_chunk::Kind::Block(block)) => self.push_block(block),
394	            None => Err(WindowError::MissingKind {
395	                chunk_index: 1 + self.blocks.len(),
396	            }),
397	        }
398	    }
399	
400	    /// Finalize after the caller observes EOF, requiring exactly the declared
401	    /// span.
402	    pub(crate) fn finish(self) -> Result<AdmittedWindow, WindowError> {
403	        let header = self.header;
404	        if self.blocks.len() != self.declared_block_count {
405	            return Err(WindowError::Incomplete {
406	                from: header.declared_from_block,
407	                to: header.declared_to_block,
408	                expected: self.declared_block_count,
409	                actual: self.blocks.len(),
410	            });
411	        }
412	        Ok(AdmittedWindow {
413	            header,
414	            blocks: AdmittedBlocks(self.blocks),
415	        })
416	    }
417	
418	    /// Structurally check and retain one block after the admitted header.
419	    fn push_block(&mut self, submitted_block: BlockWitness) -> Result<(), WindowError> {
420	        let block_index = self.blocks.len();
421	        let expected = (self.header.declared_from_block..=self.header.declared_to_block)
422	            .nth(block_index)
423	            .ok_or(WindowError::ExtraBlock {
424	                expected: self.declared_block_count,
425	            })?;
426	        if submitted_block.number != expected {
427	            return Err(WindowError::WrongBlockNumber {
428	                block_index,
429	                expected,
430	                actual: submitted_block.number,
431	            });
432	        }
433	        let BlockWitness {
434	            number: declared_number,
435	            hash: claimed_hash_bytes,
436	            parent_hash: claimed_parent_hash_bytes,
437	            rlp,
438	            witness,
439	        } = submitted_block;
440	        let claimed_hash = B256::try_from(claimed_hash_bytes.as_slice()).map_err(|_| {
441	            WindowError::BlockHashLength {
442	                number: declared_number,
443	                actual: claimed_hash_bytes.len(),
444	            }
445	        })?;
446	        let claimed_parent_hash =
447	            B256::try_from(claimed_parent_hash_bytes.as_slice()).map_err(|_| {
448	                WindowError::ParentHashLength {
449	                    number: declared_number,
450	                    actual: claimed_parent_hash_bytes.len(),
451	                }
452	            })?;
453	        let wire_witness = witness.ok_or(WindowError::MissingWitness {
454	            number: declared_number,
455	        })?;
456	        // Prost has already allocated the decoded vectors. Enforce the item
457	        // quota before conversion allocates the retained Alloy collections.
458	        charge(
459	            &mut self.accounted_witness_items,
460	            wire_witness_item_count(&wire_witness),
461	            self.limits.witness_items,
462	            |attempted, max| WindowError::WitnessItemLimit { attempted, max },
463	        )?;
464	        let witness = into_execution_witness(wire_witness);
465	        // This gate checks adjacency between stream claims; backend validation
466	        // binds each claim to the decoded block RLP.
467	        if let Some(previous) = self.blocks.last()
468	            && claimed_parent_hash != previous.claimed_hash
469	        {
470	            return Err(WindowError::ChainBreak {
471	                number: declared_number,
472	                previous: previous.declared_number,
473	                expected: previous.claimed_hash,
474	                actual: claimed_parent_hash,
475	            });
476	        }
477	
478	        // Grow lazily so an allowed span does not reserve memory before its
479	        // block chunks actually arrive.
480	        self.blocks
481	            .try_reserve(1)
482	            .map_err(|_| WindowError::StorageLimit {
483	                attempted_blocks: block_index.saturating_add(1),
484	            })?;
485	        self.blocks.push(AdmittedBlock {
486	            declared_number,
487	            claimed_hash,
488	            claimed_parent_hash,
489	            rlp,
490	            witness,
491	        });
492	        Ok(())
493	    }
494	}
495	
496	/// Charge a quota counter without overflowing or exceeding its limit.
497	fn charge(
498	    current: &mut usize,
499	    add: usize,
500	    max: usize,
501	    over: impl Fn(usize, usize) -> WindowError,
502	) -> Result<(), WindowError> {
503	    let attempted = current
504	        .checked_add(add)
505	        .ok_or_else(|| over(usize::MAX, max))?;
506	    if attempted > max {
507	        return Err(over(attempted, max));
508	    }
509	    *current = attempted;
510	    Ok(())
511	}
512	
513	/// Convert the protobuf witness into the Alloy type consumed by Stateless.
514	/// Converting each payload into `Bytes` reuses its source allocation.
515	fn into_execution_witness(witness: WireExecutionWitness) -> ExecutionWitness {
516	    let WireExecutionWitness {
517	        state,
518	        codes,
519	        keys,
520	        headers,
521	    } = witness;
522	    ExecutionWitness {
523	        state: state.into_iter().map(Into::into).collect(),
524	        codes: codes.into_iter().map(Into::into).collect(),
525	        keys: keys.into_iter().map(Into::into).collect(),
526	        headers: headers.into_iter().map(Into::into).collect(),
527	    }
528	}
529	
530	/// Count protobuf witness items before allocating the retained representation.
531	fn wire_witness_item_count(witness: &WireExecutionWitness) -> usize {
532	    witness
533	        .state
534	        .len()
535	        .saturating_add(witness.codes.len())
536	        .saturating_add(witness.keys.len())
537	        .saturating_add(witness.headers.len())
538	}
539	
