46	impl PipelineError {
47	    pub(super) const fn phase(&self) -> &'static str {
48	        match self {
49	            Self::Validation(_) => "validation",
50	            Self::Settlement(_) | Self::DeadlineBeforeSettlement => "settlement",
51	        }
52	    }
53	
54	    pub(super) const fn gate(&self) -> &'static str {
55	        match self {
56	            Self::Validation(_) => "execution",
57	            Self::Settlement(error) => error.gate(),
58	            Self::DeadlineBeforeSettlement => "deadline",
59	        }
60	    }
