62	    pub(super) fn status(&self) -> Status {
63	        match self {
64	            Self::Validation(error) => match error {
65	                validate::ValidationError::Rejected(_) => {
66	                    Status::failed_precondition("window validation rejected")
67	                }
68	                validate::ValidationError::InvalidBackendOutput(_) => {
69	                    Status::internal("validation backend returned invalid output")
70	                }
71	                validate::ValidationError::InternalInvariant(_) => {
72	                    Status::internal("request pipeline invariant failed")
73	                }
74	                validate::ValidationError::Cancelled => {
75	                    Status::cancelled("Prove request cancelled")
76	                }
77	            },
78	            Self::Settlement(error) => error.status(),
79	            Self::DeadlineBeforeSettlement => {
80	                Status::deadline_exceeded("Prove request deadline exceeded")
81	            }
82	        }
83	    }
84	}
