86	/// Re-execute the window and immediately bind its evidence to settlement.
87	///
88	/// Keeping both CPU-bound phases in one worker avoids a second blocking-task
89	/// handoff and prevents callers from handling parallel output/block vectors.
90	pub(super) fn validate_and_settle(
91	    state: &ServiceState,
92	    blocks: window::AdmittedBlocks,
93	    submitted_post_batch_calldata: Vec<u8>,
94	    submitted_blobs: Vec<Vec<u8>>,
95	    maximum_blobs: usize,
96	    deadline: Instant,
97	    cancellation: &CancellationToken,
98	) -> Result<AttestationMaterial, PipelineError> {
99	    let validated_window = state.validator.validate_window(blocks, cancellation)?;
100	    if Instant::now() >= deadline {
101	        return Err(PipelineError::DeadlineBeforeSettlement);
102	    }
103	    let (attestable_public_inputs_hash, observation_claims) = run_settlement_with_observations(
104	        SettlementInput {
105	            submitted_post_batch_calldata,
106	            submitted_blobs: &submitted_blobs,
107	            validated_window: &validated_window,
108	            expected_rollup_id: state.expected_rollup_id,
109	            expected_l2_system_address: state.expected_l2_system_address,
110	            proof_system_vkey: state.attester.proof_system_vkey(),
111	            expected_proof_system: state.attester.expected_proof_system(),
112	            system_transaction_reconstructor: &state.system_transaction_reconstructor,
113	            cancellation,
114	        },
115	        maximum_blobs,
116	    )?;
117	    ensure_settlement_active(cancellation)?;
118	    if Instant::now() >= deadline {
119	        return Err(PipelineError::DeadlineBeforeSettlement);
120	    }
121	    state
122	        .validator
123	        .verify_observations(&validated_window, &observation_claims)
124	        .map_err(SettlementPipelineError::from)?;
125	
126	    Ok(AttestationMaterial {
127	        attestable_public_inputs: attestable_public_inputs_hash,
128	        validated_window_pre_block_hash: validated_window.window_pre_block_hash(),
129	        validated_window_post_block_hash: validated_window.window_post_block_hash(),
130	    })
131	}
