201	    /// Map every pipeline error to its public gRPC code and message.
202	    pub(super) fn status(&self) -> Status {
203	        if let Self::Actionable { source, failure } = self {
204	            let status = source.status();
205	            debug_assert_eq!(status.code(), tonic::Code::FailedPrecondition);
206	            return Status::with_details(
207	                status.code(),
208	                status.message(),
209	                eez_control_rpc::encode_prove_failure(failure).into(),
210	            );
211	        }
212	
213	        let (code, message) = match self {
214	            Self::Actionable { .. } => unreachable!("handled above"),
215	            Self::PostBatchCalldata(_) => {
216	                (tonic::Code::InvalidArgument, "invalid PostBatch calldata")
217	            }
218	            Self::PublicInputs(
