230	                    "validation backend returned invalid output",
231	                ),
232	                settlement::BlockInspectionError::IntermediateSystemTransaction { .. }
233	                | settlement::BlockInspectionError::IntermediateOutboundEvent { .. }
234	                | settlement::BlockInspectionError::RevertedSystemTransaction { .. }
235	                | settlement::BlockInspectionError::ReservedSystemSender { .. } => (
236	                    tonic::Code::FailedPrecondition,
237	                    "settlement validation rejected",
238	                ),
239	            },
240	            Self::EffectPrefix(error) => match error {
241	                settlement::EffectPrefixError::TransactionStateCheckpointCountMismatch {
242	                    ..
243	                }
244	                | settlement::EffectPrefixError::TransactionStateCheckpointIndexMismatch {
245	                    ..
246	                } => (
247	                    tonic::Code::Internal,
248	                    "validation backend returned invalid output",
249	                ),
250	                settlement::EffectPrefixError::LeadingEntryNotAnchor { .. }
251	                | settlement::EffectPrefixError::InvalidEntry { .. }
252	                | settlement::EffectPrefixError::LaterAnchor { .. }
253	                | settlement::EffectPrefixError::EffectCountMismatch { .. }
254	                | settlement::EffectPrefixError::AnchorRootMismatch { .. }
255	                | settlement::EffectPrefixError::EffectKindMismatch { .. }
256	                | settlement::EffectPrefixError::EffectBlockHashMismatch { .. }
257	                | settlement::EffectPrefixError::NonZeroAnchorEtherDelta { .. }
258	                | settlement::EffectPrefixError::InvalidEffectTransactionLayout { .. } => (
259	                    tonic::Code::FailedPrecondition,
