261	                ),
262	            },
263	            Self::PublicInputs(settlement::PublicInputError::InvalidStructure(_))
264	            | Self::RootUpdateChain(_)
265	            | Self::InboundEffects(_)
266	            | Self::OutboundEffects(_)
267	            | Self::BlobSemantics(_)
268	            | Self::ObservationReplay(_) => (
