271	            ),
272	            Self::DaPayload(error) => match error {
273	                settlement::DaPayloadError::Decode { .. }
274	                | settlement::DaPayloadError::TrailingBytes { .. } => (
275	                    tonic::Code::InvalidArgument,
276	                    "invalid blob operations payload",
277	                ),
278	                settlement::DaPayloadError::InvalidBlockRlp { .. }
279	                | settlement::DaPayloadError::SystemTransactionReconstruction { .. }
280	                | settlement::DaPayloadError::InvalidEffectTransactionLayout => (
281	                    tonic::Code::Internal,
282	                    "validation backend returned invalid output",
283	                ),
284	                settlement::DaPayloadError::BlockCount { .. }
285	                | settlement::DaPayloadError::BlockRlpMismatch { .. }
286	                | settlement::DaPayloadError::UnexpectedItems { .. }
287	                | settlement::DaPayloadError::ProjectedTransactionCount { .. }
288	                | settlement::DaPayloadError::TransactionMismatch { .. }
289	                | settlement::DaPayloadError::MissingL2Entry { .. }
290	                | settlement::DaPayloadError::L2EntryMismatch { .. }
291	                | settlement::DaPayloadError::OutboundGroupSizes
292	                | settlement::DaPayloadError::SyncBlockTransactionCount { .. }
293	                | settlement::DaPayloadError::SyncBlockTransactionMismatch { .. } => (
294	                    tonic::Code::FailedPrecondition,
295	                    "settlement validation rejected",
296	                ),
297	            },
298	            Self::BlobDa(_) => (tonic::Code::InvalidArgument, "invalid batch blob DA"),
299	            Self::Cancelled => (tonic::Code::Cancelled, "Prove request cancelled"),
300	        };
301	        Status::new(code, message)
