304	    /// Attach a machine-readable eviction hint without changing the public
305	    /// status code, message, or settlement gate.
306	    fn with_actionable(self, failure: Option<ProveFailure>) -> Self {
307	        match failure {
308	            Some(failure) => Self::Actionable {
309	                source: Box::new(self),
310	                failure,
311	            },
312	            None => self,
313	        }
314	    }
315	}
