317	/// Run the synchronous settlement gates, stopping at the first failure.
318	///
319	/// Cancellation is checked before decoding and before `verify_da_payload`;
320	/// each settlement gate is synchronous and non-interruptible.
321	fn run_settlement_with_observations(
322	    input: SettlementInput<'_>,
323	    maximum_blobs: usize,
324	) -> Result<
325	    (
326	        AttestablePublicInputsHash,
327	        Vec<eez_protocol::settlement::FifoObservationClaim>,
328	    ),
329	    SettlementPipelineError,
330	> {
331	    let SettlementInput {
332	        submitted_post_batch_calldata,
333	        submitted_blobs,
334	        validated_window,
335	        expected_rollup_id,
336	        expected_l2_system_address,
337	        proof_system_vkey,
338	        expected_proof_system,
339	        system_transaction_reconstructor,
340	        cancellation,
341	    } = input;
342	    ensure_settlement_active(cancellation)?;
343	    let settling_block = validated_window.settling_block();
344	    let canonical_batch = settlement::decode_canonical_post_batch(submitted_post_batch_calldata)?;
345	    let checked_public_input_profile = settlement::CheckedPublicInputProfile::new(
346	        &canonical_batch,
347	        expected_rollup_id,
348	        expected_proof_system,
349	    )?;
350	
351	    let verified_state_chain = settlement::verify_root_update_chain(
352	        &canonical_batch,
353	        expected_rollup_id,
354	        validated_window.window_pre_block_hash(),
355	        validated_window.window_post_block_hash(),
356	    )?;
357	
358	    // If an outbound load reverted, report its paired user transaction.
359	    // Reverted inbound deliveries are handled by the inbound gate below.
360	    let settling_observations = settlement::inspect_validated_settling_block(
361	        settling_block.block(),
362	        settling_block.receipt_successes(),
363	        expected_rollup_id,
364	    )
365	    .map_err(|error| {
366	        let failure = actionable_block_inspection_failure(&error, settling_block.block());
367	        SettlementPipelineError::BlockInspection(error).with_actionable(failure)
368	    })?;
369	    settlement::verify_validated_intermediate_blocks(validated_window.preceding_blocks())?;
370	
371	    let bound_effects = settlement::bind_effects_to_execution(
372	        &verified_state_chain,
373	        validated_window.settling_pre_block_hash(),
374	        settling_block.transaction_state_checkpoints(),
375	        &settling_observations,
376	    )?;
377	
378	    // Direction-specific gates turn the ordered bindings into the only effect
379	    // capabilities accepted by exact DA reconstruction.
380	    let authorized_inbound_effects = settlement::authorize_inbound_effects(
381	        &bound_effects,
382	        expected_rollup_id,
383	        expected_l2_system_address,
384	    )
385	    .map_err(|error| {
386	        let failure = actionable_inbound_failure(&error, &canonical_batch);
387	        SettlementPipelineError::InboundEffects(error).with_actionable(failure)
388	    })?;
389	    let authorized_outbound_effects = settlement::authorize_outbound_effects(
390	        &bound_effects,
391	        expected_rollup_id,
392	        expected_l2_system_address,
393	    )
394	    .map_err(|error| {
395	        let failure = actionable_outbound_failure(&error, settling_block.block());
396	        SettlementPipelineError::OutboundEffects(error).with_actionable(failure)
397	    })?;
398	
399	    ensure_settlement_active(cancellation)?;
400	
401	    let verified_da = settlement::verify_da_carrier_with_limit(
402	        &canonical_batch,
403	        submitted_blobs,
404	        expected_rollup_id.get(),
405	        maximum_blobs,
406	    )?;
407	
408	    // Bind posted transactions and effect sidecars to the validated block bytes,
409	    // including the reconstructed Sync-block transaction sequence.
410	    settlement::verify_da_payload(
411	        verified_da.payload(),
412	        validated_window,
413	        &authorized_outbound_effects,
414	        &authorized_inbound_effects,
415	        system_transaction_reconstructor,
416	    )?;
417	    let observation_claims = settlement::verify_native_semantics_with_observations(
418	        verified_da.semantic_transactions(),
419	        validated_window,
420	        &authorized_outbound_effects,
421	        &authorized_inbound_effects,
422	        &canonical_batch,
423	        expected_rollup_id,
424	    )?;
425	
426	    let recomputed_public_inputs_hash = checked_public_input_profile
427	        .recompute_public_inputs_hash(proof_system_vkey, verified_da.transaction_blob_hashes())?;
428	    Ok((
429	        AttestablePublicInputsHash(recomputed_public_inputs_hash),
430	        observation_claims,
431	    ))
432	}
433	
434	/// Test-only entry point for settlement fixtures that contain no replay-only
435	/// lookup/static observations. Production always consumes and executes the
436	/// claims returned by `run_settlement_with_observations` before signing.
437	#[cfg(test)]
438	pub(super) fn run_settlement(
439	    input: SettlementInput<'_>,
440	) -> Result<AttestablePublicInputsHash, SettlementPipelineError> {
441	    let (hash, observations) =
442	        run_settlement_with_observations(input, eez_blob_codec::MAX_BLOBS_PER_TRANSACTION)?;
443	    assert!(
444	        observations.is_empty(),
445	        "pipeline fixture with observations must exercise validate_and_settle"
446	    );
447	    Ok(hash)
448	}
449	
450	fn actionable_block_inspection_failure(
451	    error: &settlement::BlockInspectionError,
452	    block: &validate::ValidatedBlock,
453	) -> Option<ProveFailure> {
454	    let settlement::BlockInspectionError::RevertedSystemTransaction { index } = error else {
455	        return None;
456	    };
457	    let (transaction_index, transaction_hash) =
458	        settlement::paired_outbound_transaction(block, *index)?;
459	    outbound_failure(transaction_index, transaction_hash)
460	}
461	
462	fn actionable_outbound_failure(
463	    error: &settlement::OutboundEffectError,
464	    block: &validate::ValidatedBlock,
465	) -> Option<ProveFailure> {
466	    let transaction_index = error.poisoned_transaction_index()?;
467	    let transaction_hash = settlement::transaction_hash_at(block, transaction_index)?;
468	    outbound_failure(transaction_index, transaction_hash)
469	}
470	
471	fn outbound_failure(transaction_index: usize, transaction_hash: B256) -> Option<ProveFailure> {
472	    Some(ProveFailure {
473	        actionable_failure: Some(prove_failure::ActionableFailure::Outbound(
474	            OutboundFailure {
475	                transaction_index: transaction_index.try_into().ok()?,
476	                transaction_hash: transaction_hash.as_slice().to_vec(),
477	            },
478	        )),
479	    })
480	}
481	
482	fn actionable_inbound_failure(
483	    error: &settlement::InboundEffectError,
484	    batch: &settlement::CanonicalPostBatch,
485	) -> Option<ProveFailure> {
486	    let entry_index = error.poisoned_entry_index()?;
487	    let entry_hash = batch.entry_hash_at(entry_index)?;
488	    Some(ProveFailure {
489	        actionable_failure: Some(prove_failure::ActionableFailure::Inbound(InboundFailure {
490	            entry_index: entry_index.try_into().ok()?,
491	            entry_hash: entry_hash.as_slice().to_vec(),
492	        })),
493	    })
494	}
495	
496	/// Stop settlement work after its request has been cancelled.
497	fn ensure_settlement_active(
498	    cancellation: &CancellationToken,
499	) -> Result<(), SettlementPipelineError> {
500	    if cancellation.is_cancelled() {
501	        Err(SettlementPipelineError::Cancelled)
502	    } else {
503	        Ok(())
504	    }
505	}
