382	/// Builds [`EthPayloadAttributes`] for the next block.
383	///
384	/// Stage 1 produces minimal valid attributes: a strictly-increasing timestamp
385	/// honoring the caller's target, a placeholder `prev_randao`, a
386	/// caller-configured `suggested_fee_recipient`, and the post-Shanghai /
387	/// post-Cancun fields filled in based on the chainspec.
388	///
389	/// Stage 3 will replace the placeholder `prev_randao` with an L1-derived
390	/// value per the protocol spec (§13.14). Stage 4 will add a hook for
391	/// composer-supplied system transactions.
392	#[derive(Debug, Clone)]
393	pub struct EthAttributesBuilder<ChainSpec> {
394	    chain_spec: Arc<ChainSpec>,
395	    suggested_fee_recipient: Address,
396	}
397	
398	impl<ChainSpec> EthAttributesBuilder<ChainSpec> {
399	    /// Creates a builder using the given chainspec and a zero fee recipient.
400	    #[must_use]
401	    pub const fn new(chain_spec: Arc<ChainSpec>) -> Self {
402	        Self {
403	            chain_spec,
404	            suggested_fee_recipient: Address::ZERO,
405	        }
406	    }
407	
408	    /// Configures the `suggested_fee_recipient` field on built attributes.
409	    #[must_use]
410	    pub const fn with_fee_recipient(mut self, recipient: Address) -> Self {
411	        self.suggested_fee_recipient = recipient;
412	        self
413	    }
414	}
415	
416	impl<ChainSpec> EthAttributesBuilder<ChainSpec>
417	where
418	    ChainSpec: EthChainSpec + EthereumHardforks + Send + Sync + 'static,
419	{
420	    /// Builds attributes for the block following `parent` with timestamp
421	    /// `target_timestamp` (clamped upward to preserve strict monotonicity).
422	    #[must_use]
423	    pub fn build(
424	        &self,
425	        parent: &SealedHeader<ChainSpec::Header>,
426	        target_timestamp: u64,
427	    ) -> EthPayloadAttributes {
428	        let timestamp = core::cmp::max(parent.timestamp().saturating_add(1), target_timestamp);
429	        EthPayloadAttributes {
430	            timestamp,
431	            // TODO(stage 3): derive from L1 per spec §13.14. Zeroed for
432	            // stage 1 — no security depends on prev_randao yet.
433	            prev_randao: B256::ZERO,
434	            suggested_fee_recipient: self.suggested_fee_recipient,
435	            withdrawals: self
436	                .chain_spec
437	                .is_shanghai_active_at_timestamp(timestamp)
438	                .then(Default::default),
439	            parent_beacon_block_root: self
440	                .chain_spec
441	                .is_cancun_active_at_timestamp(timestamp)
442	                .then_some(B256::ZERO),
443	            // Amsterdam-fork addition; not active for stage-1 dev chains.
444	            slot_number: None,
445	        }
446	    }
447	}
