531	    /// Runs the sequencer loop until cancellation. Errors during advance
532	    /// are logged and the loop continues; channel-closed = Scheduler
533	    /// task exited, Sequencer exits cleanly.
534	    pub async fn run(mut self) {
535	        let mut fcu_interval = tokio::time::interval(FCU_REFRESH);
536	        loop {
537	            tokio::select! {
538	                maybe_event = self.schedule_rx.recv() => {
539	                    let Some(event) = maybe_event else {
540	                        event!(
541	                            name: "eez.sequencer.schedule_rx.closed",
542	                            Level::ERROR,
543	                            "schedule channel closed; sequencer task exiting",
544	                        );
545	                        break;
546	                    };
547	                    if let Err(err) = self.advance(event).await {
548	                        event!(
549	                            name: "eez.sequencer.advance.failed",
550	                            Level::ERROR,
551	                            error = %err,
552	                            "advance failed: {{error}}",
553	                        );
554	                    }
555	                }
556	                _ = fcu_interval.tick() => {
557	                    if let Err(err) = self.committer.refresh_forkchoice().await {
558	                        event!(
559	                            name: "eez.sequencer.fcu.failed",
560	                            Level::WARN,
561	                            error = %err,
562	                            "forkchoice refresh failed: {{error}}",
563	                        );
564	                    }
565	                }
566	            }
567	        }
568	    }
