570	    /// Dispatch on slot event variant.
571	    async fn advance(&mut self, event: SlotEvent) -> DriverResult<()> {
572	        match event {
573	            SlotEvent::SyncSlot {
574	                block_height,
575	                timestamp,
576	                l1_head,
577	            } => {
578	                self.advance_sync_slot(block_height, timestamp, l1_head)
579	                    .await
580	            }
581	            SlotEvent::LiveTick {
582	                sync_slot_block_height,
583	            } => {
584	                self.advance_anchored_live_tick(sync_slot_block_height)
585	                    .await
586	            }
587	        }
588	    }
589	
590	    /// L1-anchored wall-clock tick handler: commit exactly ONE Live
591	    /// block, and only while the head is below the live region of the
592	    /// next sync slot (`sync_slot_block_height - future_count - 1`).
593	    /// The Future + Sync reserve belongs to the anchor trigger
594	    /// ([`Self::advance_sync_slot`]); ticks no-op once the live region
595	    /// is full, so they can't outrun the anchor.
596	    async fn advance_anchored_live_tick(
597	        &mut self,
598	        sync_slot_block_height: u64,
599	    ) -> DriverResult<()> {
600	        let rollup_id = self.rollup_id;
601	        let composer = Arc::clone(&self.composer);
602	        // Before the head read: a mid-slot verdict would otherwise wait K
603	        // blocks, and recovery can reorg + substitute under us.
604	        composer.recover_failed(rollup_id).await;
605	        let last_header = self.committer.last_header();
606	        let head = last_header.number();
607	        // Reserve = Future blocks + the Sync block itself. Mirrors
608	        // `live_region_end` in `RollupTiming::per_trigger_composition`.
609	        let reserve = u64::from(self.timing.future_count()) + 1;
610	        let live_region_end = sync_slot_block_height.saturating_sub(reserve);
611	        if head >= live_region_end {
612	            // Live region full (steady state between anchor fire and
613	            // the next L1 head). Future + Sync come from the anchor.
614	            return Ok(());
615	        }
616	        if self.speculative_limit_paused(head) {
617	            return Ok(());
618	        }
619	        match self
620	            .commit_one(SlotKind::Live, &last_header, sync_slot_block_height)
621	            .await
622	        {
623	            Ok(()) => Ok(()),
624	            Err(err) if err.is_stale_parent() => {
625	                log_stale_parent("live_tick");
626	                Ok(())
627	            }
628	            Err(err) => Err(err),
629	        }
630	    }
631	
632	    /// True if the bundle (ready at ~`now + proof_time`) can't reach the
633	    /// relay by `sync_slot_timestamp − submission_slack`, i.e. it would miss
634	    /// the immediate next L1 slot. Steady state has headroom; fires only on
635	    /// a late trigger, where the slot is deferred.
636	    fn sync_block_misses_l1_slot(&self, sync_slot_timestamp: u64) -> bool {
637	        let proof_ms = u64::try_from(self.timing.proof_time().as_millis()).unwrap_or(u64::MAX);
638	        let slack_ms =
639	            u64::try_from(self.timing.submission_slack().as_millis()).unwrap_or(u64::MAX);
640	        let ready_ms = crate::slot::now_unix_millis().saturating_add(proof_ms);
641	        let deadline_ms = sync_slot_timestamp
642	            .saturating_mul(1_000)
643	            .saturating_sub(slack_ms);
644	        ready_ms > deadline_ms
645	    }
646	
647	    /// One skip self-heals next trigger; a run of them means production is
648	    /// wedged, so escalate past a few.
649	    fn note_off_grid_skip(&mut self) {
650	        self.off_grid_skips = self.off_grid_skips.saturating_add(1);
651	        if self.off_grid_skips >= 3 {
652	            event!(
653	                name: "eez.sequencer.sync_slot.off_grid_stalled",
654	                Level::ERROR,
655	                consecutive_skips = self.off_grid_skips,
656	                "consecutive Sync blocks skipped for off-grid drift; production is not advancing",
657	            );
658	        }
659	    }
660	
661	    /// L1-anchored handler: read current head, compute the per-trigger
662	    /// Live/Future/Sync split via
663	    /// [`RollupTiming::per_trigger_composition`], produce accordingly.
664	    async fn advance_sync_slot(
665	        &mut self,
666	        sync_slot_block_height: u64,
667	        sync_slot_timestamp: u64,
668	        l1_head: u64,
669	    ) -> DriverResult<()> {
670	        let rollup_id = self.rollup_id;
671	        let composer = Arc::clone(&self.composer);
672	        // Before the composition: a pending verdict would seed the whole burst
673	        // on a doomed head, for compose_sync_slot to reorg away at its end.
674	        composer.recover_failed(rollup_id).await;
675	        let head = self.committer.last_header().number();
676	        // Catchup ignores the speculative cap (a steady-state bound): a
677	        // dropped pb heals by recomposing next trigger, which freezing to
678	        // Idle would block. The steady (Slot) arm still enforces the cap.
679	        let comp = self.timing.per_trigger_composition(
680	            head,
681	            sync_slot_block_height,
682	            crate::MAX_BLOCKS_PER_CATCHUP,
683	        );
684	
685	        event!(
686	            name: "eez.sequencer.sync_slot.composition",
687	            Level::INFO,
688	            head,
689	            sync_slot_block_height,
690	            sync_slot_timestamp,
691	            composition = ?comp,
692	            "computed per-trigger slot composition",
693	        );
694	
695	        // Target an absolute height, not a count. The committer is shared, so a
696	        // count re-derived from a moved head would land the Sync block off-grid.
697	        let terminal = match comp {
698	            SlotComposition::Catchup { live } => Some(head + live + 1),
699	            SlotComposition::Slot { .. } | SlotComposition::Idle => None,
700	        };
701	
702	        match comp {
703	            SlotComposition::Idle => {}
704	            SlotComposition::Catchup { live } => {
705	                // `live` is grid-snapped + capped by per_trigger_composition;
706	                // produce that many Live blocks then the terminal Sync.
707	                for _ in 0..live {
708	                    let last_header = self.committer.last_header();
709	                    // Once the burst reaches this target's Future region, use
710	                    // the ordinary slot layout even though older intervals had
711	                    // to be rebuilt first. Intermediate Sync boundaries remain
712	                    // empty through commit_one's existing grid guard.
713	                    let live_end = sync_slot_block_height
714	                        .saturating_sub(u64::from(self.timing.future_count()) + 1);
715	                    let kind = if terminal == Some(sync_slot_block_height)
716	                        && last_header.number() >= live_end
717	                    {
718	                        SlotKind::Future
719	                    } else {
720	                        SlotKind::Live
721	                    };
722	                    match self
723	                        .commit_one(kind, &last_header, sync_slot_block_height)
724	                        .await
725	                    {
726	                        Ok(()) => {}
727	                        Err(err) if err.is_stale_parent() => {
728	                            log_stale_parent("catchup.live");
729	                            return Ok(());
730	                        }
731	                        Err(err) => return Err(err),
732	                    }
733	                }
734	
735	                // A capped/past terminal remains structural-only. If catch-up
736	                // reached the actual future target, recheck its timestamp and
737	                // deadline now: beginning the tick behind must not cost another
738	                // otherwise eligible L1 opportunity.
739	                if terminal != Some(self.committer.last_header().number() + 1) {
740	                    event!(
741	                        name: "eez.sequencer.sync_slot.off_grid_skipped",
742	                        Level::WARN,
743	                        head_now = self.committer.last_header().number(),
744	                        terminal = ?terminal,
745	                        "head moved during the burst; skipping the Sync block rather than placing it off-grid",
746	                    );
747	                    self.note_off_grid_skip();
748	                    return Ok(());
749	                }
750	                let last_header = self.committer.last_header();
751	                let sync_ts = last_header
752	                    .timestamp()
753	                    .saturating_add(self.timing.l2_block_time().as_secs());
754	
755	                let can_settle = terminal == Some(sync_slot_block_height)
756	                    && sync_ts == sync_slot_timestamp
757	                    && !self.sync_block_misses_l1_slot(sync_ts)
758	                    && !self.speculative_limit_paused(last_header.number());
759	                let (target, mode) = if can_settle {
760	                    (Some(l1_head + 1), SyncSlotMode::Steady)
761	                } else {
762	                    (None, SyncSlotMode::Catchup)
763	                };
764	
765	                let parent = crate::slot::ParentContext {
766	                    header: last_header.clone(),
767	                };
768	                let prebuilt = composer
769	                    .compose_sync_slot_outcome(rollup_id, parent, sync_ts, target, mode)
770	                    .await;
771	                let prebuilt = match prebuilt {
772	                    crate::SyncSlotOutcome::Built(built) => Some(*built),
773	                    crate::SyncSlotOutcome::LegacyPool => None,
774	                    crate::SyncSlotOutcome::EndTick => return Ok(()),
775	                };
776	                if let Some(built) = prebuilt {
777	                    if let Err(err) = self.commit_one_prebuilt(SlotKind::Sync, built).await {
778	                        if err.is_stale_parent() {
779	                            log_stale_parent("catchup.sync.prebuilt");
780	                            return Ok(());
781	                        }
782	                        return Err(err);
783	                    }
784	                    self.off_grid_skips = 0;
785	                } else {
786	                    match self
787	                        .commit_one(SlotKind::Sync, &last_header, sync_slot_block_height)
788	                        .await
789	                    {
790	                        Ok(()) => {}
791	                        Err(err) if err.is_stale_parent() => {
792	                            log_stale_parent("catchup.sync");
793	                            return Ok(());
794	                        }
795	                        Err(err) => return Err(err),
796	                    }
797	                    self.off_grid_skips = 0;
798	                }
799	            }
800	            SlotComposition::Slot { live, future } => {
801	                for _ in 0..live {
802	                    let last_header = self.committer.last_header();
803	                    if self.speculative_limit_paused(last_header.number()) {
804	                        return Ok(()); // Defer Future + Sync to next trigger.
805	                    }
806	                    match self
807	                        .commit_one(SlotKind::Live, &last_header, sync_slot_block_height)
808	                        .await
809	                    {
810	                        Ok(()) => {}
811	                        Err(err) if err.is_stale_parent() => {
812	                            log_stale_parent("slot.live");
813	                            return Ok(());
814	                        }
815	                        Err(err) => return Err(err),
816	                    }
817	                }
818	                for _ in 0..future {
819	                    let last_header = self.committer.last_header();
820	                    if self.speculative_limit_paused(last_header.number()) {
821	                        return Ok(()); // Defer remaining Future + Sync to next trigger.
822	                    }
823	                    match self
824	                        .commit_one(SlotKind::Future, &last_header, sync_slot_block_height)
825	                        .await
826	                    {
827	                        Ok(()) => {}
828	                        Err(err) if err.is_stale_parent() => {
829	                            log_stale_parent("slot.future");
830	                            return Ok(());
831	                        }
832	                        Err(err) => return Err(err),
833	                    }
834	                }
835	                let last_header = self.committer.last_header();
836	                if self.speculative_limit_paused(last_header.number()) {
