842	                if expected_sync_ts != sync_slot_timestamp {
843	                    // The head moved under us. This block would settle, and an
844	                    // off-grid root wedges the deriver. Skip; next trigger realigns.
845	                    event!(
846	                        name: "eez.sequencer.sync_slot.off_grid_skipped",
847	                        Level::WARN,
