858	                // Defer-on-lateness: a late trigger that can't land the bundle
859	                // in the next L1 slot commits an empty block and holds the pool
860	                // (next slot covers it). Else drain into a prebuilt Sync block.
861	                // Check against expected_sync_ts — the ts the bundle is pinned
862	                // to below — so an off-grid trigger already past its pin defers
863	                // instead of composing a bundle that can't make its slot.
864	                let prebuilt = if self.sync_block_misses_l1_slot(expected_sync_ts) {
865	                    event!(
