904	                let prebuilt = match prebuilt {
905	                    crate::SyncSlotOutcome::Built(built) => Some(*built),
906	                    crate::SyncSlotOutcome::LegacyPool => None,
907	                    crate::SyncSlotOutcome::EndTick => return Ok(()),
908	                };
909	                if let Some(built) = prebuilt {
910	                    match self.commit_one_prebuilt(SlotKind::Sync, built).await {
911	                        Ok(()) => {}
912	                        Err(err) if err.is_stale_parent() => {
913	                            log_stale_parent("slot.sync.prebuilt");
914	                        }
915	                        Err(err) => return Err(err),
916	                    }
917	                    self.off_grid_skips = 0;
918	                    return Ok(());
919	                }
920	
921	                match self
922	                    .commit_one(SlotKind::Sync, &last_header, sync_slot_block_height)
923	                    .await
924	                {
925	                    Ok(()) => {}
926	                    Err(err) if err.is_stale_parent() => {
927	                        log_stale_parent("slot.sync");
928	                        return Ok(());
929	                    }
930	                    Err(err) => return Err(err),
931	                }
932	                self.off_grid_skips = 0;
933	            }
934	        }
935	        Ok(())
936	    }
937	
938	    /// True if the speculative-depth limit is reached; logged at DEBUG.
939	    fn speculative_limit_paused(&self, head_number: u64) -> bool {
940	        if self.max_speculative_depth == 0 {
941	            return false;
942	        }
943	        let confirmed = self.l1_head.cursor();
944	        let speculative_depth = head_number.saturating_sub(confirmed);
945	        if speculative_depth >= self.max_speculative_depth {
946	            event!(
947	                name: "eez.sequencer.speculative.paused",
948	                Level::DEBUG,
949	                head_number,
950	                confirmed,
951	                speculative_depth,
952	                max_depth = self.max_speculative_depth,
953	                "paused: speculative depth at cap; waiting for Deriver to catch up",
954	            );
955	            return true;
956	        }
957	        false
958	    }
959	
960	    /// Commit a pre-built Sync block (from the cross-chain composer)
961	    /// via `commit_derived` — same engine-API tail the Deriver uses
962	    /// for L1-derived blocks. Holds the reconcile lock so a sync-slot
963	    /// commit can't race with a deriver-side reconcile.
964	    async fn commit_one_prebuilt(
965	        &mut self,
966	        kind: SlotKind,
967	        built: crate::slot::SyncSlotBlock,
968	    ) -> DriverResult<()> {
969	        // `commit_derived` doesn't take the lock itself (only
970	        // `commit_sequenced` does, and the Deriver already holds it via
971	        // `begin_reconcile`), so hold it here too.
972	        let _reconcile_guard = self.committer.begin_reconcile().await;
973	        // Stale-parent check under the lock, like commit_sequenced: the
974	        // Deriver (or a failed-batch recovery) can move the head between
975	        // compose and commit, and a prebuilt block on a stale parent
976	        // would silently reorg that newer work via commit_derived's FCU.
977	        let current_head = self.committer.last_header().hash();
978	        let built_parent = built.header.parent_hash();
979	        if current_head != built_parent {
980	            return Err(DriverError::stale_parent(built_parent, current_head));
981	        }
982	        let block_number = built.header.number();
983	        let block_hash = built.header.hash();
984	        let block_timestamp = built.header.timestamp();
985	        let _outcome = self
986	            .committer
987	            // feed_witness=true: this is a PRODUCED Sync block — emit it to the
988	            // prover witness-capture feed (the follower/deriver passes false).
989	            .commit_derived(built.payload, built.header, true)
990	            .await?;
991	
992	        event!(
993	            name: "eez.sequencer.block.produced",
994	            Level::INFO,
995	            slot.kind = %kind,
996	            block.number = block_number,
997	            block.hash = %block_hash,
998	            block.timestamp = block_timestamp,
999	            "produced block {block_number} hash={block_hash} ts={block_timestamp} kind={kind}",
1000	        );
1001	        Ok(())
1002	    }
1003	
1004	    /// Commit one block of the given kind at
1005	    /// `parent.timestamp() + L2_block_time`. Logs `eez.sequencer.block.produced`.
1006	    async fn commit_one(
1007	        &mut self,
1008	        kind: SlotKind,
1009	        parent: &SealedHeader<ChainSpec::Header>,
1010	        sync_slot_height: u64,
1011	    ) -> DriverResult<()> {
1012	        self.composer
1013	            .set_sequencing_target(self.rollup_id, sync_slot_height);
1014	        let parent_hash = parent.hash();
1015	        let parent_ts = parent.timestamp();
1016	        let next_ts = parent_ts.saturating_add(self.timing.l2_block_time().as_secs());
1017	        if kind != SlotKind::Sync
1018	            && self.composer.guards_sequencing_da()
1019	            && parent.number().checked_add(1).is_some_and(|n| {
1020	                n % u64::from(self.timing.k()) == sync_slot_height % u64::from(self.timing.k())
1021	            })
1022	        {
1023	            // Catch-up may span several Sync intervals. Each intermediate grid
1024	            // boundary must remain an admissible historical settlement endpoint.
1025	            let outcome = self
1026	                .composer
1027	                .compose_sync_slot_outcome(
1028	                    self.rollup_id,
1029	                    crate::ParentContext {
1030	                        header: parent.clone(),
1031	                    },
1032	                    next_ts,
1033	                    None,
1034	                    SyncSlotMode::Empty,
1035	                )
1036	                .await;
1037	            return match outcome {
1038	                crate::SyncSlotOutcome::Built(block) => {
1039	                    self.commit_one_prebuilt(SlotKind::Sync, *block).await
1040	                }
1041	                _ => Err(DriverError::invalid_forkchoice(
1042	                    "required empty DA boundary unavailable".to_owned(),
1043	                )),
1044	            };
1045	        }
1046	        let attrs = self.attributes.build(parent, next_ts);
1047	        let timestamp = attrs.timestamp;
1048	        let outcome = self.committer.commit_sequenced(parent_hash, attrs).await?;
1049	        let block_number = outcome.header.number();
1050	        let block_hash = outcome.header.hash();
1051	
1052	        event!(
1053	            name: "eez.sequencer.block.produced",
1054	            Level::INFO,
1055	            slot.kind = %kind,
1056	            block.number = block_number,
1057	            block.hash = %block_hash,
1058	            block.timestamp = timestamp,
1059	            "produced block {block_number} hash={block_hash} ts={timestamp} kind={kind}",
1060	        );
1061	        Ok(())
1062	    }
1063	}
