//! Engine-API consumer that advances the chain on a 2s cadence aligned to
//! wall-clock time, with **greedy backfill** of any timestamp slots that
//! were missed due to a reorg or downtime.
//!
//! [`Sequencer::run`] is the long-running loop. Each iteration handles one
//! of:
//!
//! 1. A scheduler tick. `Sequencer::advance` runs in a loop, producing
//!    blocks at deterministic `parent.timestamp() + BLOCK_TIME_SECS`
//!    slots until the chain catches up to the tick's wall-clock target.
//!    Most ticks produce a single block (the chain is on cadence); after
//!    a reorg or a stall, the same tick may produce several filler
//!    blocks to backfill the slots that passed during the rewind.
//! 2. A slower FCU-refresh timer, used to keep reth's engine view alive
//!    during quiet periods.
//!
//! The Sequencer does **not** keep a local mirror of the canonical head.
//! Every iteration of `advance` reads the current head from the
//! [`BlockCommitterHandle::last_header`] — the actor is the single source
//! of truth, updated synchronously inside every Sequence + Derive command.
//! This is what fixes the race where the Deriver-driven canonical change
//! was visible to the actor immediately, but the Sequencer's own mirror
//! lagged behind reth's `CanonStateNotification` broadcast — producing
//! "invalid payload attributes" errors when the Sequencer issued FCU+attrs
//! based on a stale parent.

use core::fmt;
use std::{sync::Arc, time::Duration};

use alloy_primitives::{Address, B256};
use reth_chainspec::{EthChainSpec, EthereumHardforks};
use reth_ethereum_engine_primitives::EthPayloadAttributes;
use reth_payload_primitives::{BuiltPayload, PayloadTypes};
use reth_primitives_traits::{
    AlloyBlockHeader, HeaderTy, NodePrimitives, SealedHeader, SealedHeaderFor,
};
use tracing::{Level, event};

use tokio::sync::mpsc;

use crate::block_committer::BlockCommitterHandle;
use crate::error::{DriverError, DriverResult};
use crate::slot::{SlotEvent, SlotKind, SyncSlotComposerHandle, SyncSlotMode};
use crate::timing::{RollupTiming, SlotComposition};

/// How often the sequencer re-publishes the current forkchoice state.
///
/// Even when no new block is being proposed, sending an FCU keeps reth's
/// engine convinced the chain is alive. Mirrors the cadence reth's own dev
/// miner uses.
const FCU_REFRESH: Duration = Duration::from_secs(1);

/// Max speculative gap the Sequencer can run ahead of L1-confirmed
/// cursor. Pauses beyond this so reth's state-retention
/// window keeps recent ancestors alive for the Deriver's replay.
pub const DEFAULT_MAX_SPECULATIVE_DEPTH: u64 = 64;

/// Log a benign stale-parent skip: the Deriver advanced the canonical
/// head between our snapshot and the engine FCU, so this commit
/// targeted a no-longer-canonical parent. The caller bails (its
/// backfill loop or the whole trigger) and the next trigger rebuilds
/// from the fresh head. `phase` names the commit site for attribution.
fn log_stale_parent(phase: &str) {
    event!(
        name: "eez.sequencer.stale_parent",
        Level::DEBUG,
        phase,
        "deriver advanced the chain under this commit; bailing — next trigger rebuilds from fresh head",
    );
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::slot::{ParentContext, SyncSlotBlock, SyncSlotComposer, SyncSlotOutcome};
    use std::sync::Mutex;

    struct PolicyComposer {
        result: &'static str,
        calls: Arc<Mutex<Vec<SyncSlotMode>>>,
        guard: bool,
    }

    #[async_trait::async_trait]
    impl SyncSlotComposer for PolicyComposer {
        fn guards_sequencing_da(&self) -> bool {
            self.guard
        }
        async fn compose_sync_slot(
            &self,
            _: u64,
            _: ParentContext,
            _: u64,
            _: Option<u64>,
            _: SyncSlotMode,
        ) -> Option<SyncSlotBlock> {
            panic!("explicit outcome interface is required");
        }

        async fn compose_sync_slot_outcome(
            &self,
            _: u64,
            parent: ParentContext,
            timestamp: u64,
            target: Option<u64>,
            mode: SyncSlotMode,
        ) -> SyncSlotOutcome {
            assert_eq!(target.is_some(), mode == SyncSlotMode::Steady);
            self.calls.lock().unwrap().push(mode);
            if self.result == "end" {
                return SyncSlotOutcome::EndTick;
            }
            let header = SealedHeader::seal_slow(alloy_consensus::Header {
                parent_hash: if self.result == "stale" {
                    B256::ZERO
                } else {
                    parent.header.hash()
                },
                number: parent.header.number + 1,
                timestamp,
                transactions_root: alloy_consensus::constants::EMPTY_ROOT_HASH,
                ..Default::default()
            });
            SyncSlotOutcome::Built(Box::new(SyncSlotBlock {
                payload: alloy_rpc_types_engine::ExecutionData::from_block_unchecked(
                    header.hash(),
                    &alloy_consensus::Block::<alloy_consensus::TxEnvelope>::new(
                        header.clone().unseal(),
                        Default::default(),
                    ),
                ),
                header,
            }))
        }
    }

    struct LegacyComposer;
    #[async_trait::async_trait]
    impl SyncSlotComposer for LegacyComposer {
        async fn compose_sync_slot(
            &self,
            _: u64,
            _: ParentContext,
            _: u64,
            _: Option<u64>,
            _: SyncSlotMode,
        ) -> Option<SyncSlotBlock> {
            None
        }
    }

    #[tokio::test]
    async fn explicit_policy_outcomes_never_use_sync_pool_fallback_in_any_slot_mode() {
        for mode in [
            SyncSlotMode::Steady,
            SyncSlotMode::Empty,
            SyncSlotMode::Catchup,
        ] {
            for result in ["end", "empty", "stale", "legacy"] {
                let future = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap()
                    .as_secs()
                    + 3600;
                let timestamp = if mode == SyncSlotMode::Empty {
                    1
                } else {
                    future
                };
                let parent = SealedHeader::seal_slow(alloy_consensus::Header {
                    number: 4,
                    timestamp: timestamp - 1,
                    ..Default::default()
                });
                let (committer, commands) = crate::block_committer::test_committer(parent);
                let calls = Arc::new(Mutex::new(Vec::new()));
                let composer: SyncSlotComposerHandle = if result == "legacy" {
                    Arc::new(LegacyComposer)
                } else {
                    Arc::new(PolicyComposer {
                        result,
                        calls: Arc::clone(&calls),
                        guard: false,
                    })
                };
                let (_, receiver) = mpsc::channel(1);
                let mut sequencer = Sequencer::composer(
                    EthAttributesBuilder::new(Arc::new(reth_chainspec::ChainSpec::default())),
                    committer.clone(),
                    receiver,
                    RollupTiming::new(5000, 1000, 1000, 100),
                    1,
                    composer,
                    0,
                    Arc::default(),
                );
                let target = if mode == SyncSlotMode::Catchup { 15 } else { 5 };
                sequencer
                    .advance_sync_slot(target, timestamp, 1)
                    .await
                    .unwrap();
                let commands = commands.lock().unwrap();
                let live = usize::try_from(target - 5).unwrap();
                if result != "legacy" {
                    assert_eq!(*calls.lock().unwrap(), vec![mode]);
                }
                assert!(commands[..live].iter().all(|command| *command == "pool"));
                match result {
                    "end" | "stale" => {
                        assert_eq!(commands.len(), live, "{mode:?}/{result}");
                        assert_eq!(committer.last_header().number, target - 1);
                    }
                    "empty" => {
                        assert_eq!(&commands[live..], &["prebuilt"]);
                        assert_eq!(committer.last_header().number, target);
                        assert_eq!(
                            committer.last_header().transactions_root,
                            alloy_consensus::constants::EMPTY_ROOT_HASH
                        );
                    }
                    "legacy" => {
                        assert_eq!(&commands[live..], &["pool"]);
                        assert_ne!(
                            committer.last_header().transactions_root,
                            alloy_consensus::constants::EMPTY_ROOT_HASH
                        );
                    }
                    _ => unreachable!(),
                }
            }
        }
    }
    #[tokio::test]
    async fn guarded_catchup_preserves_every_intermediate_empty_boundary() {
        for k in [5, 6, 12] {
            for residue in 0..k {
                for result in ["empty", "end", "stale"] {
                    let parent = SealedHeader::seal_slow(alloy_consensus::Header {
                        number: k - 1 + residue,
                        timestamp: 100,
                        ..Default::default()
                    });
                    let (committer, commands) = crate::block_committer::test_committer(parent);
                    let calls = Arc::new(Mutex::new(Vec::new()));
                    let (_, receiver) = mpsc::channel(1);
                    let mut sequencer = Sequencer::composer(
                        EthAttributesBuilder::new(Arc::new(reth_chainspec::ChainSpec::default())),
                        committer.clone(),
                        receiver,
                        RollupTiming::new(u32::try_from(k * 1000).unwrap(), 1000, 1000, 100),
                        1,
                        Arc::new(PolicyComposer {
                            result,
                            calls: calls.clone(),
                            guard: true,
                        }),
                        0,
                        Arc::default(),
                    );
                    for _ in 0..=(k * 2) {
                        let parent = committer.last_header();
                        let outcome = sequencer
                            .commit_one(SlotKind::Live, &parent, 3 * k + residue)
                            .await;
                        if result != "empty" {
                            assert!(outcome.is_err());
                            assert_eq!(committer.last_header().number, k - 1 + residue);
                            assert!(
                                commands.lock().unwrap().is_empty(),
                                "failed empty boundary must not use the mempool"
                            );
                            break;
                        }
                        outcome.unwrap();
                        if committer.last_header().number % k == residue {
                            assert_eq!(
                                committer.last_header().transactions_root,
                                alloy_consensus::constants::EMPTY_ROOT_HASH
                            );
                        }
                    }
                    if result == "empty" {
                        assert_eq!(*calls.lock().unwrap(), vec![SyncSlotMode::Empty; 3]);
                        assert_eq!(
                            commands
                                .lock()
                                .unwrap()
                                .iter()
                                .filter(|command| **command == "prebuilt")
                                .count(),
                            3
                        );
                    }
                }
            }
        }
    }

    #[tokio::test]
    async fn catchup_can_use_the_current_future_slot_but_never_a_past_or_capped_slot() {
        for k in [5, 6, 12] {
            for residue in 0..k {
                for case in ["aligned", "late", "misaligned", "capped", "speculative_cap"] {
                    let start = k - 1 + residue;
                    let target = if case == "capped" { 1000 * k } else { 3 * k } + residue;
                    let timestamp = if case == "late" {
                        100_000
                    } else {
                        crate::slot::now_unix_millis() / 1000 + 3600
                    };
                    let parent = SealedHeader::seal_slow(alloy_consensus::Header {
                        number: start,
                        timestamp: timestamp - (target - start) + u64::from(case == "misaligned"),
                        ..Default::default()
                    });
                    let (committer, commands) = crate::block_committer::test_committer(parent);
                    let calls = Arc::new(Mutex::new(Vec::new()));
                    let (_, receiver) = mpsc::channel(1);
                    let timing =
                        RollupTiming::new(u32::try_from(k * 1000).unwrap(), 1000, 500, 700)
                            .with_preparation_time_ms(500);
                    let mut sequencer = Sequencer::composer(
                        EthAttributesBuilder::new(Arc::new(reth_chainspec::ChainSpec::default())),
                        committer.clone(),
                        receiver,
                        timing,
                        1,
                        Arc::new(PolicyComposer {
                            result: "empty",
                            calls: Arc::clone(&calls),
                            guard: true,
                        }),
                        u64::from(case == "speculative_cap"),
                        Arc::default(),
                    );
                    sequencer
                        .advance_sync_slot(target, timestamp, 100)
                        .await
                        .unwrap();
                    let calls = calls.lock().unwrap();
                    assert_eq!(
                        *calls.last().unwrap(),
                        if case == "aligned" {
                            SyncSlotMode::Steady
                        } else {
                            SyncSlotMode::Catchup
                        },
                        "K={k}, residue={residue}, {case}",
                    );
                    assert!(
                        calls[..calls.len() - 1]
                            .iter()
                            .all(|mode| *mode == SyncSlotMode::Empty)
                    );
                    let final_header = committer.last_header();
                    assert_eq!(final_header.number % k, residue);
                    assert_eq!(
                        final_header.transactions_root,
                        alloy_consensus::constants::EMPTY_ROOT_HASH
                    );
                    if case == "capped" {
                        assert!(final_header.number < target);
                        assert!(final_header.number - start <= crate::MAX_BLOCKS_PER_CATCHUP);
                    } else {
                        assert_eq!(final_header.number, target);
                    }
                    assert_eq!(
                        commands
                            .lock()
                            .unwrap()
                            .iter()
                            .filter(|c| **c == "prebuilt")
                            .count(),
                        calls.len()
                    );
                }
            }
        }
    }
}

/// Builds [`EthPayloadAttributes`] for the next block.
///
/// Stage 1 produces minimal valid attributes: a strictly-increasing timestamp
/// honoring the caller's target, a placeholder `prev_randao`, a
/// caller-configured `suggested_fee_recipient`, and the post-Shanghai /
/// post-Cancun fields filled in based on the chainspec.
///
/// Stage 3 will replace the placeholder `prev_randao` with an L1-derived
/// value per the protocol spec (§13.14). Stage 4 will add a hook for
/// composer-supplied system transactions.
#[derive(Debug, Clone)]
pub struct EthAttributesBuilder<ChainSpec> {
    chain_spec: Arc<ChainSpec>,
    suggested_fee_recipient: Address,
}

impl<ChainSpec> EthAttributesBuilder<ChainSpec> {
    /// Creates a builder using the given chainspec and a zero fee recipient.
    #[must_use]
    pub const fn new(chain_spec: Arc<ChainSpec>) -> Self {
        Self {
            chain_spec,
            suggested_fee_recipient: Address::ZERO,
        }
    }

    /// Configures the `suggested_fee_recipient` field on built attributes.
    #[must_use]
    pub const fn with_fee_recipient(mut self, recipient: Address) -> Self {
        self.suggested_fee_recipient = recipient;
        self
    }
}

impl<ChainSpec> EthAttributesBuilder<ChainSpec>
where
    ChainSpec: EthChainSpec + EthereumHardforks + Send + Sync + 'static,
{
    /// Builds attributes for the block following `parent` with timestamp
    /// `target_timestamp` (clamped upward to preserve strict monotonicity).
    #[must_use]
    pub fn build(
        &self,
        parent: &SealedHeader<ChainSpec::Header>,
        target_timestamp: u64,
    ) -> EthPayloadAttributes {
        let timestamp = core::cmp::max(parent.timestamp().saturating_add(1), target_timestamp);
        EthPayloadAttributes {
            timestamp,
            // TODO(stage 3): derive from L1 per spec §13.14. Zeroed for
            // stage 1 — no security depends on prev_randao yet.
            prev_randao: B256::ZERO,
            suggested_fee_recipient: self.suggested_fee_recipient,
            withdrawals: self
                .chain_spec
                .is_shanghai_active_at_timestamp(timestamp)
                .then(Default::default),
            parent_beacon_block_root: self
                .chain_spec
                .is_cancun_active_at_timestamp(timestamp)
                .then_some(B256::ZERO),
            // Amsterdam-fork addition; not active for stage-1 dev chains.
            slot_number: None,
        }
    }
}

/// Translates scheduler proposals into engine-API `forkchoiceUpdated`
/// then `newPayload` via the [`BlockCommitter`](crate::BlockCommitterHandle).
/// Stateless w.r.t. head — reads `committer.last_header()` (the actor
/// writes synchronously on every Sequence/Derive).
pub struct Sequencer<T, ChainSpec>
where
    T: PayloadTypes<PayloadAttributes = EthPayloadAttributes>,
{
    attributes: EthAttributesBuilder<ChainSpec>,
    schedule_rx: mpsc::Receiver<SlotEvent>,
    committer: BlockCommitterHandle<T>,
    /// Per-rollup timing (L1/L2 cadence, proof window, slack). Used to
    /// compute per-trigger Live/Future/Sync block composition and per-
    /// block timestamps.
    timing: RollupTiming,
    rollup_id: u64,
    composer: SyncSlotComposerHandle,
    max_speculative_depth: u64,
    l1_head: Arc<eez_l1::L1CanonicalHead>,
    /// Consecutive Sync blocks skipped for off-grid drift. A skip self-heals
    /// next trigger; a run of them is a stall and must be loud (invariant 7).
    off_grid_skips: u32,
}

impl<T, ChainSpec> fmt::Debug for Sequencer<T, ChainSpec>
where
    T: PayloadTypes<PayloadAttributes = EthPayloadAttributes>,
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Sequencer")
            .field("committer", &self.committer)
            .field("rollup_id", &self.rollup_id)
            .field("max_speculative_depth", &self.max_speculative_depth)
            .finish_non_exhaustive()
    }
}

impl<T, ChainSpec> Sequencer<T, ChainSpec>
where
    T: PayloadTypes<
            PayloadAttributes = EthPayloadAttributes,
            ExecutionData = alloy_rpc_types_engine::ExecutionData,
        > + Send
        + Sync
        + 'static,
    <T::BuiltPayload as BuiltPayload>::Primitives:
        NodePrimitives<BlockHeader = alloy_consensus::Header> + Send + Sync + 'static,
    SealedHeaderFor<<T::BuiltPayload as BuiltPayload>::Primitives>: Send,
    ChainSpec: EthChainSpec<Header = HeaderTy<<T::BuiltPayload as BuiltPayload>::Primitives>>
        + EthereumHardforks
        + Send
        + Sync
        + 'static,
{
    /// Construct an L1-anchored composer sequencer. All composer-only
    /// dependencies are mandatory and share the binary-owned committer with
    /// the Composer and Deriver.
    #[must_use]
    #[allow(clippy::too_many_arguments)]
    pub fn composer(
        attributes: EthAttributesBuilder<ChainSpec>,
        committer: BlockCommitterHandle<T>,
        schedule_rx: mpsc::Receiver<SlotEvent>,
        timing: RollupTiming,
        rollup_id: u64,
        composer: SyncSlotComposerHandle,
        max_speculative_depth: u64,
        l1_head: Arc<eez_l1::L1CanonicalHead>,
    ) -> Self {
        Self {
            attributes,
            schedule_rx,
            committer,
            timing,
            rollup_id,
            composer,
            max_speculative_depth,
            l1_head,
            off_grid_skips: 0,
        }
    }

    /// Runs the sequencer loop until cancellation. Errors during advance
    /// are logged and the loop continues; channel-closed = Scheduler
    /// task exited, Sequencer exits cleanly.
    pub async fn run(mut self) {
        let mut fcu_interval = tokio::time::interval(FCU_REFRESH);
        loop {
            tokio::select! {
                maybe_event = self.schedule_rx.recv() => {
                    let Some(event) = maybe_event else {
                        event!(
                            name: "eez.sequencer.schedule_rx.closed",
                            Level::ERROR,
                            "schedule channel closed; sequencer task exiting",
                        );
                        break;
                    };
                    if let Err(err) = self.advance(event).await {
                        event!(
                            name: "eez.sequencer.advance.failed",
                            Level::ERROR,
                            error = %err,
                            "advance failed: {{error}}",
                        );
                    }
                }
                _ = fcu_interval.tick() => {
                    if let Err(err) = self.committer.refresh_forkchoice().await {
                        event!(
                            name: "eez.sequencer.fcu.failed",
                            Level::WARN,
                            error = %err,
                            "forkchoice refresh failed: {{error}}",
                        );
                    }
                }
            }
        }
    }

    /// Dispatch on slot event variant.
    async fn advance(&mut self, event: SlotEvent) -> DriverResult<()> {
        match event {
            SlotEvent::SyncSlot {
                block_height,
                timestamp,
                l1_head,
            } => {
                self.advance_sync_slot(block_height, timestamp, l1_head)
                    .await
            }
            SlotEvent::LiveTick {
                sync_slot_block_height,
            } => {
                self.advance_anchored_live_tick(sync_slot_block_height)
                    .await
            }
        }
    }

    /// L1-anchored wall-clock tick handler: commit exactly ONE Live
    /// block, and only while the head is below the live region of the
    /// next sync slot (`sync_slot_block_height - future_count - 1`).
    /// The Future + Sync reserve belongs to the anchor trigger
    /// ([`Self::advance_sync_slot`]); ticks no-op once the live region
    /// is full, so they can't outrun the anchor.
    async fn advance_anchored_live_tick(
        &mut self,
        sync_slot_block_height: u64,
    ) -> DriverResult<()> {
        let rollup_id = self.rollup_id;
        let composer = Arc::clone(&self.composer);
        // Before the head read: a mid-slot verdict would otherwise wait K
        // blocks, and recovery can reorg + substitute under us.
        composer.recover_failed(rollup_id).await;
        let last_header = self.committer.last_header();
        let head = last_header.number();
        // Reserve = Future blocks + the Sync block itself. Mirrors
        // `live_region_end` in `RollupTiming::per_trigger_composition`.
        let reserve = u64::from(self.timing.future_count()) + 1;
        let live_region_end = sync_slot_block_height.saturating_sub(reserve);
        if head >= live_region_end {
            // Live region full (steady state between anchor fire and
            // the next L1 head). Future + Sync come from the anchor.
            return Ok(());
        }
        if self.speculative_limit_paused(head) {
            return Ok(());
        }
        match self
            .commit_one(SlotKind::Live, &last_header, sync_slot_block_height)
            .await
        {
            Ok(()) => Ok(()),
            Err(err) if err.is_stale_parent() => {
                log_stale_parent("live_tick");
                Ok(())
            }
            Err(err) => Err(err),
        }
    }

    /// True if the bundle (ready at ~`now + proof_time`) can't reach the
    /// relay by `sync_slot_timestamp − submission_slack`, i.e. it would miss
    /// the immediate next L1 slot. Steady state has headroom; fires only on
    /// a late trigger, where the slot is deferred.
    fn sync_block_misses_l1_slot(&self, sync_slot_timestamp: u64) -> bool {
        let proof_ms = u64::try_from(self.timing.proof_time().as_millis()).unwrap_or(u64::MAX);
        let slack_ms =
            u64::try_from(self.timing.submission_slack().as_millis()).unwrap_or(u64::MAX);
        let ready_ms = crate::slot::now_unix_millis().saturating_add(proof_ms);
        let deadline_ms = sync_slot_timestamp
            .saturating_mul(1_000)
            .saturating_sub(slack_ms);
        ready_ms > deadline_ms
    }

    /// One skip self-heals next trigger; a run of them means production is
    /// wedged, so escalate past a few.
    fn note_off_grid_skip(&mut self) {
        self.off_grid_skips = self.off_grid_skips.saturating_add(1);
        if self.off_grid_skips >= 3 {
            event!(
                name: "eez.sequencer.sync_slot.off_grid_stalled",
                Level::ERROR,
                consecutive_skips = self.off_grid_skips,
                "consecutive Sync blocks skipped for off-grid drift; production is not advancing",
            );
        }
    }

    /// L1-anchored handler: read current head, compute the per-trigger
    /// Live/Future/Sync split via
    /// [`RollupTiming::per_trigger_composition`], produce accordingly.
    async fn advance_sync_slot(
        &mut self,
        sync_slot_block_height: u64,
        sync_slot_timestamp: u64,
        l1_head: u64,
    ) -> DriverResult<()> {
        let rollup_id = self.rollup_id;
        let composer = Arc::clone(&self.composer);
        // Before the composition: a pending verdict would seed the whole burst
        // on a doomed head, for compose_sync_slot to reorg away at its end.
        composer.recover_failed(rollup_id).await;
        let head = self.committer.last_header().number();
        // Catchup ignores the speculative cap (a steady-state bound): a
        // dropped pb heals by recomposing next trigger, which freezing to
        // Idle would block. The steady (Slot) arm still enforces the cap.
        let comp = self.timing.per_trigger_composition(
            head,
            sync_slot_block_height,
            crate::MAX_BLOCKS_PER_CATCHUP,
        );

        event!(
            name: "eez.sequencer.sync_slot.composition",
            Level::INFO,
            head,
            sync_slot_block_height,
            sync_slot_timestamp,
            composition = ?comp,
            "computed per-trigger slot composition",
        );

        // Target an absolute height, not a count. The committer is shared, so a
        // count re-derived from a moved head would land the Sync block off-grid.
        let terminal = match comp {
            SlotComposition::Catchup { live } => Some(head + live + 1),
            SlotComposition::Slot { .. } | SlotComposition::Idle => None,
        };

        match comp {
            SlotComposition::Idle => {}
            SlotComposition::Catchup { live } => {
                // `live` is grid-snapped + capped by per_trigger_composition;
                // produce that many Live blocks then the terminal Sync.
                for _ in 0..live {
                    let last_header = self.committer.last_header();
                    // Once the burst reaches this target's Future region, use
                    // the ordinary slot layout even though older intervals had
                    // to be rebuilt first. Intermediate Sync boundaries remain
                    // empty through commit_one's existing grid guard.
                    let live_end = sync_slot_block_height
                        .saturating_sub(u64::from(self.timing.future_count()) + 1);
                    let kind = if terminal == Some(sync_slot_block_height)
                        && last_header.number() >= live_end
                    {
                        SlotKind::Future
                    } else {
                        SlotKind::Live
                    };
                    match self
                        .commit_one(kind, &last_header, sync_slot_block_height)
                        .await
                    {
                        Ok(()) => {}
                        Err(err) if err.is_stale_parent() => {
                            log_stale_parent("catchup.live");
                            return Ok(());
                        }
                        Err(err) => return Err(err),
                    }
                }

                // A capped/past terminal remains structural-only. If catch-up
                // reached the actual future target, recheck its timestamp and
                // deadline now: beginning the tick behind must not cost another
                // otherwise eligible L1 opportunity.
                if terminal != Some(self.committer.last_header().number() + 1) {
                    event!(
                        name: "eez.sequencer.sync_slot.off_grid_skipped",
                        Level::WARN,
                        head_now = self.committer.last_header().number(),
                        terminal = ?terminal,
                        "head moved during the burst; skipping the Sync block rather than placing it off-grid",
                    );
                    self.note_off_grid_skip();
                    return Ok(());
                }
                let last_header = self.committer.last_header();
                let sync_ts = last_header
                    .timestamp()
                    .saturating_add(self.timing.l2_block_time().as_secs());

                let can_settle = terminal == Some(sync_slot_block_height)
                    && sync_ts == sync_slot_timestamp
                    && !self.sync_block_misses_l1_slot(sync_ts)
                    && !self.speculative_limit_paused(last_header.number());
                let (target, mode) = if can_settle {
                    (Some(l1_head + 1), SyncSlotMode::Steady)
                } else {
                    (None, SyncSlotMode::Catchup)
                };

                let parent = crate::slot::ParentContext {
                    header: last_header.clone(),
                };
                let prebuilt = composer
                    .compose_sync_slot_outcome(rollup_id, parent, sync_ts, target, mode)
                    .await;
                let prebuilt = match prebuilt {
                    crate::SyncSlotOutcome::Built(built) => Some(*built),
                    crate::SyncSlotOutcome::LegacyPool => None,
                    crate::SyncSlotOutcome::EndTick => return Ok(()),
                };
                if let Some(built) = prebuilt {
                    if let Err(err) = self.commit_one_prebuilt(SlotKind::Sync, built).await {
                        if err.is_stale_parent() {
                            log_stale_parent("catchup.sync.prebuilt");
                            return Ok(());
                        }
                        return Err(err);
                    }
                    self.off_grid_skips = 0;
                } else {
                    match self
                        .commit_one(SlotKind::Sync, &last_header, sync_slot_block_height)
                        .await
                    {
                        Ok(()) => {}
                        Err(err) if err.is_stale_parent() => {
                            log_stale_parent("catchup.sync");
                            return Ok(());
                        }
                        Err(err) => return Err(err),
                    }
                    self.off_grid_skips = 0;
                }
            }
            SlotComposition::Slot { live, future } => {
                for _ in 0..live {
                    let last_header = self.committer.last_header();
                    if self.speculative_limit_paused(last_header.number()) {
                        return Ok(()); // Defer Future + Sync to next trigger.
                    }
                    match self
                        .commit_one(SlotKind::Live, &last_header, sync_slot_block_height)
                        .await
                    {
                        Ok(()) => {}
                        Err(err) if err.is_stale_parent() => {
                            log_stale_parent("slot.live");
                            return Ok(());
                        }
                        Err(err) => return Err(err),
                    }
                }
                for _ in 0..future {
                    let last_header = self.committer.last_header();
                    if self.speculative_limit_paused(last_header.number()) {
                        return Ok(()); // Defer remaining Future + Sync to next trigger.
                    }
                    match self
                        .commit_one(SlotKind::Future, &last_header, sync_slot_block_height)
                        .await
                    {
                        Ok(()) => {}
                        Err(err) if err.is_stale_parent() => {
                            log_stale_parent("slot.future");
                            return Ok(());
                        }
                        Err(err) => return Err(err),
                    }
                }
                let last_header = self.committer.last_header();
                if self.speculative_limit_paused(last_header.number()) {
                    return Ok(()); // Defer the Sync (postBatch terminal) to next trigger.
                }
                let expected_sync_ts = last_header
                    .timestamp()
                    .saturating_add(self.timing.l2_block_time().as_secs());
                if expected_sync_ts != sync_slot_timestamp {
                    // The head moved under us. This block would settle, and an
                    // off-grid root wedges the deriver. Skip; next trigger realigns.
                    event!(
                        name: "eez.sequencer.sync_slot.off_grid_skipped",
                        Level::WARN,
                        expected = expected_sync_ts,
                        sync_slot_timestamp,
                        head = last_header.number(),
                        sync_slot_block_height,
                        "sync-slot drift: parent + L2_block_time != the L1-derived sync timestamp; skipping the Sync block rather than settling off-grid",
                    );
                    self.note_off_grid_skip();
                    return Ok(());
                }

                // Defer-on-lateness: a late trigger that can't land the bundle
                // in the next L1 slot commits an empty block and holds the pool
                // (next slot covers it). Else drain into a prebuilt Sync block.
                // Check against expected_sync_ts — the ts the bundle is pinned
                // to below — so an off-grid trigger already past its pin defers
                // instead of composing a bundle that can't make its slot.
                let prebuilt = if self.sync_block_misses_l1_slot(expected_sync_ts) {
                    event!(
                        name: "eez.sequencer.sync_slot.deferred_late",
                        Level::WARN,
                        sync_slot_block_height,
                        sync_slot_timestamp,
                        l1_head,
                        "trigger too late for the immediate L1 slot; committing an empty block and holding the pool — next slot's batch covers it",
                    );
                    // Empty mode keeps this grid height batch-boundary-eligible.
                    // The explicit outcome also lets a failed required empty
                    // build end the tick without admitting pool transactions.
                    let parent = crate::slot::ParentContext {
                        header: last_header.clone(),
                    };
                    composer
                        .compose_sync_slot_outcome(
                            rollup_id,
                            parent,
                            expected_sync_ts,
                            None,
                            SyncSlotMode::Empty,
                        )
                        .await
                } else {
                    let parent = crate::slot::ParentContext {
                        header: last_header.clone(),
                    };
                    composer
                        // Steady: aim the immediate next L1 block, pinned to
                        // expected_sync_ts (re-derivable; == the L1 slot ts on-grid).
                        .compose_sync_slot_outcome(
                            rollup_id,
                            parent,
                            expected_sync_ts,
                            Some(l1_head + 1),
                            SyncSlotMode::Steady,
                        )
                        .await
                };
                let prebuilt = match prebuilt {
                    crate::SyncSlotOutcome::Built(built) => Some(*built),
                    crate::SyncSlotOutcome::LegacyPool => None,
                    crate::SyncSlotOutcome::EndTick => return Ok(()),
                };
                if let Some(built) = prebuilt {
                    match self.commit_one_prebuilt(SlotKind::Sync, built).await {
                        Ok(()) => {}
                        Err(err) if err.is_stale_parent() => {
                            log_stale_parent("slot.sync.prebuilt");
                        }
                        Err(err) => return Err(err),
                    }
                    self.off_grid_skips = 0;
                    return Ok(());
                }

                match self
                    .commit_one(SlotKind::Sync, &last_header, sync_slot_block_height)
                    .await
                {
                    Ok(()) => {}
                    Err(err) if err.is_stale_parent() => {
                        log_stale_parent("slot.sync");
                        return Ok(());
                    }
                    Err(err) => return Err(err),
                }
                self.off_grid_skips = 0;
            }
        }
        Ok(())
    }

    /// True if the speculative-depth limit is reached; logged at DEBUG.
    fn speculative_limit_paused(&self, head_number: u64) -> bool {
        if self.max_speculative_depth == 0 {
            return false;
        }
        let confirmed = self.l1_head.cursor();
        let speculative_depth = head_number.saturating_sub(confirmed);
        if speculative_depth >= self.max_speculative_depth {
            event!(
                name: "eez.sequencer.speculative.paused",
                Level::DEBUG,
                head_number,
                confirmed,
                speculative_depth,
                max_depth = self.max_speculative_depth,
                "paused: speculative depth at cap; waiting for Deriver to catch up",
            );
            return true;
        }
        false
    }

    /// Commit a pre-built Sync block (from the cross-chain composer)
    /// via `commit_derived` — same engine-API tail the Deriver uses
    /// for L1-derived blocks. Holds the reconcile lock so a sync-slot
    /// commit can't race with a deriver-side reconcile.
    async fn commit_one_prebuilt(
        &mut self,
        kind: SlotKind,
        built: crate::slot::SyncSlotBlock,
    ) -> DriverResult<()> {
        // `commit_derived` doesn't take the lock itself (only
        // `commit_sequenced` does, and the Deriver already holds it via
        // `begin_reconcile`), so hold it here too.
        let _reconcile_guard = self.committer.begin_reconcile().await;
        // Stale-parent check under the lock, like commit_sequenced: the
        // Deriver (or a failed-batch recovery) can move the head between
        // compose and commit, and a prebuilt block on a stale parent
        // would silently reorg that newer work via commit_derived's FCU.
        let current_head = self.committer.last_header().hash();
        let built_parent = built.header.parent_hash();
        if current_head != built_parent {
            return Err(DriverError::stale_parent(built_parent, current_head));
        }
        let block_number = built.header.number();
        let block_hash = built.header.hash();
        let block_timestamp = built.header.timestamp();
        let _outcome = self
            .committer
            // feed_witness=true: this is a PRODUCED Sync block — emit it to the
            // prover witness-capture feed (the follower/deriver passes false).
            .commit_derived(built.payload, built.header, true)
            .await?;

        event!(
            name: "eez.sequencer.block.produced",
            Level::INFO,
            slot.kind = %kind,
            block.number = block_number,
            block.hash = %block_hash,
            block.timestamp = block_timestamp,
            "produced block {block_number} hash={block_hash} ts={block_timestamp} kind={kind}",
        );
        Ok(())
    }

    /// Commit one block of the given kind at
    /// `parent.timestamp() + L2_block_time`. Logs `eez.sequencer.block.produced`.
    async fn commit_one(
        &mut self,
        kind: SlotKind,
        parent: &SealedHeader<ChainSpec::Header>,
        sync_slot_height: u64,
    ) -> DriverResult<()> {
        self.composer
            .set_sequencing_target(self.rollup_id, sync_slot_height);
        let parent_hash = parent.hash();
        let parent_ts = parent.timestamp();
        let next_ts = parent_ts.saturating_add(self.timing.l2_block_time().as_secs());
        if kind != SlotKind::Sync
            && self.composer.guards_sequencing_da()
            && parent.number().checked_add(1).is_some_and(|n| {
                n % u64::from(self.timing.k()) == sync_slot_height % u64::from(self.timing.k())
            })
        {
            // Catch-up may span several Sync intervals. Each intermediate grid
            // boundary must remain an admissible historical settlement endpoint.
            let outcome = self
                .composer
                .compose_sync_slot_outcome(
                    self.rollup_id,
                    crate::ParentContext {
                        header: parent.clone(),
                    },
                    next_ts,
                    None,
                    SyncSlotMode::Empty,
                )
                .await;
            return match outcome {
                crate::SyncSlotOutcome::Built(block) => {
                    self.commit_one_prebuilt(SlotKind::Sync, *block).await
                }
                _ => Err(DriverError::invalid_forkchoice(
                    "required empty DA boundary unavailable".to_owned(),
                )),
            };
        }
        let attrs = self.attributes.build(parent, next_ts);
        let timestamp = attrs.timestamp;
        let outcome = self.committer.commit_sequenced(parent_hash, attrs).await?;
        let block_number = outcome.header.number();
        let block_hash = outcome.header.hash();

        event!(
            name: "eez.sequencer.block.produced",
            Level::INFO,
            slot.kind = %kind,
            block.number = block_number,
            block.hash = %block_hash,
            block.timestamp = timestamp,
            "produced block {block_number} hash={block_hash} ts={timestamp} kind={kind}",
        );
        Ok(())
    }
}

    Ok(total_replayed)
}

/// STF-replay `raw_txs` on top of `parent_block_number`. Timestamp
/// is `parent.timestamp + 2s` (Rollup-1 spec §1.3).
///
/// # Errors
///
/// `l2_provider` (parent lookup / state / builder failure),
/// `local_diverged` (tx decode / recover / execute failure).
pub fn execute_block(
    &self,
    parent_block_number: u64,
    raw_txs: &[Vec<u8>],
) -> DeriverResult<(ExecutionData, SealedHeader<alloy_consensus::Header>)> {
    self.execute_block_with_template(parent_block_number, raw_txs, None)
}

/// Execute a block using the complete producer-advertised metadata when
/// the self-contained DA profile supplies it.
fn execute_block_with_template(
    &self,
    parent_block_number: u64,
    raw_txs: &[Vec<u8>],
    template: Option<&EthereumBlock>,
) -> DeriverResult<(ExecutionData, SealedHeader<alloy_consensus::Header>)> {
    // Diagnostic: log parent context before touching reth so we can
    // pinpoint failing `state_by_block_hash` lookups.
    let local_best = self
        .inner
        .l2_provider
        .best_block_number()
        .map_err(DeriverError::l2_provider)?;
    event!(
        name: "eez.deriver.execute_block.start",
        Level::DEBUG,
        parent_block_number,
        local_best,
        tx_count = raw_txs.len(),
        "execute_block: looking up parent header",
    );

    let parent_header = self
        .inner
        .l2_provider
        .sealed_header(parent_block_number)
        .map_err(|e| {
            event!(
                name: "eez.deriver.execute_block.parent_lookup_failed",
                Level::ERROR,
                parent_block_number,
                local_best,
                error = %e,
                "sealed_header() failed",
            );
            DeriverError::l2_provider(e)
        })?
        .ok_or_else(|| {
            event!(
                name: "eez.deriver.execute_block.parent_missing",
                Level::ERROR,
                parent_block_number,
                local_best,
                "sealed_header() returned None — parent header is not in canonical chain",
            );
            DeriverError::l2_provider(format!(
                "local L2 header at parent block {parent_block_number} missing"
            ))
        })?;

    let parent_hash = parent_header.hash();
    let timestamp = template.map_or_else(
        || {
            parent_header
                .timestamp()
                .saturating_add(self.inner.l2_block_time_secs)
        },
        |block| block.header.timestamp,
    );
    if let Some(block) = template
        && (block.header.number != parent_block_number.saturating_add(1)
            || block.header.parent_hash != parent_hash)
    {
        return Err(DeriverError::local_diverged_with_msg(
            parent_block_number.saturating_add(1),
            "self-contained block metadata does not extend the local parent",
        ));
    }

    let state_provider = self
        .inner
        .l2_provider
        .state_by_block_hash(parent_hash)
        .map_err(|e| {
            // reth has the *header* for this block (sealed_header
            // succeeded above) but refuses to give us its state.
            // Capture as much context as possible.
            event!(
                name: "eez.deriver.execute_block.no_state",
                Level::ERROR,
                parent_block_number,
                parent_hash = %parent_hash,
                local_best,
                parent_timestamp = parent_header.timestamp(),
                error = %e,
                "state_by_block_hash() failed for a header that sealed_header() returned successfully — likely reth state retention timing under reorg churn",
            );
            DeriverError::l2_provider(e)
        })?;
    let state_db = StateProviderDatabase::new(state_provider.as_ref());
    let mut db = State::builder()
        .with_database(state_db)
        .with_bundle_update()
        .build();

    // Chainspec-aware deriver
    // prevents STF mismatches w.r.t. payload builder
    let chain_spec = &self.inner.chain_spec;
    let attributes = NextBlockEnvAttributes {
        timestamp,
        suggested_fee_recipient: template
            .map_or(Address::ZERO, |block| block.header.beneficiary),
        prev_randao: template.map_or(B256::ZERO, |block| block.header.mix_hash),
        gas_limit: template.map_or(BUILDER_GAS_LIMIT, |block| block.header.gas_limit),
        parent_beacon_block_root: template.map_or_else(
            || {
                chain_spec
                    .is_cancun_active_at_timestamp(timestamp)
                    .then_some(B256::ZERO)
            },
            |block| block.header.parent_beacon_block_root,
        ),
        withdrawals: template.map_or_else(
            || {
                chain_spec
                    .is_shanghai_active_at_timestamp(timestamp)
                    .then(alloy_eips::eip4895::Withdrawals::default)
            },
            |block| block.body.withdrawals.clone(),
        ),
        extra_data: template.map_or_else(
            || Bytes::from_static(BUILDER_EXTRA_DATA),
            |block| block.header.extra_data.clone(),
        ),
        slot_number: None,
    };

    let mut builder = self
        .inner
        .evm_config
        .builder_for_next_block(&mut db, &parent_header, attributes)
        .map_err(|e| {
            DeriverError::l2_provider(format!("builder_for_next_block failed: {e}"))
        })?;

    builder
        .apply_pre_execution_changes()
        .map_err(|e| DeriverError::l2_provider(format!("pre-execution changes failed: {e}")))?;

    for (tx_idx, tx_bytes) in raw_txs.iter().enumerate() {
        let tx = TransactionSigned::decode_2718(&mut tx_bytes.as_slice()).map_err(|e| {
            DeriverError::local_diverged_with_msg(
                parent_block_number + 1,
                &format!("decode tx #{tx_idx}: {e}"),
            )
        })?;
        let recovered = SignedTransaction::try_into_recovered(tx).map_err(|_| {
            DeriverError::local_diverged_with_msg(
                parent_block_number + 1,
                &format!("could not recover signer for tx #{tx_idx}"),
            )
        })?;
        builder.execute_transaction(recovered).map_err(|e| {
            DeriverError::local_diverged_with_msg(
                parent_block_number + 1,
                &format!("execute tx #{tx_idx}: {e}"),
            )
        })?;
    }

    let outcome = builder
        .finish(state_provider.as_ref(), None)
        .map_err(|e| DeriverError::l2_provider(format!("block builder finish failed: {e}")))?;

    let sealed_block = outcome.block.sealed_block().clone();
    let sealed_header = sealed_block.sealed_header().clone();
    if let Some(template) = template {
        let advertised_txs = template
            .body
            .transactions
            .iter()
            .map(Encodable2718::encoded_2718)
            .collect::<Vec<_>>();
        if !advertised_txs.starts_with(raw_txs) {
            return Err(DeriverError::local_diverged_with_msg(
                parent_block_number.saturating_add(1),
                "replayed transactions are not an exact prefix of the self-contained block",
            ));
        }
        if advertised_txs.len() != raw_txs.len()
            && template
                .body
                .withdrawals
                .as_ref()
                .is_some_and(|withdrawals| !withdrawals.is_empty())
        {
            return Err(DeriverError::local_diverged_with_msg(
                parent_block_number.saturating_add(1),
                "partial self-contained block replay cannot include withdrawals",
            ));
        }
        if advertised_txs.len() != raw_txs.len() && !template.body.ommers.is_empty() {
            return Err(DeriverError::local_diverged_with_msg(
                parent_block_number.saturating_add(1),
                "partial self-contained block replay cannot include ommers",
            ));
        }
        if advertised_txs.len() == raw_txs.len() {
            let advertised_hash = template.header.hash_slow();
            if sealed_header.hash() != advertised_hash {
                return Err(DeriverError::local_diverged_with_msg(
                    parent_block_number.saturating_add(1),
                    &format!(
                        "replayed self-contained block hash {} differs from advertised hash {advertised_hash}",
                        sealed_header.hash(),
                    ),
                ));
            }
        }
    }
    let execution_data = <EthEngineTypes as PayloadTypes>::block_to_payload(sealed_block, None);
    Ok((execution_data, sealed_header))
}

/// Build + commit one L1-derived L2 block via STF replay.
///
/// # Errors
///
/// Forwards [`Self::execute_block`] errors plus
/// [`DeriverError::is_invalid_forkchoice`] /
/// [`DeriverError::is_committer_closed`] from the
/// committer-side submission.
pub async fn replay_block(
    &self,
    parent_block_number: u64,
    raw_txs: &[Vec<u8>],
) -> DeriverResult<DeriveOutcome> {
    self.replay_block_with_template(parent_block_number, raw_txs, None)
        .await
}

async fn replay_block_with_template(
    &self,
    parent_block_number: u64,
    raw_txs: &[Vec<u8>],
    template: Option<&EthereumBlock>,
) -> DeriverResult<DeriveOutcome> {
    let (payload, header) =
        self.execute_block_with_template(parent_block_number, raw_txs, template)?;
    // feed_witness=false: follower / L1-reconcile re-derive — the producer
    // already fed this block to the prover witness capture; don't double-feed.
    Ok(self
        .inner
        .committer
        .commit_derived(payload, header, false)
        .await?)
}

/// Runs the deriver loop, processing each event on `rx` until the
/// stream closes. `rx` must be subscribed before the `L1Watcher`
/// starts so no event predates it.
pub async fn run(self, mut rx: broadcast::Receiver<L1Event>) {
    // Defensive re-anchor: a cheap no-op in the normal boot order;
    // load-bearing for any caller that subscribed rx late.
    if let Err(err) = self.catch_up().await {
        event!(
            name: "eez.deriver.resync.failed",
            Level::ERROR,
            event_name = "eez.deriver.resync.failed",
            error = %err,
            "post-subscribe resync failed; deriver may have a gap",
        );
    }

    event!(
        name: "eez.deriver.started",
        Level::INFO,
        cursor = self.cursor(),
        "deriver loop started",
    );
    loop {
        match rx.recv().await {
            Ok(event) => {
                if let Err(err) = self.handle_event(event).await {
                    self.inner.scan_needs_resync.store(true, Ordering::Release);
                    self.inner.l1_head.invalidate_scan();
                    if err.is_committer_closed() {
                        event!(
                            name: "eez.deriver.committer.closed",
                            Level::ERROR,
                            event_name = "eez.deriver.committer.closed",
                            error = %err,
                            "block committer gone; deriver exiting",
                        );
                        return;
                    }
                    // A dropped event leaves `last_indexed_l2` behind
                    // L1, so later batches replay at the wrong heights —
                    // re-anchor from L1 first.
                    event!(
                        name: "eez.deriver.event.failed",
                        Level::WARN,
                        error = %err,
                        "deriver failed to handle event; resyncing from L1",
                    );
                    if !self.try_recover().await {
                        return;
                    }
                }
            }
            Err(broadcast::error::RecvError::Lagged(skipped)) => {
                self.inner.scan_needs_resync.store(true, Ordering::Release);
                self.inner.l1_head.invalidate_scan();
                event!(
                    name: "eez.deriver.l1_events.lagged",
                    Level::WARN,
                    skipped,
                    "L1 event stream lagged; resyncing from L1",
                );
                if !self.try_recover().await {
                    return;
                }
            }
            Err(broadcast::error::RecvError::Closed) => {
                event!(
                    name: "eez.deriver.l1_events.closed",
                    Level::ERROR,
                    "L1 event stream closed; deriver exiting",
                );
                return;
            }
        }
    }
}

/// Post-failure recovery via [`Self::catch_up`]. Returns `false` only
/// when the committer is gone and the loop must exit; a failed resync is
/// logged and retried at the next L1 event.
async fn try_recover(&self) -> bool {
    match self.catch_up().await {
        Ok(()) => {
            event!(
                name: "eez.deriver.resync.recovered",
                Level::INFO,
                cursor = self.cursor(),
                "resync complete; cursor re-anchored to L1",
            );
            true
        }
        Err(err) if err.is_committer_closed() => {
            event!(
                name: "eez.deriver.committer.closed",
                Level::ERROR,
                event_name = "eez.deriver.committer.closed",
                error = %err,
                "block committer gone; deriver exiting",
            );
            false
        }
        Err(err) => {
            event!(
                name: "eez.deriver.resync.failed",
                Level::ERROR,
                event_name = "eez.deriver.resync.failed",
                error = %err,
                "resync failed; will retry after the next L1 event",
            );
            true
        }
    }
}

async fn handle_event(&self, event: L1Event) -> DeriverResult<()> {
    match event {
        L1Event::BatchPosted {
            l1_block_number,
            l1_block_hash,
            tx_hash,
            tx_index,
            submitter,
            operations_payload,
            post_batch_input,
            state_applied,
            settlement,
            claimed_current_root,
            claimed_new_root,
            last_in_l1_block,
        } => {
            self.on_batch_posted(
                l1_block_number,
                l1_block_hash,
                tx_hash,
                tx_index,
                submitter,
                operations_payload,
                post_batch_input,
                state_applied,
                settlement,
                claimed_current_root,
                claimed_new_root,
                last_in_l1_block,
            )
            .await
        }
        L1Event::NewHead { .. } => Ok(()),
        L1Event::ScanComplete {
            block_number,
            block_hash,
        } => {
            if self.inner.scan_needs_resync.load(Ordering::Acquire) {
                return self.catch_up().await;
            }
            let _guard = self.inner.committer.begin_reconcile().await;
            self.finish_scan(block_number, Some(block_hash)).await
        }
        L1Event::Reorg {
            common_ancestor_number,
            old_head_hash,
            new_head_hash,
            new_head_number,
            ..
        } => {
            self.on_l1_reorg(
                common_ancestor_number,
                old_head_hash,
                new_head_number,
                new_head_hash,
            )
            .await
        }
        L1Event::Finalized { block_number, .. } => self.on_l1_finalized(block_number).await,
    }
}

#[allow(clippy::too_many_arguments)]
async fn on_batch_posted(
    &self,
    l1_block_number: u64,
    l1_block_hash: B256,
    tx_hash: B256,
    tx_index: u64,
    submitter: Address,
    operations_payload: Bytes,
    post_batch_input: Bytes,
    state_applied: bool,
    settlement: eez_l1::Settlement,
    claimed_current_root: Option<B256>,
    claimed_new_root: Option<B256>,
    last_in_l1_block: bool,
) -> DeriverResult<()> {
    let decoded = eez_payload_codec::decode(operations_payload.as_ref())?;
    let block_count = decoded.block_count() as u64;

    // Dedup by tx_hash — already-indexed = already processed by
    // catch_up; this is a stale live event.
    if self.inner.l1_head.contains_l1_tx(&tx_hash) {
        event!(
            name: "eez.deriver.batch_posted.skipped",
            Level::DEBUG,
            l1_block_number,
            tx_hash = %tx_hash,
            "live event for an already-indexed batch; skipping",
        );
        return self.flush_deferred_safe(last_in_l1_block).await;
    }

    // L1-finality gate: no `L2ExecutionPerformed` for our rollupId
    // means the bundle didn't settle — L1's stored root didn't
    // advance and the claimed roots are phantoms. Skip; the
    // composer's next slot re-attempts. Without this gate the
    // deriver would replay the unsettled range, reorg L2, then fail
    // `check_claimed_state` as a spurious divergence.
    if settlement.is_empty() {
        let _guard = self.inner.committer.begin_reconcile().await;
        self.inner.l1_head.publish(self.batch_evidence(
            eez_l1::L1BlockRef {
                number: l1_block_number,
                hash: l1_block_hash,
            },
            (tx_hash, tx_index),
            &post_batch_input,
            &decoded,
            settlement,
            None,
        )?);
        event!(
            name: "eez.deriver.batch.unsettled",
            Level::INFO,
            l1_block_number,
            tx_hash = %tx_hash,
            submitter = %submitter,
            "postBatch's L1 block has no L2ExecutionPerformed for our rollup; bundle didn't settle, skipping (re-attempt expected)",
        );
        return self.flush_deferred_safe(last_in_l1_block).await;
    }

    if block_count == 0 {
        return Err(DeriverError::l2_provider(
            "applied batch has no L2 block metadata",
        ));
    }

    event!(
        name: "eez.deriver.batch_posted.entered",
        Level::INFO,
        l1_block_number,
        tx_hash = %tx_hash,
        state_applied,
        "on_batch_posted entered; awaiting reconcile lock",
    );
    // Acquire lock to prevent sequencing during multi-block derivation
    let _guard = self.inner.committer.begin_reconcile().await;
    event!(
        name: "eez.deriver.batch_posted.lock_acquired",
        Level::INFO,
        l1_block_number,
        tx_hash = %tx_hash,
        state_applied,
        "reconcile lock acquired",
    );

    // `state_applied` only catches the IMMEDIATE-entry path, where
    // `_applyRootUpdates` fires in the postBatch tx itself. In the
    // DEFERRED-entry path (our setter / deposit flow) it fires later
    // inside the user_tx calling `executeCrossChainCall` — a
    // different tx hash in the same L1 block — so the batch-log scanner
    // reports `state_applied=false`. The `settled_count` gate above
    // already confirmed something settled, so we still process.
    if !state_applied {
        event!(
            name: "eez.deriver.batch.deferred_path",
            Level::INFO,
            l1_block_number,
            tx_hash = %tx_hash,
            submitter = %submitter,
            "no L2ExecutionPerformed in postBatch tx — deferred-entry flow; bundled user_tx settled the state",
        );
    }

    // from_block is the next L2 block after the highest indexed
    // batch — the shared L1CanonicalHead is the source of truth.
    let last_indexed_l2 = self.inner.l1_head.last_indexed_l2();
    let resumed = settlement.start > 0;
    // Anchor on the batch's own start, not our cursor: a competing
    // composer's batch can cover a range that begins below it.
    let anchor = match settlement.entry_state {
