1	//! Canonical pending-block accounting. Only newly observed blocks are loaded
2	//! and measured in steady state; a hash change rewinds to the common ancestor.
3	
4	use std::collections::BTreeMap;
5	
6	use alloy_primitives::B256;
7	use eez_l1::L2Endpoint;
8	
9	use super::PolicyError;
10	
11	/// One measured block. No receipts are needed to count included transactions.
12	#[derive(Debug, Clone, Copy)]
13	pub(crate) struct BlockActivity {
14	    pub endpoint: L2Endpoint,
15	    pub parent_hash: B256,
16	    /// The individual block's length as an element of the existing payload's
17	    /// `Vec<Vec<u8>>`, including the element's RLP framing.
18	    pub encoded_item_bytes: u64,
19	    pub pure_transactions: u64,
20	}
21	
22	#[derive(Debug, Clone, Copy)]
23	struct IndexedBlock {
24	    block: BlockActivity,
25	    prefix_bytes: u64,
26	    prefix_pure_transactions: u64,
27	    latest_pure: Option<L2Endpoint>,
28	}
29	
30	#[derive(Debug, Default, Clone, Copy)]
31	pub(crate) struct DaOverhead {
32	    pub entry_items: usize,
33	    pub group_items: usize,
34	    pub semantic_bytes: usize,
35	}
36	
37	/// Not persisted. The cache's format identity includes both existing codecs.
38	#[derive(Debug, Default)]
39	pub(crate) struct ActivityIndex {
40	    codec: (u8, u8),
41	    anchor: Option<L2Endpoint>,
42	    anchor_prefix_bytes: u64,
43	    anchor_prefix_pure_transactions: u64,
44	    blocks: BTreeMap<u64, IndexedBlock>,
45	}
46	
47	impl ActivityIndex {
48	    /// Update through the supplied parent, including reth's just-built pending
49	    /// parent. Hash lookups avoid a race with provider height-index promotion.
50	    /// Returns whether previously cached blocks may have been invalidated.
51	    /// A steady append does not require walking the separate immutable RLP cache.
52	    pub fn update(
53	        &mut self,
54	        anchor: L2Endpoint,
55	        parent: L2Endpoint,
56	        mut load: impl FnMut(B256) -> Result<BlockActivity, PolicyError>,
57	    ) -> Result<bool, PolicyError> {
58	        let codec = (
59	            eez_payload_codec::TAG_SELF_CONTAINED_BLOCKS,
60	            eez_blob_codec::PROTOCOL_VERSION,
61	        );
62	        let mut invalidated = self.codec != codec || self.anchor != Some(anchor);
63	        if self.codec != codec {
64	            *self = Self {
65	                codec,
66	                ..Self::default()
67	            };
68	        }
69	        if parent.number < anchor.number {
70	            return Err(PolicyError::Unavailable(
71	                "L2 parent precedes the settlement anchor".into(),
72	            ));
73	        }
74	        if self.anchor != Some(anchor) {
75	            if let Some(block) = self.blocks.get(&anchor.number).copied()
76	                && block.block.endpoint == anchor
77	                && self.anchor.is_some_and(|old| old.number <= anchor.number)
78	            {
79	                self.anchor_prefix_bytes = block.prefix_bytes;
80	                self.anchor_prefix_pure_transactions = block.prefix_pure_transactions;
81	                self.blocks = self.blocks.split_off(&anchor.number);
82	                self.blocks.remove(&anchor.number);
83	            } else {
84	                self.blocks.clear();
85	                self.anchor_prefix_bytes = 0;
86	                self.anchor_prefix_pure_transactions = 0;
87	            }
88	            self.anchor = Some(anchor);
89	        }
90	        let mut cursor = parent;
91	        let mut pending = Vec::new();
92	        while cursor.number > anchor.number {
93	            if self
94	                .blocks
95	                .get(&cursor.number)
96	                .is_some_and(|cached| cached.block.endpoint == cursor)
97	            {
98	                break;
99	            }
100	            let block = load(cursor.hash)?;
101	            if block.endpoint != cursor {
102	                return Err(PolicyError::Unavailable(
103	                    "block lookup returned a different identity".into(),
104	                ));
105	            }
106	            pending.push(block);
107	            cursor = L2Endpoint {
108	                number: cursor.number - 1,
109	                hash: block.parent_hash,
110	            };
111	        }
112	        if cursor.number == anchor.number && cursor.hash != anchor.hash {
113	            return Err(PolicyError::Unavailable(
114	                "pending L2 ancestry does not match the validated anchor".into(),
115	            ));
116	        }
117	        if let Some(after) = cursor.number.checked_add(1) {
118	            invalidated |= !self.blocks.split_off(&after).is_empty();
119	        }
120	        for block in pending.into_iter().rev() {
121	            let previous = self.blocks.last_key_value().map(|(_, block)| *block);
122	            let prefix_bytes = previous
123	                .map_or(self.anchor_prefix_bytes, |block| block.prefix_bytes)
124	                .checked_add(block.encoded_item_bytes)
125	                .ok_or(PolicyError::Arithmetic("pending encoded block bytes"))?;
126	            let prefix_pure_transactions = previous
127	                .map_or(self.anchor_prefix_pure_transactions, |block| {
128	                    block.prefix_pure_transactions
129	                })
130	                .checked_add(block.pure_transactions)
131	                .ok_or(PolicyError::Arithmetic("pending pure transaction count"))?;
132	            let latest_pure = if block.pure_transactions > 0 {
133	                Some(block.endpoint)
134	            } else {
135	                previous.and_then(|block| block.latest_pure)
136	            };
137	            self.blocks.insert(
138	                block.endpoint.number,
139	                IndexedBlock {
140	                    block,
141	                    prefix_bytes,
142	                    prefix_pure_transactions,
143	                    latest_pure,
144	                },
145	            );
146	        }
147	        Ok(invalidated)
148	    }
149	
150	    pub fn latest_pure(&self) -> Option<L2Endpoint> {
151	        self.blocks
152	            .last_key_value()
153	            .and_then(|(_, block)| block.latest_pure)
154	            .filter(|block| {
155	                self.anchor
156	                    .is_some_and(|anchor| block.number > anchor.number)
157	            })
158	    }
159	
160	    pub fn pending_pure_transactions(&self) -> Result<u64, PolicyError> {
161	        self.blocks
162	            .last_key_value()
163	            .map_or(self.anchor_prefix_pure_transactions, |(_, block)| {
164	                block.prefix_pure_transactions
165	            })
166	            .checked_sub(self.anchor_prefix_pure_transactions)
167	            .ok_or(PolicyError::Arithmetic(
168	                "pending pure transaction prefix subtraction",
169	            ))
170	    }
171	
172	    pub fn endpoint_at(&self, number: u64) -> Option<L2Endpoint> {
173	        self.blocks
174	            .get(&number)
175	            .map(|block| block.block.endpoint)
176	            .or_else(|| self.anchor.filter(|anchor| anchor.number == number))
177	    }
178	
179	    /// Exact size for an anchor-only historical prefix. Its terminal is already
180	    /// indexed and it has no endpoint-dependent derivation or semantic entries.
181	    pub fn historical_stream_bytes(&self, endpoint: L2Endpoint) -> Result<u64, PolicyError> {
182	        let block = self
183	            .blocks
184	            .get(&endpoint.number)
185	            .filter(|block| block.block.endpoint == endpoint)
186	            .ok_or_else(|| {
187	                PolicyError::Unavailable(
188	                    "historical prefix is not in the canonical byte index".into(),
189	                )
190	            })?;
191	        let items = block
192	            .prefix_bytes
193	            .checked_sub(self.anchor_prefix_bytes)
194	            .ok_or(PolicyError::Arithmetic(
195	                "historical byte prefix subtraction",
196	            ))?;
197	        let items = usize::try_from(items)
198	            .map_err(|_| PolicyError::Arithmetic("historical byte prefix"))?;
199	        let payload = eez_payload_codec::self_contained_payload_len(items, 0, 0)
200	            .map_err(|error| PolicyError::Unavailable(error.to_string()))?;
201	        let stream = eez_blob_codec::native_stream_len(payload, 0)
202	            .map_err(|error| PolicyError::Unavailable(error.to_string()))?;
203	        u64::try_from(stream).map_err(|_| PolicyError::Arithmetic("historical stream size"))
204	    }
205	
206	    /// Estimate the complete pending range plus the current terminal block.
207	    /// No blob allocations, padding, hashing, or semantic re-encoding occurs.
208	    #[cfg(test)]
209	    pub fn estimated_stream_bytes(&self, terminal_item_bytes: usize) -> Result<u64, PolicyError> {
210	        self.estimated_stream_bytes_with_overhead(terminal_item_bytes, DaOverhead::default())
211	    }
212	
213	    pub fn estimated_stream_bytes_with_overhead(
214	        &self,
215	        terminal_item_bytes: usize,
216	        overhead: DaOverhead,
217	    ) -> Result<u64, PolicyError> {
218	        let last = self
219	            .blocks
220	            .last_key_value()
221	            .map_or(self.anchor_prefix_bytes, |(_, block)| block.prefix_bytes);
222	        let bytes = last
223	            .checked_sub(self.anchor_prefix_bytes)
224	            .ok_or(PolicyError::Arithmetic("pending byte prefix subtraction"))?;
225	        let bytes = usize::try_from(bytes)
226	            .ok()
227	            .and_then(|bytes| bytes.checked_add(terminal_item_bytes))
228	            .ok_or(PolicyError::Arithmetic("pending block length"))?;
229	        let payload_bytes = eez_payload_codec::self_contained_payload_len(
230	            bytes,
231	            overhead.entry_items,
232	            overhead.group_items,
233	        )
234	        .map_err(|error| PolicyError::Unavailable(error.to_string()))?;
235	        let stream_bytes =
236	            eez_blob_codec::native_stream_len(payload_bytes, overhead.semantic_bytes)
237	                .map_err(|error| PolicyError::Unavailable(error.to_string()))?;
238	        u64::try_from(stream_bytes).map_err(|_| PolicyError::Arithmetic("native stream byte count"))
239	    }
240	}
