242	#[cfg(test)]
243	mod tests {
244	    use super::*;
245	
246	    #[test]
247	    fn individually_fitting_blocks_can_exceed_capacity_before_the_first_sync_boundary() {
248	        use alloy_rlp::Encodable as _;
249	
250	        // Chiado's five-block Sync interval: three ordinary data blocks, then
251	        // two empty blocks. Only the last block is an eligible terminal.
252	        let budget = 2 * eez_blob_codec::DATA_BYTES_PER_BLOB;
253	        let mut parent_hash = B256::ZERO;
254	        let mut bodies = Vec::new();
255	        let mut activity = Vec::new();
256	        for number in 1..=5 {
257	            let mut block = reth_ethereum_primitives::Block::default();
258	            block.header.number = number;
259	            block.header.parent_hash = parent_hash;
260	            if number <= 3 {
261	                block.body.transactions.push(
262	                    reth_ethereum_primitives::TransactionSigned::new_unhashed(
263	                        alloy_consensus::TxLegacy {
264	                            nonce: number - 1,
265	                            input: vec![0u8; 100_164].into(),
266	                            ..Default::default()
267	                        }
268	                        .into(),
269	                        alloy_primitives::Signature::test_signature(),
270	                    ),
271	                );
272	            }
273	            block.header.transactions_root =
274	                alloy_consensus::proofs::calculate_transaction_root(&block.body.transactions);
275	            let hash = block.header.hash_slow();
276	            let body = alloy_rlp::encode(&block);
277	            activity.push(BlockActivity {
278	                endpoint: L2Endpoint { number, hash },
279	                parent_hash,
280	                encoded_item_bytes: body.length() as u64,
281	                pure_transactions: block.body.transactions.len() as u64,
282	            });
283	            bodies.push(body);
284	            parent_hash = hash;
285	        }
286	        let measured_stream = |blocks: &[Vec<u8>]| {
287	            let payload = eez_payload_codec::encode_self_contained(blocks, &[], &[]).unwrap();
288	            eez_blob_codec::encode_native_stream(1, payload.into(), vec![])
289	                .unwrap()
290	                .blob_portion
291	                .len()
292	        };
293	        for body in &bodies {
294	            assert!(measured_stream(std::slice::from_ref(body)) <= budget);
295	        }
296	        assert!(measured_stream(&bodies[..2]) <= budget);
297	        assert!(measured_stream(&bodies[..3]) > budget);
298	        let mut index = ActivityIndex::default();
299	        let endpoint = activity.last().unwrap().endpoint;
300	        index
301	            .update(
302	                L2Endpoint {
303	                    number: 0,
304	                    hash: B256::ZERO,
305	                },
306	                endpoint,
307	                |hash| {
308	                    Ok(*activity
309	                        .iter()
310	                        .find(|block| block.endpoint.hash == hash)
311	                        .unwrap())
312	                },
313	            )
314	            .unwrap();
315	        let first_terminal_bytes = index.historical_stream_bytes(endpoint).unwrap();
316	        assert_eq!(first_terminal_bytes, measured_stream(&bodies) as u64);
317	        assert!(first_terminal_bytes > budget as u64);
318	        assert_eq!(index.pending_pure_transactions().unwrap(), 3);
319	    }
