150	    /// Evaluate one consistent canonical snapshot. No state changes on error.
151	    ///
152	    /// # Errors
153	    /// Missing/contradictory target inputs or overflow. These are deferrals,
154	    /// never evidence that the batch is over capacity or already settled.
155	    pub fn evaluate(
156	        &mut self,
157	        config: &PolicyConfig,
158	        snapshot: PolicySnapshot,
159	    ) -> Result<PolicyDecision, PolicyError> {
160	        let PolicySnapshot {
161	            anchor,
162	            candidate,
163	            target_l1_timestamp,
164	            latest_pure_block,
165	            cross_chain,
166	            estimated_stream_bytes,
167	            effective_blobs,
168	            usable_bytes_per_blob,
169	            drain_coverage,
170	        } = snapshot;
171	        let unsettled_blocks = candidate
172	            .number
173	            .checked_sub(anchor.endpoint.number)
174	            .ok_or_else(|| {
175	                PolicyError::Unavailable("candidate precedes settled endpoint".into())
176	            })?;
177	        let target_ms = target_l1_timestamp
178	            .checked_mul(1000)
179	            .ok_or(PolicyError::Arithmetic("target timestamp in milliseconds"))?;
180	        let anchor_ms = anchor
181	            .l1_timestamp
182	            .checked_mul(1000)
183	            .ok_or(PolicyError::Arithmetic("anchor timestamp in milliseconds"))?;
184	        let settlement_age_ms = target_ms.checked_sub(anchor_ms).ok_or_else(|| {
185	            PolicyError::Unavailable("target precedes canonical anchor timestamp".into())
186	        })?;
187	        if effective_blobs == 0 || usable_bytes_per_blob == 0 {
188	            return Err(PolicyError::Unavailable(
189	                "effective blob capacity is zero or unknown".into(),
190	            ));
191	        }
192	        if let Some(pure) = latest_pure_block
193	            && (pure.number <= anchor.endpoint.number || pure.number > candidate.number)
194	        {
195	            return Err(PolicyError::Unavailable(
196	                "pure activity lies outside the pending range".into(),
197	            ));
198	        }
199	        let mut reasons = DueReasons::default();
200	        if unsettled_blocks >= config.max_unsettled_l2_blocks.get() {
201	            reasons.insert(DueReasons::GENERAL);
202	        }
203	        if latest_pure_block.is_some() {
204	            match config.pure_l2 {
205	                PureL2Mode::Always => reasons.insert(DueReasons::PURE_ALWAYS),
206	                PureL2Mode::Interval { milliseconds } => {
207	                    let deadline = anchor_ms
208	                        .checked_add(milliseconds.get())
209	                        .ok_or(PolicyError::Arithmetic("settlement interval deadline"))?;
210	                    if target_ms >= deadline {
211	                        reasons.insert(DueReasons::PURE_INTERVAL);
212	                    }
213	                }
214	            }
215	        }
216	        let cross_chain_endpoint = match cross_chain {
217	            CrossChainWork::None => None,
218	            CrossChainWork::Executable => Some(candidate),
219	            CrossChainWork::Predecessor(endpoint) => {
220	                if endpoint.number <= anchor.endpoint.number || endpoint.number > candidate.number {
221	                    return Err(PolicyError::Unavailable(
222	                        "cross-chain predecessor is not finite pending history".into(),
223	                    ));
224	                }
225	                Some(endpoint)
226	            }
227	        };
228	        if cross_chain_endpoint.is_some() {
229	            reasons.insert(DueReasons::CROSS_CHAIN);
230	        }
231	        if let Some(fullness) = config.blob_fullness_bps
232	            && unsettled_blocks > 0
233	        {
234	            let occupied = u128::from(estimated_stream_bytes) * 10_000;
235	            let threshold = u128::from(effective_blobs)
236	                .checked_mul(u128::from(usable_bytes_per_blob))
237	                .and_then(|value| value.checked_mul(u128::from(fullness.get())))
238	                .ok_or(PolicyError::Arithmetic("aggregate blob fullness capacity"))?;
239	            if occupied >= threshold {
240	                reasons.insert(DueReasons::FULLNESS);
241	            }
242	        }
243	        let mut drain = match drain_coverage {
244	            DrainCoverage::Pending => self.drain,
245	            DrainCoverage::Covered | DrainCoverage::Replaced => None,
246	        };
247	        let retained_reasons = DueReasons(reasons.0 & !DueReasons::CROSS_CHAIN.0);
248	        if let Some(ref mut intent) = drain {
249	            // Time/general/fullness never extend an unfinished finite drain,
250	            // including after an intermediate prefix advances its anchor.
251	            let new_pure = reasons.contains(DueReasons::PURE_ALWAYS)
252	                && latest_pure_block.is_some_and(|block| block.number > intent.endpoint.number);
253	            if new_pure {
254	                intent.endpoint = candidate;
255	            }
256	            intent.reasons.0 |= retained_reasons.0;
257	            reasons.insert(DueReasons::DRAIN);
258	        } else if !retained_reasons.is_empty() {
259	            drain = Some(DrainIntent {
260	                endpoint: candidate,
261	                reasons: retained_reasons,
262	            });
263	        }
264	        self.drain = drain;
265	        let required_endpoint = match (drain.map(|intent| intent.endpoint), cross_chain_endpoint) {
266	            (Some(periodic), Some(cross)) if periodic.number > cross.number => Some(periodic),
267	            (_, Some(cross)) => Some(cross),
268	            (periodic, None) => periodic,
269	        };
270	        Ok(PolicyDecision {
271	            reasons,
272	            required_endpoint,
273	            unsettled_blocks,
274	            settlement_age_ms,
275	        })
276	    }
277	}
278	
279	#[cfg(test)]
280	mod tests;
