1	//! Per-rollup wall-clock timing configuration.
2	//!
3	//! [`RollupTiming`] is a `Copy` value type carrying these input fields:
4	//!
5	//! - `l1_block_time_ms` — L1 cadence (12 000 mainnet, 5 000 chiado).
6	//! - `l2_block_time_ms` — L2 cadence (2 000 mainnet target, 2 500
7	//!   chiado-slow, 1 000 chiado-fast).
8	//! - `proof_time_ms` — worst-case prover wall-clock budget.
9	//! - `submission_slack_ms` — how early the proven bundle must reach the
10	//!   relay before the next L1 slot. With `proof_time`, sizes the Future
11	//!   region (see [`RollupTiming::future_count`]). Default 100 ms.
12	//! - `preparation_time_ms` — optional separate preparation allowance. Unset
13	//!   preserves the legacy rounded trigger; supplied uses millisecond precision.
14	//!
15	//! Derived helpers ([`RollupTiming::k`], [`RollupTiming::future_count`],
16	//! [`RollupTiming::live_count`], [`RollupTiming::per_trigger_composition`])
17	//! compute the per-sync-slot block layout deterministically from these
18	//! fields. No I/O, no allocation; the Sequencer calls them once per trigger.
19	//!
20	//! Validation ([`RollupTiming::validate`]) refuses any of: non-integer K, K < 2,
21	//! `proof_time + slack ≥ l1_block_time`, `proof_time > (K-1) * l2_block_time`,
22	//! or any zero field. Hard error at startup per `invariant 7` — the
23	//! Sequencer refuses to start on misconfig rather than producing surprising
24	//! block patterns.
25	//!
26	//! Per-rollup placement: stored inside each `RollupState` in the
27	//! `eez-composer` umbrella. Different L2s on the same composer can run
28	//! different timings.
29	//!
30	//! # Worked examples
31	//!
32	//! `future = ceil((proof + slack) / L2) − 1`, `live = K − future − 1`,
33	//! `trigger = L1 − (future + 1)·L2`:
34	//!
35	//! | Deployment  | L1 (ms) | L2 (ms) | proof | slack | K | future | live | trigger (ms) |
36	//! |---|---|---|---|---|---|---|---|---|
37	//! | mainnet     | 12 000  | 2 000   | 4 000 | 1 500 | 6 | 2      | 3    | 6 000        |
38	//! | chiado      | 5 000   | 1 000   | 200   | 1 700 | 5 | 1      | 3    | 3 000        |
39	//! | chiado-slow | 4 000   | 2 000   | 1 500 | 100   | 2 | 0      | 1    | 2 000        |
40	
41	use std::env;
42	use std::num::ParseIntError;
43	use std::time::Duration;
44	
45	use crate::error::{DriverError, DriverResult};
46	
47	/// Cap on Live blocks produced per catchup trigger. Aligned with
48	/// [`MAX_BLOCKS_PER_BATCH`] on the Composer side so one trigger's
49	/// catchup output maps to exactly one postBatch submission. Drop to
50	/// 100 if 300 turns out to produce calldata-gas pressure in practice.
51	pub const MAX_BLOCKS_PER_CATCHUP: u64 = 300;
52	
53	/// Cap on one postBatch's SETTLEMENT range, where [`MAX_BLOCKS_PER_CATCHUP`] caps
54	/// production. `EEZ_MAX_BLOCKS_PER_BATCH` overrides it, rounded down to a multiple
55	/// of K. A chunk shrinks no further than K blocks, so calldata heavier than
56	/// `EEZ_MAX_POSTBATCH_GAS` allows over K blocks cannot settle at any cap.
57	pub const MAX_BLOCKS_PER_BATCH: u64 = MAX_BLOCKS_PER_CATCHUP;
58	
59	const ENV_L1_BLOCK_TIME_MS: &str = "EEZ_L1_BLOCK_TIME_MS";
60	const ENV_L2_BLOCK_TIME_MS: &str = "EEZ_L2_BLOCK_TIME_MS";
61	const ENV_PROOF_TIME_MS: &str = "EEZ_PROOF_TIME_MS";
62	const ENV_SUBMISSION_SLACK_MS: &str = "EEZ_SUBMISSION_SLACK_MS";
63	const ENV_PREPARATION_TIME_MS: &str = "EEZ_PREPARATION_TIME_MS";
64	
65	const DEFAULT_SUBMISSION_SLACK_MS: u32 = 100;
66	
67	/// Per-rollup timing configuration. Cheap `Copy` value type.
68	//
69	// `_ms` postfixes are intentional: each field carries milliseconds at
70	// the raw-arithmetic layer (env parsing + integer validation in
71	// `validate()`). The `Duration` accessors below — `l1_block_time()`,
72	// `l2_block_time()`, etc — are the typed view. Dropping `_ms` would
73	// lose the unit at the integer boundary and is more confusing than the
74	// repetition is worth.
75	#[allow(clippy::struct_field_names)]
76	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
77	pub struct RollupTiming {
78	    l1_block_time_ms: u32,
79	    l2_block_time_ms: u32,
80	    proof_time_ms: u32,
81	    submission_slack_ms: u32,
82	    preparation_time_ms: Option<u32>,
83	}
84	
85	impl RollupTiming {
86	    /// Construct from raw values. Does not validate — call
87	    /// [`Self::validate`] before relying on derived methods, or use
88	    /// [`Self::from_env`] which validates as part of loading.
89	    #[must_use]
90	    pub const fn new(
91	        l1_block_time_ms: u32,
92	        l2_block_time_ms: u32,
93	        proof_time_ms: u32,
94	        submission_slack_ms: u32,
95	    ) -> Self {
96	        Self {
97	            l1_block_time_ms,
98	            l2_block_time_ms,
99	            proof_time_ms,
100	            submission_slack_ms,
101	            preparation_time_ms: None,
102	        }
103	    }
104	
105	    /// Reserve preparation separately from proving and relay submission. The
106	    /// trigger then uses millisecond precision; without this explicit setting,
107	    /// existing profiles retain their whole-L2-block preparation window.
108	    #[must_use]
109	    pub const fn with_preparation_time_ms(mut self, milliseconds: u32) -> Self {
110	        self.preparation_time_ms = Some(milliseconds);
111	        self
112	    }
113	
114	    /// Read fields from `EEZ_L1_BLOCK_TIME_MS`, `EEZ_L2_BLOCK_TIME_MS`,
115	    /// `EEZ_PROOF_TIME_MS`, `EEZ_SUBMISSION_SLACK_MS` (the slack
116	    /// defaults to 100 ms if unset), and optional `EEZ_PREPARATION_TIME_MS`.
117	    /// Runs [`Self::validate`] on the result.
118	    ///
119	    /// # Errors
120	    ///
121	    /// Returns [`DriverError`] for any missing required variable, malformed
122	    /// value, or validation failure.
123	    pub fn from_env() -> DriverResult<Self> {
124	        let mut t = Self::new(
125	            parse_env(ENV_L1_BLOCK_TIME_MS)?,
126	            parse_env(ENV_L2_BLOCK_TIME_MS)?,
127	            parse_env(ENV_PROOF_TIME_MS)?,
128	            parse_env_or(ENV_SUBMISSION_SLACK_MS, DEFAULT_SUBMISSION_SLACK_MS)?,
129	        );
130	        if let Some(value) = parse_optional_env(ENV_PREPARATION_TIME_MS)? {
131	            t = t.with_preparation_time_ms(value);
132	        }
133	        t.validate()?;
134	        Ok(t)
135	    }
136	
137	    /// Verify the invariants from §5.4.4. Hard error on violation;
138	    /// `eez-node` startup refuses to spawn the Sequencer rather than
139	    /// producing surprising block patterns from a misconfigured set.
140	    ///
141	    /// # Errors
142	    ///
143	    /// Returns [`DriverError`] for any of:
144	    /// - any zero field
145	    /// - `L2_block_time % 1000 != 0` — L2 block time must be whole
146	    ///   seconds. Block timestamps are unix integer-seconds and the
147	    ///   Scheduler computes `block_height = (sync_slot_ts - genesis_ts)
148	    ///   / l2_block_secs`; sub-second cadence truncates and leaves the
149	    ///   Sequencer perpetually behind the target.
150	    /// - `L1_block_time % L2_block_time != 0` (K not integer)
151	    /// - `K < 2` (Sync slot must be distinct from surrounding Lives)
152	    /// - `proof_time + submission_slack >= L1_block_time`
153	    /// - `proof_time > (K - 1) * L2_block_time` (no room for Future
154	    ///   blocks before Sync)
155	    /// - preparation is supplied as zero, or the combined preparation, proof
156	    ///   and slack budget exceeds `(K - 1) * L2_block_time`
157	    pub fn validate(&self) -> DriverResult<()> {
158	        if self.l1_block_time_ms == 0 || self.l2_block_time_ms == 0 || self.proof_time_ms == 0 {
159	            return Err(DriverError::timing_config(
160	                "all timing fields (l1_block_time, l2_block_time, proof_time) must be > 0",
161	            ));
162	        }
163	        if !self.l2_block_time_ms.is_multiple_of(1000) {
164	            return Err(DriverError::timing_config(format!(
165	                "L2 block time ({} ms) must be a whole number of seconds; \
166	                 unix block timestamps are integer-second and the sync-slot \
167	                 block-height arithmetic relies on it",
168	                self.l2_block_time_ms,
169	            )));
170	        }
171	        if !self.l1_block_time_ms.is_multiple_of(self.l2_block_time_ms) {
172	            return Err(DriverError::timing_config(format!(
173	                "L1 block time ({} ms) must be an integer multiple of L2 block time ({} ms); K must be integer",
174	                self.l1_block_time_ms, self.l2_block_time_ms,
175	            )));
176	        }
177	        let k = self.k();
178	        if k < 2 {
179	            return Err(DriverError::timing_config(format!(
180	                "K must be >= 2 (got {k}); Sync slot must be distinct from surrounding Live blocks"
181	            )));
182	        }
183	        if self.preparation_time_ms == Some(0) {
184	            return Err(DriverError::timing_config(
185	                "EEZ_PREPARATION_TIME_MS must be positive when supplied",
186	            ));
187	        }
188	        let budget = self
189	            .proof_time_ms
190	            .checked_add(self.submission_slack_ms)
191	            .and_then(|n| n.checked_add(self.preparation_time_ms.unwrap_or(0)))
192	            .ok_or_else(|| DriverError::timing_config("combined timing budget overflow"))?;
193	        if self.proof_time_ms.saturating_add(self.submission_slack_ms) >= self.l1_block_time_ms {
194	            return Err(DriverError::timing_config(format!(
195	                "proof_time ({} ms) + submission_slack ({} ms) must be < L1 block time ({} ms)",
196	                self.proof_time_ms, self.submission_slack_ms, self.l1_block_time_ms,
197	            )));
198	        }
199	        let max_budget = (k - 1) * self.l2_block_time_ms;
200	        if self.proof_time_ms.saturating_add(self.submission_slack_ms) > max_budget {
201	            return Err(DriverError::timing_config(format!(
202	                "proof_time ({} ms) + submission_slack ({} ms) must be <= (K-1) * L2 block time ({} * {} = {} ms); else there is no room for Future blocks before Sync",
203	                self.proof_time_ms,
204	                self.submission_slack_ms,
205	                k - 1,
206	                self.l2_block_time_ms,
207	                max_budget,
208	            )));
209	        }
210	        if budget > max_budget {
211	            return Err(DriverError::timing_config(format!(
212	                "preparation + proof + submission slack ({budget} ms) must fit the \
213	                 Future region ({max_budget} ms), leaving at least one Live block"
214	            )));
215	        }
216	        Ok(())
217	    }
218	
219	    /// L1 block time as a [`Duration`].
220	    #[must_use]
221	    pub const fn l1_block_time(self) -> Duration {
222	        Duration::from_millis(self.l1_block_time_ms as u64)
223	    }
224	
225	    /// L2 block time as a [`Duration`].
226	    #[must_use]
227	    pub const fn l2_block_time(self) -> Duration {
228	        Duration::from_millis(self.l2_block_time_ms as u64)
229	    }
230	
231	    /// Prover wall-clock budget as a [`Duration`].
232	    #[must_use]
233	    pub const fn proof_time(self) -> Duration {
234	        Duration::from_millis(self.proof_time_ms as u64)
235	    }
236	
237	    /// Relay-submission slack as a [`Duration`].
238	    #[must_use]
239	    pub const fn submission_slack(self) -> Duration {
240	        Duration::from_millis(self.submission_slack_ms as u64)
241	    }
242	
243	    /// L2 blocks per sync slot. `K = L1_block_time / L2_block_time`.
244	    #[must_use]
245	    pub const fn k(self) -> u32 {
246	        self.l1_block_time_ms / self.l2_block_time_ms
247	    }
248	
249	    /// Future blocks per slot: `ceil((preparation + proof + slack) / l2) − 1`,
250	    /// where preparation contributes zero when not explicitly configured.
251	    /// Sized so the proven bundle reaches the relay `submission_slack` before
252	    /// the next L1 slot, letting the postBatch target the immediate next block.
253	    #[must_use]
254	    pub const fn future_count(self) -> u32 {
255	        let budget_ms = self
256	            .proof_time_ms
257	            .saturating_add(self.submission_slack_ms)
258	            .saturating_add(match self.preparation_time_ms {
259	                Some(value) => value,
260	                None => 0,
261	            });
262	        // Manual ceil — div_ceil isn't const on the pinned toolchain.
263	        let blocks = budget_ms
264	            .saturating_add(self.l2_block_time_ms)
265	            .saturating_sub(1)
266	            / self.l2_block_time_ms;
267	        blocks.saturating_sub(1)
268	    }
269	
270	    /// Live blocks per slot — the L2 blocks already produced on
271	    /// wall-clock cadence by the time the trigger fires.
272	    #[must_use]
273	    pub const fn live_count(self) -> u32 {
274	        self.k() - self.future_count() - 1
275	    }
276	
277	    /// Wall-clock offset after the anchor L1 block at which the trigger
278	    /// fires. An explicit preparation allowance reserves exactly preparation +
279	    /// proof + slack, with millisecond precision. Otherwise the legacy trigger
280	    /// remains at the end of the Live region, `l1 − (future + 1)·l2`.
281	    #[must_use]
282	    pub const fn proof_window_open(self) -> Duration {
283	        if let Some(preparation) = self.preparation_time_ms {
284	            let reserved_ms = preparation
285	                .saturating_add(self.proof_time_ms)
286	                .saturating_add(self.submission_slack_ms);
287	            return Duration::from_millis(self.l1_block_time_ms.saturating_sub(reserved_ms) as u64);
288	        }
289	        let reserved_ms = (self.future_count() + 1).saturating_mul(self.l2_block_time_ms);
290	        Duration::from_millis(self.l1_block_time_ms.saturating_sub(reserved_ms) as u64)
291	    }
292	
293	    /// Wall-clock offset from "L1 block N landed" by which the
294	    /// postBatch bundle must reach the relay
295	    /// (`L1_block_time - submission_slack`).
296	    #[must_use]
297	    pub const fn submission_deadline(self) -> Duration {
298	        Duration::from_millis((self.l1_block_time_ms - self.submission_slack_ms) as u64)
299	    }
300	
301	    /// Decide what to produce at a sync-slot trigger given the current
302	    /// L2 head, the target sync-slot block height, and the per-trigger
303	    /// catchup budget.
304	    ///
305	    /// `max_catchup_blocks` bounds a Catchup chunk to the K-grid; the
306	    /// Sequencer always passes [`MAX_BLOCKS_PER_CATCHUP`] (catchup does not
307	    /// enforce the speculative cap — that's steady-only).
308	    ///
309	    /// Catchup if closing the slot needs > `K` blocks, else the slot suffix
310	    /// (Live + Future + 1 Sync). [`SlotComposition::Idle`] when head ≥
311	    /// `sync_slot_block`, or the budget can't reach a grid height above head.
312	    #[must_use]
313	    pub fn per_trigger_composition(
314	        self,
315	        head_block: u64,
316	        sync_slot_block: u64,
317	        max_catchup_blocks: u64,
318	    ) -> SlotComposition {
319	        if head_block >= sync_slot_block {
320	            return SlotComposition::Idle;
321	        }
322	
323	        let future = u64::from(self.future_count());
324	        let k = u64::from(self.k());
325	        let live_region_end = sync_slot_block.saturating_sub(future + 1);
326	
327	        if head_block < live_region_end {
328	            // Below Live region. Steady-state if we can close the
329	            // slot this trigger; Catchup otherwise.
330	            let live_to_produce = live_region_end - head_block;
331	            // K - (future + 1) = max Live blocks per steady-state slot.
332	            if live_to_produce <= k.saturating_sub(future + 1) {
333	                SlotComposition::Slot {
334	                    live: live_to_produce,
335	                    future,
336	                }
337	            } else {
338	                // Over-catch: snap the terminal to the K-grid (step back from
339	                // the target by whole K's until it fits) so the deriver
340	                // re-derives it — robust to a genesis off the slot boundary.
341	                let gap = sync_slot_block - head_block;
342	                let steps_back = gap.saturating_sub(max_catchup_blocks).div_ceil(k);
343	                let snap = steps_back.saturating_mul(k);
344	                if snap >= sync_slot_block || sync_slot_block - snap <= head_block {
345	                    // Budget can't reach a grid height above head; wait.
346	                    SlotComposition::Idle
347	                } else {
348	                    SlotComposition::Catchup {
349	                        live: sync_slot_block - snap - head_block - 1,
350	                    }
351	                }
352	            }
353	        } else {
354	            // Inside the Future region already — produce the remainder
355	            // of the slot suffix. This happens if a previous trigger
356	            // overshot.
357	            let in_future = head_block - live_region_end;
358	            let remaining_future = future.saturating_sub(in_future);
359	            SlotComposition::Slot {
360	                live: 0,
361	                future: remaining_future,
362	            }
363	        }
364	    }
365	
366	    /// Terminal for a bounded settlement chunk: the largest height
367	    /// `<= cursor + cap` sharing `sync_height`'s K-residue (the deriver rebuilds
368	    /// a terminal by position). `None` if none lies strictly between the two.
369	    #[must_use]
370	    pub fn historical_chunk_boundary(self, cursor: u64, sync_height: u64, cap: u64) -> Option<u64> {
371	        let k = u64::from(self.k());
372	        let over = sync_height.saturating_sub(cursor.saturating_add(cap));
373	        let boundary = sync_height.checked_sub(over.div_ceil(k).saturating_mul(k))?;
374	        (boundary > cursor && boundary < sync_height).then_some(boundary)
375	    }
376	}
377	
378	/// Output of [`RollupTiming::per_trigger_composition`].
379	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
380	pub enum SlotComposition {
381	    /// Already at or past the target sync slot. No blocks to produce
382	    /// this trigger.
383	    Idle,
384	    /// Catchup: `live` blocks then a terminal Sync block at the grid-snapped
385	    /// height `head + live + 1`. Past/capped terminals are structural-only.
386	    /// When the burst reaches the requested future target, the Sequencer uses
387	    /// its Future suffix and rechecks eligibility for a steady Sync slot.
388	    Catchup { live: u64 },
389	    /// Steady-state: produce `live` Live blocks + `future` Future
390	    /// blocks + 1 Sync block (always implicit when this variant is
391	    /// returned).
392	    Slot { live: u64, future: u64 },
393	}
394	
395	fn parse_env(name: &str) -> DriverResult<u32> {
396	    let raw =
397	        env::var(name).map_err(|_| DriverError::timing_config(format!("{name} is required")))?;
398	    raw.parse::<u32>()
399	        .map_err(|e: ParseIntError| DriverError::timing_config(format!("{name}: {e}")))
400	}
401	
402	fn parse_env_or(name: &str, default: u32) -> DriverResult<u32> {
403	    Ok(parse_optional_env(name)?.unwrap_or(default))
404	}
405	
406	fn parse_optional_env(name: &str) -> DriverResult<Option<u32>> {
407	    match env::var(name) {
408	        Ok(v) => v
409	            .parse::<u32>()
410	            .map(Some)
411	            .map_err(|e: ParseIntError| DriverError::timing_config(format!("{name}: {e}"))),
412	        Err(env::VarError::NotPresent) => Ok(None),
413	        Err(env::VarError::NotUnicode(_)) => Err(DriverError::timing_config(format!(
414	            "{name} contains non-UTF-8 bytes"
415	        ))),
416	    }
417	}
