419	#[cfg(test)]
420	mod tests {
421	    use super::*;
422	
423	    fn mainnet() -> RollupTiming {
424	        // proof+slack = 5500 → future = 2, live = 3, trigger = +6s.
425	        RollupTiming::new(12_000, 2_000, 4_000, 1_500)
426	    }
427	
428	    // K=2 devnet timing. Whole-second L2 only — sub-second cadence
429	    // trips `.as_secs()` truncation in the Scheduler (see `validate`).
430	    fn chiado_slow() -> RollupTiming {
431	        // proof+slack = 1600 → future = 0, live = 1.
432	        RollupTiming::new(4_000, 2_000, 1_500, 100)
433	    }
434	
435	    // Real chiado deployment: proof+slack = 1900 → future = 1, live = 3,
436	    // trigger = +3s, so the postBatch targets the immediate next L1 block.
437	    fn chiado_fast() -> RollupTiming {
438	        RollupTiming::new(5_000, 1_000, 200, 1_700)
439	    }
440	
441	    /// After an off-grid settlement the cursor sits one below the grid. The next
442	    /// trigger must still end ON the grid — the range just gets longer.
443	    #[test]
444	    fn an_off_grid_cursor_realigns_on_the_next_slot() {
445	        let t = mainnet();
446	        let k = u64::from(t.k());
447	        // Off-grid head/cursor: one below an on-grid sync height.
448	        let head = 174_197_u64;
449	        assert_ne!(head % k, 0, "fixture must be off-grid");
450	
451	        // Next grid height above it.
452	        let sync = 174_198_u64;
453	        let comp = t.per_trigger_composition(head, sync, 64);
454	        let produced = match comp {
455	            SlotComposition::Slot { live, future } => live + future + 1,
456	            SlotComposition::Catchup { live } => live + 1,
457	            SlotComposition::Idle => 0,
458	        };
459	        assert!(produced > 0, "must produce the realigning Sync block");
460	        assert_eq!(head + produced, sync, "terminal must land on the grid");
461	        assert_eq!((head + produced) % k, 0);
462	
463	        // The drift cannot persist: the next target is absolute, so the span
464	        // stretches to reach it (K+1 here) instead of inheriting the offset.
465	        let far = t.per_trigger_composition(head, sync + k, 300);
466	        let produced_far = match far {
467	            SlotComposition::Slot { live, future } => live + future + 1,
468	            SlotComposition::Catchup { live } => live + 1,
469	            SlotComposition::Idle => 0,
470	        };
471	        assert_eq!(
472	            head + produced_far,
473	            sync + k,
474	            "must reach the absolute target"
475	        );
476	        assert_eq!(produced_far, k + 1, "one longer-than-K span realigns it");
477	
478	        // A whole slot later: still on-grid, normal K-block span.
479	        let sync2 = sync + k;
480	        let comp2 = t.per_trigger_composition(sync, sync2, 64);
