1	//! Startup settings passed to the composer after validation. Environment
2	//! access belongs at the launcher boundary, before nodes or workers start.
3	
4	use std::collections::HashMap;
5	
6	use eez_driver::{DEFAULT_MAX_SPECULATIVE_DEPTH, RollupTiming};
7	use eez_l1::posting_fees::{PostingFeeConfig, PostingFeeError};
8	
9	use crate::settlement_policy::{PolicyConfig, PolicyError};
10	
11	#[derive(Debug, Clone)]
12	pub struct ComposerSettings {
13	    pub(super) timing: RollupTiming,
14	    pub(super) policy: Option<PolicyConfig>,
15	    pub(super) max_blobs_per_batch: Option<u64>,
16	    /// `None` selects automatic resource/time admission. Numeric settings keep
17	    /// the existing operator count limit, including the unset default of 50.
18	    pub(super) max_user_txs_per_bundle: Option<usize>,
19	    pub(super) posting_fees: Option<PostingFeeConfig>,
20	    pub(super) emission: super::EmissionLimits,
21	    max_speculative_depth: u64,
22	}
23	
24	impl ComposerSettings {
25	    pub fn from_env(timing: RollupTiming) -> Result<Self, PolicyError> {
26	        Self::parse(timing, |name| match std::env::var(name) {
27	            Ok(value) => Ok(Some(value)),
28	            Err(std::env::VarError::NotPresent) => Ok(None),
29	            Err(_) => Err(PolicyError::Config(format!(
30	                "{name} contains non-UTF-8 bytes"
31	            ))),
32	        })
33	    }
34	
35	    /// Parse one immutable startup snapshot. A shared setting is read from its
36	    /// source once even when both the policy and sequencer validate/use it.
37	    pub fn parse(
38	        timing: RollupTiming,
39	        mut read: impl FnMut(&str) -> Result<Option<String>, PolicyError>,
40	    ) -> Result<Self, PolicyError> {
41	        timing
42	            .validate()
43	            .map_err(|error| PolicyError::Config(error.to_string()))?;
44	        let mut snapshot: HashMap<String, Option<String>> = HashMap::new();
45	        let mut get = |name: &str| {
46	            if let Some(value) = snapshot.get(name) {
47	                return Ok(value.clone());
48	            }
49	            let value = read(name)?;
50	            snapshot.insert(name.to_owned(), value.clone());
51	            Ok(value)
52	        };
53	        let policy = PolicyConfig::parse(&mut get, u64::from(timing.k()))?;
54	        let enabled = policy.is_some();
55	        let posting_fees = if enabled {
56	            Some(
57	                PostingFeeConfig::parse(|name| {
58	                    get(name).map_err(|error| PostingFeeError::Config(error.to_string()))
59	                })
60	                .map_err(|error| PolicyError::Config(error.to_string()))?,
61	            )
62	        } else {
63	            for name in [
64	                "EEZ_L1_POSTBATCH_MAX_FEE_PER_GAS",
65	                "EEZ_L1_POSTBATCH_MAX_FEE_PER_BLOB_GAS",
66	                "EEZ_L1_POSTBATCH_MIN_PRIORITY_FEE",
67	                "EEZ_L1_POSTBATCH_MAX_PRIORITY_FEE",
68	                "EEZ_L1_POSTBATCH_PRIORITY_MARGIN_BPS",
69	                "EEZ_L1_POSTBATCH_EXECUTION_HEADROOM_BPS",
70	                "EEZ_L1_POSTBATCH_BLOB_HEADROOM_BPS",
