1	//! `RemoteProver` — the composer-side [`Prover`] backed by one `Prove` RPC.
2	//!
3	//! The composer holds `Arc<dyn Prover>` and calls `prove(ctx)`; when that
4	//! `Arc` is a [`RemoteProver`], the call maps [`ProvingContext`] to a
5	//! `prove.v1` client-stream (a header then one chunk per window block), dials
6	//! the configured `eez-proof-signer`, awaits the attestation, verifies it recovers
7	//! to the registered attester over the exact request batch and physical blobs,
8	//! and returns the 65-byte signature. Stateless:
9	//! one round-trip, no feed/cursor/sink.
10	
11	#![cfg_attr(not(test), warn(unused_crate_dependencies))]
12	
13	use std::sync::Arc;
14	
15	use alloy_primitives::{Address, B256, Bytes, Signature};
16	use alloy_sol_types::SolCall;
17	use async_trait::async_trait;
18	use eez_control_rpc::v1::{
19	    BlockWitness as WireBlockWitness, ExecutionWitness as WireWitness, PostBatch, ProveChunk,
20	    ProveHeader, prove_chunk, prove_failure, prover_client::ProverClient,
21	};
22	use eez_prover::{
23	    ActionableProverFailure, Prover, ProverError, ProverResult, ProvingContext,
24	    RetryableProverError,
25	};
26	use tonic::{Code, Status};
27	use tracing::{Level, event};
28	
29	/// A [`Prover`] that proves a window on a remote `eez-proof-signer` over the
30	/// `prove.v1.Prover` gRPC service. Cheap to clone (`Arc<Inner>`).
31	#[derive(Debug, Clone)]
32	pub struct RemoteProver {
33	    inner: Arc<Inner>,
34	}
35	
36	#[derive(Debug)]
37	struct Inner {
38	    /// The `eez-proof-signer` endpoint, e.g. `http://127.0.0.1:50061`.
39	    url: String,
40	    /// The proof system's registered attester. The returned signature MUST
41	    /// recover to this over the returned `publicInputsHash`, or the proof is
42	    /// rejected (a wrong/malicious prover cannot forge an attestation).
43	    attester: Address,
44	}
45	
46	impl RemoteProver {
47	    /// Build a remote prover pointing at `url`, verifying attestations against
48	    /// the registered `attester`.
49	    #[must_use]
50	    pub fn new(url: impl Into<String>, attester: Address) -> Self {
51	        Self {
52	            inner: Arc::new(Inner {
53	                url: url.into(),
54	                attester,
55	            }),
56	        }
57	    }
58	
59	    /// The registered attester this prover verifies against.
60	    #[must_use]
61	    pub fn attester(&self) -> Address {
62	        self.inner.attester
63	    }
64	}
65	
66	/// Map a [`ProvingContext`] to the ordered `Prove` chunk stream: header first
67	/// (with the authoritative postBatch calldata), then one chunk per block.
68	fn chunks_for(ctx: &ProvingContext) -> Vec<ProveChunk> {
69	    // The authoritative on-chain payload (proofs[] empty — the proof isn't part
70	    // of the publicInputsHash). The prover decodes THIS to recompute the hash.
71	    let abi_calldata = eez_protocol::abi::postAndVerifyBatchCall {
72	        batch: ctx.batch.clone(),
73	    }
74	    .abi_encode();
75	
76	    let mut chunks = Vec::with_capacity(1 + ctx.blocks.len());
77	    chunks.push(ProveChunk {
78	        kind: Some(prove_chunk::Kind::Header(ProveHeader {
79	            rollup_id: ctx.rollup_id,
80	            from_block: ctx.from_block,
81	            to_block: ctx.to_block,
82	            post_batch: Some(PostBatch {
83	                abi_calldata,
84	                // Empty: the prover recomputes the hash and returns it; we don't
85	                // pre-claim it (the batch determines it deterministically).
86	                public_inputs_hash: Vec::new(),
87	                l1_block_hash: ctx.l1_block_hash.map(|h| h.to_vec()).unwrap_or_default(),
88	                posting_context: Some(eez_control_rpc::v1::L1PostingContext {
89	                    chain_id: ctx.l1_posting.chain_id,
90	                    target_timestamp: ctx.l1_posting.target_timestamp,
91	                }),
92	                blobs: ctx
93	                    .blobs
94	                    .iter()
95	                    .map(|blob| blob.as_bytes().to_vec())
96	                    .collect(),
97	            }),
98	        })),
99	    });
100	    for bw in &ctx.blocks {
101	        chunks.push(ProveChunk {
102	            kind: Some(prove_chunk::Kind::Block(WireBlockWitness {
103	                number: bw.number,
104	                hash: bw.hash.to_vec(),
105	                parent_hash: bw.parent_hash.to_vec(),
106	                rlp: bw.rlp.to_vec(),
107	                witness: Some(WireWitness {
108	                    state: bw.witness.state.iter().map(|b| b.to_vec()).collect(),
109	                    codes: bw.witness.codes.iter().map(|b| b.to_vec()).collect(),
110	                    keys: bw.witness.keys.iter().map(|b| b.to_vec()).collect(),
111	                    headers: bw.witness.headers.iter().map(|b| b.to_vec()).collect(),
112	                }),
113	            })),
114	        });
115	    }
116	    chunks
117	}
118	
119	#[async_trait]
120	impl Prover for RemoteProver {
121	    async fn prove(&self, ctx: ProvingContext) -> ProverResult<Bytes> {
122	        let chunks = chunks_for(&ctx);
123	        let n_blocks = chunks.len().saturating_sub(1);
124	
125	        // Raise the message-size cap on both directions: a single block's witness
126	        // can exceed tonic's 4 MiB default → `ResourceExhausted`. Server matches.
127	        let mut client = ProverClient::connect(self.inner.url.clone())
128	            .await
129	            .map_err(|error| ProverError::Retryable {
130	                kind: RetryableProverError::Unavailable,
131	                message: format!("connect {}: {error}", self.inner.url),
132	            })?
133	            .max_encoding_message_size(eez_control_rpc::MAX_MESSAGE_BYTES)
134	            .max_decoding_message_size(eez_control_rpc::MAX_MESSAGE_BYTES);
135	        let resp = client
136	            .prove(tokio_stream::iter(chunks))
137	            .await
138	            .map_err(|status| map_rpc_status(ctx.from_block, ctx.to_block, status))?
139	            .into_inner();
140	
141	        // Bind both the signing authority and the signed payload. A signature
142	        // from the registered attester over another batch is not our proof.
143	        let hash = verify_attestation(
144	            &resp.signature,
145	            &resp.public_inputs_hash,
146	            self.inner.attester,
147	        )?;
148	        let from_block = ctx.from_block;
149	        let to_block = ctx.to_block;
150	        let vkey = self.vkey();
151	        // KZG commitment calculation is CPU work; keep it off the async worker.
152	        let expected_hash = tokio::task::spawn_blocking(move || request_hash(&ctx, vkey))
153	            .await
154	            .map_err(|error| {
155	                ProverError::Backend(format!("public-input preflight worker: {error}"))
156	            })??;
157	        if hash != expected_hash {
158	            return Err(ProverError::Backend(format!(
159	                "attestation publicInputsHash {hash} != request hash {expected_hash}"
160	            )));
161	        }
162	        event!(
163	            name: "eez.prover_client.attested",
164	            Level::INFO,
165	            event_name = "eez.prover_client.attested",
166	            from = from_block,
167	            to = to_block,
168	            blocks = n_blocks,
169	            %hash,
170	            "remote prover attested the window",
171	        );
172	        Ok(Bytes::copy_from_slice(&resp.signature))
173	    }
174	
175	    fn vkey(&self) -> B256 {
176	        // Left-zero-pad the 20-byte attester into a B256 (the registry vkey).
177	        self.inner.attester.into_word()
178	    }
179	}
180	
181	/// Recompute the sole proof carrier from the exact request, deriving versioned
182	/// hashes from physical blobs instead of accepting a remote hash claim.
183	fn request_hash(ctx: &ProvingContext, vkey: B256) -> ProverResult<B256> {
184	    let blob_hashes = eez_blob_codec::blob_versioned_hashes(&ctx.blobs)
185	        .map_err(|error| ProverError::Backend(format!("request blob commitments: {error}")))?;
186	    let hashes =
187	        eez_protocol::public_inputs_hashes_with_blob_hashes(&ctx.batch, vkey, &blob_hashes)
188	            .map_err(|error| ProverError::Backend(format!("request public inputs: {error}")))?;
189	    match hashes.as_slice() {
190	        [hash] => Ok(*hash),
191	        _ => Err(ProverError::Backend(format!(
192	            "request has {} public-input hashes, expected one",
193	            hashes.len()
194	        ))),
195	    }
196	}
197	
198	/// Preserve the Composer profile's closed retryable-status allowlist across
199	/// the transport-neutral [`Prover`] boundary. Every other non-OK status is a
200	/// non-retryable backend rejection for the unchanged request.
201	fn map_rpc_status(from_block: u64, to_block: u64, status: Status) -> ProverError {
202	    let kind = match status.code() {
203	        Code::Unavailable => Some(RetryableProverError::Unavailable),
204	        Code::DeadlineExceeded => Some(RetryableProverError::DeadlineExceeded),
205	        Code::Aborted => Some(RetryableProverError::Aborted),
206	        _ => None,
207	    };
208	    let message = format!("Prove {from_block}-{to_block}: {status}");
209	    match kind {
210	        Some(kind) => ProverError::Retryable { kind, message },
211	        None if status.code() == Code::FailedPrecondition => {
212	            match decode_actionable_failure(status.details()) {
213	                Some(failure) => ProverError::Actionable { failure, message },
214	                None => ProverError::Backend(message),
215	            }
216	        }
217	        None => ProverError::Backend(message),
218	    }
219	}
220	
221	/// Decode only the exact candidate identities the Composer can act on.
222	/// Empty, malformed, or wrong-length details remain non-actionable.
223	fn decode_actionable_failure(details: &[u8]) -> Option<ActionableProverFailure> {
224	    if details.is_empty() {
225	        return None;
226	    }
227	    let failure = eez_control_rpc::decode_prove_failure(details)
228	        .ok()?
229	        .actionable_failure?;
230	    match failure {
231	        prove_failure::ActionableFailure::Outbound(outbound) => {
232	            Some(ActionableProverFailure::Outbound {
233	                transaction_index: outbound.transaction_index.try_into().ok()?,
234	                transaction_hash: exact_hash(&outbound.transaction_hash)?,
235	            })
236	        }
237	        prove_failure::ActionableFailure::Inbound(inbound) => {
238	            Some(ActionableProverFailure::Inbound {
239	                entry_index: inbound.entry_index.try_into().ok()?,
240	                entry_hash: exact_hash(&inbound.entry_hash)?,
241	            })
242	        }
243	    }
244	}
245	
246	fn exact_hash(bytes: &[u8]) -> Option<B256> {
247	    (bytes.len() == B256::len_bytes()).then(|| B256::from_slice(bytes))
248	}
249	
250	/// Verify a prover attestation: the 65-byte signature must recover to `attester`
251	/// over the 32-byte `public_inputs_hash`. Returns the bound hash on success.
252	///
253	/// # Errors
254	///
255	/// [`ProverError::Backend`] on a wrong-length signature or hash, a malformed
256	/// signature, non-canonical `s` or `v`, or a signer that isn't the registered attester.
257	fn verify_attestation(
258	    signature: &[u8],
259	    public_inputs_hash: &[u8],
260	    attester: Address,
261	) -> ProverResult<B256> {
262	    if signature.len() != 65 {
263	        return Err(ProverError::Backend(format!(
264	            "attestation is {} bytes, expected 65 (r||s||v)",
265	            signature.len()
266	        )));
267	    }
268	    if public_inputs_hash.len() != 32 {
269	        return Err(ProverError::Backend(format!(
270	            "publicInputsHash is {} bytes, expected 32",
271	            public_inputs_hash.len()
272	        )));
273	    }
274	    let hash = B256::from_slice(public_inputs_hash);
275	    if !matches!(signature[64], 27 | 28) {
276	        return Err(ProverError::Backend(
277	            "attestation v must be 27 or 28".into(),
278	        ));
279	    }
280	    let sig = Signature::try_from(signature)
281	        .map_err(|e| ProverError::Backend(format!("malformed attestation signature: {e}")))?;
282	    if sig.normalize_s().is_some() {
283	        return Err(ProverError::Backend(
284	            "attestation must use canonical low-s".into(),
285	        ));
286	    }
287	    let recovered = sig
288	        .recover_address_from_prehash(&hash)
289	        .map_err(|e| ProverError::Backend(format!("attestation recover failed: {e}")))?;
290	    if recovered != attester {
291	        return Err(ProverError::Backend(format!(
292	            "attestation signer {recovered} != registered attester {attester}"
293	        )));
294	    }
295	    Ok(hash)
296	}
