1	//! Persistent per-block witness store for the composer-controlled prover
2	//! (remote mode).
3	//!
4	//! At commit, the committer feeds each produced block's hash to [`run_capture`],
5	//! which re-executes it (parent state still fresh) and persists the augmented
6	//! witness. [`NodeWitnessSource`] serves the committed window of
7	//! [`eez_prover::ProvingContext::blocks`] from the store, re-execing on demand
8	//! only for the newest blocks not yet drained.
9	//!
10	//! Persistent (mdbx), not RAM: the node is non-archival, so by settlement time an
11	//! older block's parent state is pruned — a RAM store lost on restart couldn't
12	//! re-derive it, stalling a restart with an unsettled backlog. Dedicated env
13	//! (never reth's node DB; path `EEZ_WITNESS_DB_PATH`), keyed by block number.
14	//!
15	//! Purge floor = L1-FINALIZED (not merely-posted) L2 height: an L1 reorg could
16	//! roll a posted batch out and need its witness back. The endpoint (uncommitted
17	//! Sync block) is captured by the composer's `endpoint_witness`, not here.
18	
19	use std::path::Path;
20	use std::sync::Arc;
21	
22	use alloy_consensus::Header;
23	use alloy_eips::BlockHashOrNumber;
24	use alloy_primitives::{B256, Bytes};
25	use alloy_rpc_types_debug::ExecutionWitness;
26	use eez_driver::witness::{ExecutionWitnessMode, block_witness};
27	use eez_prover::{BlockWitness, ProvingWitnessSource};
28	use reth_ethereum_primitives::{Block, EthPrimitives};
29	use reth_evm::ConfigureEvm;
30	use reth_libmdbx::{DatabaseFlags, Environment, Geometry, WriteFlags};
31	use reth_storage_api::{BlockReader, HeaderProvider, StateProviderFactory, TransactionVariant};
32	use tokio::sync::mpsc;
33	use tracing::{Level, event};
34	
35	const GIGABYTE: usize = 1024 * 1024 * 1024;
36	/// mdbx reserves this as sparse virtual address space (no preallocation) and
37	/// grows the file lazily, so a generous cap just means "never `MAP_FULL`".
38	const MAP_MAX_BYTES: usize = 256 * GIGABYTE;
39	const GROWTH_STEP: isize = 1024 * 1024 * 1024;
40	
41	/// Persistent witness store: a dedicated mdbx env keyed by block number
42	/// (big-endian, so key order == numeric order → ordered purge). Cheap `Arc`
43	/// clone; mdbx MVCC needs no extra lock.
44	pub struct WitnessDb {
45	    env: Environment,
46	}
47	
48	impl std::fmt::Debug for WitnessDb {
49	    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
50	        f.debug_struct("WitnessDb").finish_non_exhaustive()
51	    }
52	}
53	
54	impl WitnessDb {
55	    /// Open (creating if absent) the witness env at `path`.
56	    ///
57	    /// # Errors
58	    /// Filesystem or mdbx open failures.
59	    pub fn open(path: &Path) -> eyre::Result<Self> {
60	        std::fs::create_dir_all(path)?;
61	        let mut builder = Environment::builder();
62	        builder.set_geometry(Geometry {
63	            size: Some(0..MAP_MAX_BYTES),
64	            growth_step: Some(GROWTH_STEP),
65	            shrink_threshold: None,
66	            page_size: None,
67	        });
68	        let env = builder
69	            .open(path)
70	            .map_err(|e| eyre::eyre!("open witness env at {}: {e}", path.display()))?;
71	        let txn = env.begin_rw_txn()?;
72	        txn.create_db(None, DatabaseFlags::empty())?; // default (unnamed) table
73	        txn.commit()?;
74	        Ok(Self { env })
75	    }
76	
77	    /// Persist `bw` under its block number (overwrites on reorg re-capture).
78	    ///
79	    /// # Errors
80	    /// Serialization or mdbx write failures.
81	    pub fn put(&self, number: u64, bw: &BlockWitness) -> eyre::Result<()> {
82	        let bytes = postcard::to_allocvec(&StoredWitness::from(bw))
83	            .map_err(|e| eyre::eyre!("encode witness {number}: {e}"))?;
84	        let txn = self.env.begin_rw_txn()?;
85	        let db = txn.open_db(None)?;
86	        txn.put(db.dbi(), number.to_be_bytes(), &bytes, WriteFlags::UPSERT)?;
87	        txn.commit()?;
88	        Ok(())
89	    }
90	
91	    /// Read the witness at `number`, or `None` if absent.
92	    ///
93	    /// # Errors
94	    /// mdbx read or deserialization failures.
95	    pub fn get(&self, number: u64) -> eyre::Result<Option<BlockWitness>> {
96	        let txn = self.env.begin_ro_txn()?;
97	        let db = txn.open_db(None)?;
98	        let raw: Option<Vec<u8>> = txn.get(db.dbi(), &number.to_be_bytes())?;
99	        match raw {
100	            Some(bytes) => {
101	                let stored: StoredWitness = postcard::from_bytes(&bytes)
102	                    .map_err(|e| eyre::eyre!("decode witness {number}: {e}"))?;
103	                Ok(Some(stored.into()))
104	            }
105	            None => Ok(None),
106	        }
107	    }
