109	    /// Delete every witness with block number `< below`, returning the count.
110	    /// Call with the L1-FINALIZED L2 height — those blocks can't need re-settlement.
111	    ///
112	    /// # Errors
113	    /// mdbx write failures.
114	    pub fn purge_settled(&self, below: u64) -> eyre::Result<usize> {
115	        let below_be = below.to_be_bytes();
116	        let txn = self.env.begin_rw_txn()?;
117	        let db = txn.open_db(None)?;
118	        // Collect-then-delete in one txn: mdbx cursor-during-delete is subtle.
119	        let mut doomed: Vec<[u8; 8]> = Vec::new();
120	        {
121	            let mut cursor = txn.cursor(db.dbi())?;
122	            let mut entry: Option<([u8; 8], ())> = cursor.first()?;
123	            while let Some((key, ())) = entry {
124	                if key >= below_be {
125	                    break; // ordered keys → the rest are all >= floor
126	                }
127	                doomed.push(key);
128	                entry = cursor.next()?;
129	            }
130	        }
131	        for key in &doomed {
132	            txn.del(db.dbi(), key, None)?;
133	        }
134	        txn.commit()?;
135	        Ok(doomed.len())
136	    }
137	}
