212	impl<P, E> ProvingWitnessSource for NodeWitnessSource<P, E>
213	where
214	    P: BlockReader<Block = Block>
215	        + StateProviderFactory
216	        + HeaderProvider<Header = Header>
217	        + Send
218	        + Sync,
219	    E: ConfigureEvm<Primitives = EthPrimitives> + Send + Sync,
220	{
221	    fn block_witness(&self, number: u64) -> Result<BlockWitness, String> {
222	        match self.store.get(number) {
223	            // Reorg guard: the store is keyed by block number, so a witness
224	            // captured before a reorg can be stale. Trust the hit only if its
225	            // hash matches the current canonical block; otherwise fall through to
226	            // re-exec the canonical block by number.
227	            Ok(Some(bw)) => match self.provider.block_hash(number) {
228	                Ok(Some(canon)) if canon == bw.hash => return Ok(bw),
229	                Ok(_) => {
230	                    event!(
231	                        name: "eez.node.witness_store.stale_reorg",
232	                        Level::WARN,
233	                        number,
234	                        stored = %bw.hash,
235	                        "stored witness hash != canonical block; re-executing (reorg)",
236	                    );
237	                }
238	                Err(e) => {
239	                    event!(
240	                        name: "eez.node.witness_store.canon_hash_failed",
241	                        Level::WARN,
242	                        number,
243	                        error = %e,
244	                        "canonical hash lookup failed; re-executing on-demand",
245	                    );
246	                }
247	            },
248	            Ok(None) => {} // not captured yet → re-exec fallback below
249	            Err(e) => {
250	                // Unexpected; fall back to re-exec rather than fail the slot.
251	                event!(
252	                    name: "eez.node.witness_store.read_failed",
253	                    Level::WARN,
254	                    number,
255	                    error = %e,
256	                    "witness store read failed; falling back to on-demand re-exec",
257	                );
258	            }
259	        }
260	        build_block_witness(
261	            &self.provider,
262	            &self.evm_config,
263	            BlockHashOrNumber::Number(number),
264	        )
265	    }
