268	/// Re-execute a committed block on its parent state → augmented witness.
269	/// Blocking (trie walk); call under `spawn_blocking`.
270	fn build_block_witness<P, E>(
271	    provider: &P,
272	    evm_config: &E,
273	    id: BlockHashOrNumber,
274	) -> Result<BlockWitness, String>
275	where
276	    P: BlockReader<Block = Block> + StateProviderFactory + HeaderProvider<Header = Header>,
277	    E: ConfigureEvm<Primitives = EthPrimitives>,
278	{
279	    let block = provider
280	        .recovered_block(id, TransactionVariant::WithHash)
281	        .map_err(|e| format!("fetch block {id:?}: {e}"))?
282	        .ok_or_else(|| format!("witness for block {id:?} not captured yet"))?;
283	    // Legacy + removal-closure augmentation: the intermediate-per-tx-root nodes
284	    // the prover's re-execution needs (MPT completeness fix).
285	    block_witness(provider, evm_config, &block, ExecutionWitnessMode::Legacy)
286	        .map_err(|e| format!("witness for block {id:?}: {e}"))
287	}
