289	/// Drain committed-block hashes, capture each block's witness at commit (parent
290	/// state fresh), persist it, and purge everything the L1 has FINALIZED
291	/// (`settled_floor`). Runs until the channel closes.
292	pub async fn run_capture<P, E, F>(
293	    mut rx: mpsc::UnboundedReceiver<B256>,
294	    store: WitnessStore,
295	    provider: P,
296	    evm_config: E,
297	    settled_floor: F,
298	) where
299	    P: BlockReader<Block = Block>
300	        + StateProviderFactory
301	        + HeaderProvider<Header = Header>
302	        + Clone
303	        + Send
304	        + Sync
305	        + 'static,
306	    E: ConfigureEvm<Primitives = EthPrimitives> + Clone + Send + Sync + 'static,
307	    F: Fn() -> u64 + Send + 'static,
308	{
309	    while let Some(hash) = rx.recv().await {
310	        let provider = provider.clone();
311	        let evm_config = evm_config.clone();
312	        let built = tokio::task::spawn_blocking(move || {
313	            build_block_witness(&provider, &evm_config, BlockHashOrNumber::Hash(hash))
314	        })
315	        .await;
316	        match built {
317	            Ok(Ok(bw)) => {
318	                let number = bw.number;
319	                if let Err(e) = store.put(number, &bw) {
320	                    event!(
321	                        name: "eez.node.witness_capture.persist_failed",
322	                        Level::ERROR,
323	                        number,
324	                        error = %e,
325	                        "persisting captured witness failed",
326	                    );
327	                }
328	                // Drop finalized witnesses; cheap when nothing is below the floor.
329	                match store.purge_settled(settled_floor()) {
330	                    Ok(n) if n > 0 => event!(
331	                        name: "eez.node.witness_store.purged",
332	                        Level::DEBUG,
333	                        removed = n,
334	                        "purged finalized witnesses",
335	                    ),
336	                    Ok(_) => {}
337	                    Err(e) => event!(
338	                        name: "eez.node.witness_store.purge_failed",
339	                        Level::WARN,
340	                        error = %e,
341	                        "purging finalized witnesses failed",
342	                    ),
343	                }
344	            }
345	            Ok(Err(e)) => event!(
346	                name: "eez.node.witness_capture.failed",
347	                Level::WARN,
348	                %hash,
349	                error = %e,
350	                "witness capture failed for a committed block; composer will retry the Sync slot",
351	            ),
352	            Err(e) => event!(
353	                name: "eez.node.witness_capture.join_error",
354	                Level::ERROR,
355	                %hash,
356	                error = %e,
357	                "witness capture task panicked",
358	            ),
359	        }
360	    }
361	}
