385	    /// put → get round-trips through postcard, survives a close+reopen
386	    /// (restart), and `purge_settled` removes exactly the below-floor prefix.
387	    #[test]
388	    fn persist_get_purge_restart() {
389	        let dir = tempfile::tempdir().unwrap();
390	        for n in [10u64, 11, 12] {
