397	        let got = db.get(11).unwrap().expect("11 present after restart");
398	        assert_eq!(got.number, 11);
399	        assert_eq!(got.rlp, Bytes::from(vec![11u8; 4]));
400	        assert!(db.get(99).unwrap().is_none());
