18	///
19	/// Private fields make construction exclusive to [`verify_root_update_chain`].
20	/// Downstream effect binding can therefore use each retained entry/update pair
21	/// without repeating the nonempty and exactly-one-update checks.
22	pub(crate) struct VerifiedRootUpdateChain<'batch> {
