53	pub(crate) enum RootUpdateChainError {
54	    #[error("batch has no execution entries")]
55	    NoEntries,
56	    #[error("batch entry {entry_index} has {actual} root updates; expected exactly one")]
57	    UpdateCount { entry_index: usize, actual: usize },
58	    #[error("batch claims rollup id {claimed}; expected rollup id {expected}")]
59	    ExpectedRollupMismatch { expected: u64, claimed: u64 },
60	    #[error(
61	        "batch entry {entry_index} claims rollup id {claimed}; expected common rollup id {expected}"
62	    )]
63	    RollupMismatch {
64	        entry_index: usize,
65	        expected: u64,
66	        claimed: u64,
67	    },
68	    #[error(
69	        "leading root update claims initial commitment {claimed}; validated parent block hash is {validated}"
70	    )]
71	    InitialRootMismatch { validated: B256, claimed: B256 },
72	    #[error(
73	        "root-update chain breaks before entry {entry_index}: previous claimed block hash is {previous_claimed_block_hash}, next claimed parent hash is {next_claimed_parent_hash}"
74	    )]
75	    ChainBreak {
