77	        previous_claimed_block_hash: B256,
78	        next_claimed_parent_hash: B256,
79	    },
80	    #[error(
81	        "root-update chain claims final commitment {claimed}; validated block hash is {validated}"
82	    )]
83	    FinalMismatch { validated: B256, claimed: B256 },
84	}
