86	/// Require one claimed root update per entry, the expected rollup, and a
87	/// continuous block-hash chain between the locally validated window endpoints.
88	///
89	/// This checks continuity of Composer claims; `bind_effects_to_execution`
90	/// separately proves that the leading entry is an anchor and binds interior
91	/// commitments to prefix-block checkpoints.
92	pub(crate) fn verify_root_update_chain(
93	    batch: &CanonicalPostBatch,
94	    expected_rollup_id: NonZeroU64,
95	    validated_window_pre_block_hash: B256,
96	    validated_window_post_block_hash: B256,
97	) -> Result<VerifiedRootUpdateChain<'_>, RootUpdateChainError> {
98	    let submitted_batch = batch.as_batch();
99	    let (leading_claimed_entry, trailing_claimed_entries) =
100	        submitted_batch
101	            .entries
102	            .split_first()
103	            .ok_or(RootUpdateChainError::NoEntries)?;
104	    let leading_claimed_update = sole_update(leading_claimed_entry.rootUpdates.as_slice(), 0)?;
105	    let expected_rollup = expected_rollup_id.get();
106	    if leading_claimed_update.rollupId != expected_rollup {
107	        return Err(RootUpdateChainError::ExpectedRollupMismatch {
108	            expected: expected_rollup,
109	            claimed: leading_claimed_update.rollupId,
110	        });
111	    }
112	    if leading_claimed_update.currentRoot != validated_window_pre_block_hash {
113	        return Err(RootUpdateChainError::InitialRootMismatch {
114	            validated: validated_window_pre_block_hash,
115	            claimed: leading_claimed_update.currentRoot,
116	        });
117	    }
118	
119	    let claimed_rollup = leading_claimed_update.rollupId;
120	    let mut previous_claimed_block_hash = leading_claimed_update.newRoot;
121	    let mut verified_trailing = Vec::with_capacity(trailing_claimed_entries.len());
122	    for (entry_index, entry) in trailing_claimed_entries.iter().enumerate() {
123	        let entry_index = entry_index + 1;
124	        let claimed_update = sole_update(entry.rootUpdates.as_slice(), entry_index)?;
125	        if claimed_update.rollupId != claimed_rollup {
126	            return Err(RootUpdateChainError::RollupMismatch {
127	                entry_index,
128	                expected: claimed_rollup,
129	                claimed: claimed_update.rollupId,
130	            });
131	        }
132	        if claimed_update.currentRoot != previous_claimed_block_hash {
133	            return Err(RootUpdateChainError::ChainBreak {
134	                entry_index,
135	                previous_claimed_block_hash,
136	                next_claimed_parent_hash: claimed_update.currentRoot,
137	            });
138	        }
139	        previous_claimed_block_hash = claimed_update.newRoot;
140	        verified_trailing.push(VerifiedRootUpdateEntry {
141	            claimed_entry: entry,
142	            claimed_update,
143	        });
144	    }
145	
146	    if previous_claimed_block_hash != validated_window_post_block_hash {
147	        return Err(RootUpdateChainError::FinalMismatch {
148	            validated: validated_window_post_block_hash,
149	            claimed: previous_claimed_block_hash,
150	        });
151	    }
152	
153	    Ok(VerifiedRootUpdateChain {
154	        expected_rollup,
155	        leading: VerifiedRootUpdateEntry {
156	            claimed_entry: leading_claimed_entry,
157	            claimed_update: leading_claimed_update,
158	        },
159	        trailing: verified_trailing,
160	    })
161	}
162	
163	fn sole_update(
164	    root_updates: &[RootUpdateSol],
165	    entry_index: usize,
166	) -> Result<&RootUpdateSol, RootUpdateChainError> {
167	    let [update] = root_updates else {
168	        return Err(RootUpdateChainError::UpdateCount {
169	            entry_index,
170	            actual: root_updates.len(),
171	        });
172	    };
173	    Ok(update)
174	}
